window.DUAS=[{"id": "kursi", "color": "green", "eyebrow": "قرآن کریم · بقره ۲۵۵ تا ۲۵۷", "title": "آیت‌الکرسی", "sub": "برای پناه و آرامش؛ هر صبح و شب", "body": "<section class=\"pa\"><p class=\"q\">ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةࣱ وَلَا نَوۡمࣱۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءࣲ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ <span class=\"am\">﴿٢٥٥﴾</span> لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ <span class=\"am\">﴿٢٥٦﴾</span> ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ <span class=\"am\">﴿٢٥٧﴾</span></p>\n<p class=\"fa\">خداست که هیچ معبودی جز او نیست؛ زنده و پاینده [و نگه‌دارندهٔ همه] است. نه خوابی سبک او را فرا می‌گیرد و نه خوابی سنگین. آنچه در آسمان‌ها و آنچه در زمین است از آنِ اوست. کیست که نزد او جز به اذن او شفاعت کند؟ آنچه پیش روی آنان و آنچه پشت سرشان است می‌داند، و آنان به چیزی از علم او احاطه نمی‌یابند مگر به آنچه خود بخواهد. کرسی او آسمان‌ها و زمین را فرا گرفته است و نگهداری آن دو بر او گران نیست؛ و او بلندمرتبه و بزرگ است. <span class=\"fn\">(۲۵۵)</span> در [پذیرش] دین هیچ اجباری نیست؛ راه درست از گمراهی آشکار شده است. پس هر که به طاغوت کفر ورزد و به خدا ایمان آورد، به دستاویز استواری چنگ زده که گسستنی ندارد؛ و خدا شنوا و داناست. <span class=\"fn\">(۲۵۶)</span> خدا سرپرست کسانی است که ایمان آورده‌اند؛ آنان را از تاریکی‌ها به سوی نور بیرون می‌برد. و کسانی که کفر ورزیدند، سرپرستانشان طاغوت است که آنان را از نور به سوی تاریکی‌ها بیرون می‌برند؛ آنان اهل آتش‌اند و در آن جاودانه‌اند. <span class=\"fn\">(۲۵۷)</span></p></section><p class=\"note\">صوت‌ها فقط آیهٔ ۲۵۵ را دارند.</p><div class=\"player\"><span>🔊 آیهٔ ۲۵۵ با صدای مشاری العفاسی (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/k-afasy.mp3\"></audio></div><div class=\"player\"><span>🔊 آیهٔ ۲۵۵ با صدای یاسر الدوسری (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/k-dosari.mp3\"></audio></div><div class=\"player\"><span>🔊 آیهٔ ۲۵۵، قاری نامشخص (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/k-3.mp3\"></audio></div>"}, {"id": "qul", "color": "teal", "eyebrow": "قرآن کریم · سوره‌های اخلاص، فلق و ناس", "title": "سه قل؛ پناه‌خواهی", "sub": "معوّذتین (فلق و ناس) برای پناه بردن به خدا از هر شر", "body": "<h3>سورهٔ اخلاص</h3><section class=\"pa\"><p class=\"qbism\">بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ</p>\n<p class=\"q\">قُلۡ هُوَ ٱللَّهُ أَحَدٌ <span class=\"am\">﴿١﴾</span> ٱللَّهُ ٱلصَّمَدُ <span class=\"am\">﴿٢﴾</span> لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ <span class=\"am\">﴿٣﴾</span> وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ <span class=\"am\">﴿٤﴾</span></p>\n<p class=\"fa\">بگو: او خدای یگانه است؛ <span class=\"fn\">(۱)</span> خدای بی‌نیاز [که همه به او نیازمندند]؛ <span class=\"fn\">(۲)</span> نه زاده و نه زاده شده؛ <span class=\"fn\">(۳)</span> و هیچ کس همتای او نیست. <span class=\"fn\">(۴)</span></p></section><div class=\"player\"><span>🔊 سورهٔ اخلاص (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/q112.mp3\"></audio></div><h3>سورهٔ فلق</h3><section class=\"pa\"><p class=\"qbism\">بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ</p>\n<p class=\"q\">قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ <span class=\"am\">﴿١﴾</span> مِن شَرِّ مَا خَلَقَ <span class=\"am\">﴿٢﴾</span> وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ <span class=\"am\">﴿٣﴾</span> وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِي ٱلۡعُقَدِ <span class=\"am\">﴿٤﴾</span> وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ <span class=\"am\">﴿٥﴾</span></p>\n<p class=\"fa\">بگو: پناه می‌برم به پروردگار سپیده‌دم، <span class=\"fn\">(۱)</span> از شر آنچه آفریده است، <span class=\"fn\">(۲)</span> و از شر تاریکی شب، چون فرا رسد، <span class=\"fn\">(۳)</span> و از شر دمندگان در گره‌ها، <span class=\"fn\">(۴)</span> و از شر حسود، چون حسد ورزد. <span class=\"fn\">(۵)</span></p></section><div class=\"player\"><span>🔊 فلق با صدای ماهر المعیقلی (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/q113-maher.mp3\"></audio></div><div class=\"player\"><span>🔊 فلق با صدای یاسر الدوسری (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/q113-dosari.mp3\"></audio></div><h3>سورهٔ ناس</h3><section class=\"pa\"><p class=\"qbism\">بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ</p>\n<p class=\"q\">قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ <span class=\"am\">﴿١﴾</span> مَلِكِ ٱلنَّاسِ <span class=\"am\">﴿٢﴾</span> إِلَٰهِ ٱلنَّاسِ <span class=\"am\">﴿٣﴾</span> مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ <span class=\"am\">﴿٤﴾</span> ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ <span class=\"am\">﴿٥﴾</span> مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ <span class=\"am\">﴿٦﴾</span></p>\n<p class=\"fa\">بگو: پناه می‌برم به پروردگار مردم، <span class=\"fn\">(۱)</span> فرمانروای مردم، <span class=\"fn\">(۲)</span> معبود مردم، <span class=\"fn\">(۳)</span> از شر وسوسه‌گرِ پنهان‌شونده، <span class=\"fn\">(۴)</span> همان که در سینه‌های مردم وسوسه می‌کند، <span class=\"fn\">(۵)</span> از جنّیان و آدمیان. <span class=\"fn\">(۶)</span></p></section><div class=\"player\"><span>🔊 ناس با صدای ماهر المعیقلی (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/q114-maher.mp3\"></audio></div><div class=\"player\"><span>🔊 ناس با صدای یاسر الدوسری (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/q114-dosari.mp3\"></audio></div>"}, {"id": "yasin", "color": "green", "eyebrow": "قرآن کریم · سورهٔ ۳۶ · ۸۳ آیه", "title": "سورهٔ یاسین", "sub": "قلب قرآن؛ با متن کامل و ترجمهٔ فارسی", "body": "<div class=\"player\"><span>🔊 یاسین با صدای ماهر المعیقلی (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/q036-maher.mp3\"></audio></div><div class=\"player\"><span>🔊 یاسین با صدای یاسر الدوسری (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/q036-dosari.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">آیات ۱ تا ۱۲</span><p class=\"qbism\">بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ</p>\n<p class=\"q\">يسٓ <span class=\"am\">﴿١﴾</span> وَٱلۡقُرۡءَانِ ٱلۡحَكِيمِ <span class=\"am\">﴿٢﴾</span> إِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ <span class=\"am\">﴿٣﴾</span> عَلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ <span class=\"am\">﴿٤﴾</span> تَنزِيلَ ٱلۡعَزِيزِ ٱلرَّحِيمِ <span class=\"am\">﴿٥﴾</span> لِتُنذِرَ قَوۡمࣰا مَّآ أُنذِرَ ءَابَآؤُهُمۡ فَهُمۡ غَٰفِلُونَ <span class=\"am\">﴿٦﴾</span> لَقَدۡ حَقَّ ٱلۡقَوۡلُ عَلَىٰٓ أَكۡثَرِهِمۡ فَهُمۡ لَا يُؤۡمِنُونَ <span class=\"am\">﴿٧﴾</span> إِنَّا جَعَلۡنَا فِيٓ أَعۡنَٰقِهِمۡ أَغۡلَٰلࣰا فَهِيَ إِلَى ٱلۡأَذۡقَانِ فَهُم مُّقۡمَحُونَ <span class=\"am\">﴿٨﴾</span> وَجَعَلۡنَا مِنۢ بَيۡنِ أَيۡدِيهِمۡ سَدࣰّا وَمِنۡ خَلۡفِهِمۡ سَدࣰّا فَأَغۡشَيۡنَٰهُمۡ فَهُمۡ لَا يُبۡصِرُونَ <span class=\"am\">﴿٩﴾</span> وَسَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ <span class=\"am\">﴿١٠﴾</span> إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكۡرَ وَخَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَةࣲ وَأَجۡرࣲ كَرِيمٍ <span class=\"am\">﴿١١﴾</span> إِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ فِيٓ إِمَامࣲ مُّبِينࣲ <span class=\"am\">﴿١٢﴾</span></p>\n<p class=\"fa\">یا، سین. <span class=\"fn\">(۱)</span> سوگند به قرآنِ حکمت‌آمیز، <span class=\"fn\">(۲)</span> که تو بی‌گمان از فرستادگانی، <span class=\"fn\">(۳)</span> بر راهی راست. <span class=\"fn\">(۴)</span> [این قرآن] فرو فرستادهٔ [خدای] شکست‌ناپذیرِ مهربان است، <span class=\"fn\">(۵)</span> تا قومی را هشدار دهی که پدرانشان هشدار داده نشدند، پس آنان غافل‌اند. <span class=\"fn\">(۶)</span> به‌راستی آن سخن [عذاب] بر بیشترشان محقق شده است، پس آنان ایمان نمی‌آورند. <span class=\"fn\">(۷)</span> ما در گردن‌هایشان غل‌هایی نهادیم که تا چانه‌هایشان می‌رسد، پس سرهایشان رو به بالا مانده است. <span class=\"fn\">(۸)</span> و پیش رویشان سدّی و پشت سرشان سدّی نهادیم و [چشمانشان را] پوشاندیم، پس نمی‌بینند. <span class=\"fn\">(۹)</span> و برایشان یکسان است که هشدارشان دهی یا هشدارشان ندهی؛ ایمان نمی‌آورند. <span class=\"fn\">(۱۰)</span> تنها کسی را [به‌راستی] هشدار می‌دهی که از این یادآوری پیروی کند و در نهان از [خدای] رحمان بترسد؛ پس او را به آمرزش و پاداشی ارجمند مژده بده. <span class=\"fn\">(۱۱)</span> به‌راستی ماییم که مردگان را زنده می‌کنیم، و آنچه را پیش فرستاده‌اند و آثارشان را می‌نویسیم؛ و همه چیز را در کتابی روشن برشمرده‌ایم. <span class=\"fn\">(۱۲)</span></p></section><section class=\"pa\"><span class=\"n\">آیات ۱۳ تا ۳۲</span><p class=\"q\">وَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَٰبَ ٱلۡقَرۡيَةِ إِذۡ جَآءَهَا ٱلۡمُرۡسَلُونَ <span class=\"am\">﴿١٣﴾</span> إِذۡ أَرۡسَلۡنَآ إِلَيۡهِمُ ٱثۡنَيۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِثࣲ فَقَالُوٓاْ إِنَّآ إِلَيۡكُم مُّرۡسَلُونَ <span class=\"am\">﴿١٤﴾</span> قَالُواْ مَآ أَنتُمۡ إِلَّا بَشَرࣱ مِّثۡلُنَا وَمَآ أَنزَلَ ٱلرَّحۡمَٰنُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا تَكۡذِبُونَ <span class=\"am\">﴿١٥﴾</span> قَالُواْ رَبُّنَا يَعۡلَمُ إِنَّآ إِلَيۡكُمۡ لَمُرۡسَلُونَ <span class=\"am\">﴿١٦﴾</span> وَمَا عَلَيۡنَآ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ <span class=\"am\">﴿١٧﴾</span> قَالُوٓاْ إِنَّا تَطَيَّرۡنَا بِكُمۡۖ لَئِن لَّمۡ تَنتَهُواْ لَنَرۡجُمَنَّكُمۡ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمࣱ <span class=\"am\">﴿١٨﴾</span> قَالُواْ طَٰٓئِرُكُم مَّعَكُمۡ أَئِن ذُكِّرۡتُمۚ بَلۡ أَنتُمۡ قَوۡمࣱ مُّسۡرِفُونَ <span class=\"am\">﴿١٩﴾</span> وَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ رَجُلࣱ يَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ <span class=\"am\">﴿٢٠﴾</span> ٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرࣰا وَهُم مُّهۡتَدُونَ <span class=\"am\">﴿٢١﴾</span> وَمَا لِيَ لَآ أَعۡبُدُ ٱلَّذِي فَطَرَنِي وَإِلَيۡهِ تُرۡجَعُونَ <span class=\"am\">﴿٢٢﴾</span> ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدۡنِ ٱلرَّحۡمَٰنُ بِضُرࣲّ لَّا تُغۡنِ عَنِّي شَفَٰعَتُهُمۡ شَيۡـࣰٔا وَلَا يُنقِذُونِ <span class=\"am\">﴿٢٣﴾</span> إِنِّيٓ إِذࣰا لَّفِي ضَلَٰلࣲ مُّبِينٍ <span class=\"am\">﴿٢٤﴾</span> إِنِّيٓ ءَامَنتُ بِرَبِّكُمۡ فَٱسۡمَعُونِ <span class=\"am\">﴿٢٥﴾</span> قِيلَ ٱدۡخُلِ ٱلۡجَنَّةَۖ قَالَ يَٰلَيۡتَ قَوۡمِي يَعۡلَمُونَ <span class=\"am\">﴿٢٦﴾</span> بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ ٱلۡمُكۡرَمِينَ <span class=\"am\">﴿٢٧﴾</span> ۞ وَمَآ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندࣲ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ <span class=\"am\">﴿٢٨﴾</span> إِن كَانَتۡ إِلَّا صَيۡحَةࣰ وَٰحِدَةࣰ فَإِذَا هُمۡ خَٰمِدُونَ <span class=\"am\">﴿٢٩﴾</span> يَٰحَسۡرَةً عَلَى ٱلۡعِبَادِۚ مَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ <span class=\"am\">﴿٣٠﴾</span> أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ أَنَّهُمۡ إِلَيۡهِمۡ لَا يَرۡجِعُونَ <span class=\"am\">﴿٣١﴾</span> وَإِن كُلࣱّ لَّمَّا جَمِيعࣱ لَّدَيۡنَا مُحۡضَرُونَ <span class=\"am\">﴿٣٢﴾</span></p>\n<p class=\"fa\">و برای آنان مَثَلِ اهل آن شهر را بیاور، آن‌گاه که فرستادگان به آنجا آمدند؛ <span class=\"fn\">(۱۳)</span> آن‌گاه که دو تن را به سویشان فرستادیم و آن دو را دروغگو شمردند، پس با سومی [آنان را] نیرو دادیم؛ و گفتند: «ما به سوی شما فرستاده شده‌ایم.» <span class=\"fn\">(۱۴)</span> گفتند: «شما جز بشری مانند ما نیستید، و [خدای] رحمان چیزی فرو نفرستاده است؛ شما جز دروغ نمی‌گویید.» <span class=\"fn\">(۱۵)</span> گفتند: «پروردگارمان می‌داند که ما به‌راستی به سوی شما فرستاده شده‌ایم، <span class=\"fn\">(۱۶)</span> و بر ما جز رساندنِ آشکار [پیام] نیست.» <span class=\"fn\">(۱۷)</span> گفتند: «ما شما را به فال بد گرفته‌ایم؛ اگر دست برندارید، حتماً سنگسارتان می‌کنیم و قطعاً عذابی دردناک از ما به شما خواهد رسید.» <span class=\"fn\">(۱۸)</span> گفتند: «فال بدِ شما با خودتان است. آیا اگر پندتان دهند [چنین می‌کنید]؟ بلکه شما قومی زیاده‌روید.» <span class=\"fn\">(۱۹)</span> و مردی از دورترین نقطهٔ شهر شتابان آمد [و] گفت: «ای قوم من، از این فرستادگان پیروی کنید؛ <span class=\"fn\">(۲۰)</span> از کسانی پیروی کنید که از شما مزدی نمی‌خواهند و خود هدایت‌یافته‌اند. <span class=\"fn\">(۲۱)</span> و چرا کسی را نپرستم که مرا آفریده است، و به سوی او بازگردانده می‌شوید؟ <span class=\"fn\">(۲۲)</span> آیا به جای او معبودانی بگیرم که اگر [خدای] رحمان برایم زیانی بخواهد، شفاعتشان هیچ سودی به من نرساند و نجاتم ندهند؟ <span class=\"fn\">(۲۳)</span> در آن صورت من بی‌گمان در گمراهی آشکاری خواهم بود. <span class=\"fn\">(۲۴)</span> من به پروردگارتان ایمان آوردم؛ پس [سخن] مرا بشنوید.» <span class=\"fn\">(۲۵)</span> [به او] گفته شد: «به بهشت درآی.» گفت: «ای کاش قوم من می‌دانستند <span class=\"fn\">(۲۶)</span> که پروردگارم مرا آمرزید و از گرامی‌داشتگان قرارم داد.» <span class=\"fn\">(۲۷)</span> و پس از او بر قومش هیچ سپاهی از آسمان فرو نفرستادیم، و فرو فرستنده [چنین سپاهی] نبودیم. <span class=\"fn\">(۲۸)</span> تنها یک بانگ بود و ناگهان همه خاموش [و بی‌جان] شدند. <span class=\"fn\">(۲۹)</span> دریغ بر این بندگان! هیچ فرستاده‌ای به سویشان نمی‌آمد مگر آنکه او را ریشخند می‌کردند. <span class=\"fn\">(۳۰)</span> آیا ندیده‌اند چه بسیار نسل‌ها را پیش از آنان نابود کردیم، که آنان دیگر به سوی اینان باز نمی‌گردند؟ <span class=\"fn\">(۳۱)</span> و همهٔ آنان بی‌استثنا نزد ما حاضر خواهند شد. <span class=\"fn\">(۳۲)</span></p></section><section class=\"pa\"><span class=\"n\">آیات ۳۳ تا ۵۰</span><p class=\"q\">وَءَايَةࣱ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَيۡتَةُ أَحۡيَيۡنَٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبࣰّا فَمِنۡهُ يَأۡكُلُونَ <span class=\"am\">﴿٣٣﴾</span> وَجَعَلۡنَا فِيهَا جَنَّٰتࣲ مِّن نَّخِيلࣲ وَأَعۡنَٰبࣲ وَفَجَّرۡنَا فِيهَا مِنَ ٱلۡعُيُونِ <span class=\"am\">﴿٣٤﴾</span> لِيَأۡكُلُواْ مِن ثَمَرِهِۦ وَمَا عَمِلَتۡهُ أَيۡدِيهِمۡۚ أَفَلَا يَشۡكُرُونَ <span class=\"am\">﴿٣٥﴾</span> سُبۡحَٰنَ ٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا يَعۡلَمُونَ <span class=\"am\">﴿٣٦﴾</span> وَءَايَةࣱ لَّهُمُ ٱلَّيۡلُ نَسۡلَخُ مِنۡهُ ٱلنَّهَارَ فَإِذَا هُم مُّظۡلِمُونَ <span class=\"am\">﴿٣٧﴾</span> وَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرࣲّ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ <span class=\"am\">﴿٣٨﴾</span> وَٱلۡقَمَرَ قَدَّرۡنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِيمِ <span class=\"am\">﴿٣٩﴾</span> لَا ٱلشَّمۡسُ يَنۢبَغِي لَهَآ أَن تُدۡرِكَ ٱلۡقَمَرَ وَلَا ٱلَّيۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلࣱّ فِي فَلَكࣲ يَسۡبَحُونَ <span class=\"am\">﴿٤٠﴾</span> وَءَايَةࣱ لَّهُمۡ أَنَّا حَمَلۡنَا ذُرِّيَّتَهُمۡ فِي ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ <span class=\"am\">﴿٤١﴾</span> وَخَلَقۡنَا لَهُم مِّن مِّثۡلِهِۦ مَا يَرۡكَبُونَ <span class=\"am\">﴿٤٢﴾</span> وَإِن نَّشَأۡ نُغۡرِقۡهُمۡ فَلَا صَرِيخَ لَهُمۡ وَلَا هُمۡ يُنقَذُونَ <span class=\"am\">﴿٤٣﴾</span> إِلَّا رَحۡمَةࣰ مِّنَّا وَمَتَٰعًا إِلَىٰ حِينࣲ <span class=\"am\">﴿٤٤﴾</span> وَإِذَا قِيلَ لَهُمُ ٱتَّقُواْ مَا بَيۡنَ أَيۡدِيكُمۡ وَمَا خَلۡفَكُمۡ لَعَلَّكُمۡ تُرۡحَمُونَ <span class=\"am\">﴿٤٥﴾</span> وَمَا تَأۡتِيهِم مِّنۡ ءَايَةࣲ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ <span class=\"am\">﴿٤٦﴾</span> وَإِذَا قِيلَ لَهُمۡ أَنفِقُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَنُطۡعِمُ مَن لَّوۡ يَشَآءُ ٱللَّهُ أَطۡعَمَهُۥٓ إِنۡ أَنتُمۡ إِلَّا فِي ضَلَٰلࣲ مُّبِينࣲ <span class=\"am\">﴿٤٧﴾</span> وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ <span class=\"am\">﴿٤٨﴾</span> مَا يَنظُرُونَ إِلَّا صَيۡحَةࣰ وَٰحِدَةࣰ تَأۡخُذُهُمۡ وَهُمۡ يَخِصِّمُونَ <span class=\"am\">﴿٤٩﴾</span> فَلَا يَسۡتَطِيعُونَ تَوۡصِيَةࣰ وَلَآ إِلَىٰٓ أَهۡلِهِمۡ يَرۡجِعُونَ <span class=\"am\">﴿٥٠﴾</span></p>\n<p class=\"fa\">و نشانه‌ای برای آنان، زمینِ مرده است که آن را زنده کردیم و از آن دانه بیرون آوردیم که از آن می‌خورند. <span class=\"fn\">(۳۳)</span> و در آن باغ‌هایی از درختان خرما و انگور پدید آوردیم و چشمه‌هایی در آن روان ساختیم، <span class=\"fn\">(۳۴)</span> تا از میوهٔ آن بخورند، در حالی که دست‌هایشان آن را نساخته است؛ پس آیا سپاس نمی‌گزارند؟ <span class=\"fn\">(۳۵)</span> پاک و منزّه است آن [خدایی] که همهٔ جفت‌ها را آفرید؛ از آنچه زمین می‌رویاند و از خودشان و از آنچه نمی‌دانند. <span class=\"fn\">(۳۶)</span> و نشانه‌ای برای آنان، شب است که روز را از آن برمی‌کَنیم، پس ناگهان در تاریکی فرو می‌روند. <span class=\"fn\">(۳۷)</span> و خورشید به سوی قرارگاهی که برای اوست روان است؛ این اندازه‌گیری [خدای] شکست‌ناپذیرِ داناست. <span class=\"fn\">(۳۸)</span> و برای ماه منزل‌هایی معیّن کردیم، تا آنکه [در پایان] مانند شاخهٔ کهنهٔ خوشهٔ خرما [باریک و خمیده] بازگردد. <span class=\"fn\">(۳۹)</span> نه خورشید را سزد که به ماه برسد، و نه شب بر روز پیشی گیرد؛ و هر یک در مداری شناورند. <span class=\"fn\">(۴۰)</span> و نشانه‌ای برای آنان اینکه ما نسلشان را در کشتیِ پُربار سوار کردیم، <span class=\"fn\">(۴۱)</span> و برایشان همانند آن، چیزهایی آفریدیم که بر آن سوار می‌شوند. <span class=\"fn\">(۴۲)</span> و اگر بخواهیم غرقشان می‌کنیم؛ آن‌گاه نه فریادرسی دارند و نه رهانیده می‌شوند، <span class=\"fn\">(۴۳)</span> مگر به رحمتی از ما، و برای بهره‌مندی تا زمانی معیّن. <span class=\"fn\">(۴۴)</span> و چون به آنان گفته شود: «از آنچه پیش روی شما و آنچه پشت سرتان است پروا کنید، باشد که مورد رحمت قرار گیرید» [روی می‌گردانند]. <span class=\"fn\">(۴۵)</span> و هیچ نشانه‌ای از نشانه‌های پروردگارشان برایشان نمی‌آید مگر آنکه از آن روی‌گردان‌اند. <span class=\"fn\">(۴۶)</span> و چون به آنان گفته شود: «از آنچه خدا روزی‌تان کرده انفاق کنید»، کافران به مؤمنان می‌گویند: «آیا کسی را غذا دهیم که اگر خدا می‌خواست خودش غذایش می‌داد؟ شما جز در گمراهی آشکار نیستید.» <span class=\"fn\">(۴۷)</span> و می‌گویند: «اگر راست می‌گویید، این وعده کی خواهد بود؟» <span class=\"fn\">(۴۸)</span> جز یک بانگ را انتظار نمی‌کشند که آنان را فرو می‌گیرد، در حالی که با هم در کشمکش‌اند. <span class=\"fn\">(۴۹)</span> پس نه می‌توانند وصیتی کنند و نه به سوی خانواده‌شان بازمی‌گردند. <span class=\"fn\">(۵۰)</span></p></section><section class=\"pa\"><span class=\"n\">آیات ۵۱ تا ۶۷</span><p class=\"q\">وَنُفِخَ فِي ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلۡأَجۡدَاثِ إِلَىٰ رَبِّهِمۡ يَنسِلُونَ <span class=\"am\">﴿٥١﴾</span> قَالُواْ يَٰوَيۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜۗ هَٰذَا مَا وَعَدَ ٱلرَّحۡمَٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ <span class=\"am\">﴿٥٢﴾</span> إِن كَانَتۡ إِلَّا صَيۡحَةࣰ وَٰحِدَةࣰ فَإِذَا هُمۡ جَمِيعࣱ لَّدَيۡنَا مُحۡضَرُونَ <span class=\"am\">﴿٥٣﴾</span> فَٱلۡيَوۡمَ لَا تُظۡلَمُ نَفۡسࣱ شَيۡـࣰٔا وَلَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ <span class=\"am\">﴿٥٤﴾</span> إِنَّ أَصۡحَٰبَ ٱلۡجَنَّةِ ٱلۡيَوۡمَ فِي شُغُلࣲ فَٰكِهُونَ <span class=\"am\">﴿٥٥﴾</span> هُمۡ وَأَزۡوَٰجُهُمۡ فِي ظِلَٰلٍ عَلَى ٱلۡأَرَآئِكِ مُتَّكِـُٔونَ <span class=\"am\">﴿٥٦﴾</span> لَهُمۡ فِيهَا فَٰكِهَةࣱ وَلَهُم مَّا يَدَّعُونَ <span class=\"am\">﴿٥٧﴾</span> سَلَٰمࣱ قَوۡلࣰا مِّن رَّبࣲّ رَّحِيمࣲ <span class=\"am\">﴿٥٨﴾</span> وَٱمۡتَٰزُواْ ٱلۡيَوۡمَ أَيُّهَا ٱلۡمُجۡرِمُونَ <span class=\"am\">﴿٥٩﴾</span> ۞ أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِينࣱ <span class=\"am\">﴿٦٠﴾</span> وَأَنِ ٱعۡبُدُونِيۚ هَٰذَا صِرَٰطࣱ مُّسۡتَقِيمࣱ <span class=\"am\">﴿٦١﴾</span> وَلَقَدۡ أَضَلَّ مِنكُمۡ جِبِلࣰّا كَثِيرًاۖ أَفَلَمۡ تَكُونُواْ تَعۡقِلُونَ <span class=\"am\">﴿٦٢﴾</span> هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي كُنتُمۡ تُوعَدُونَ <span class=\"am\">﴿٦٣﴾</span> ٱصۡلَوۡهَا ٱلۡيَوۡمَ بِمَا كُنتُمۡ تَكۡفُرُونَ <span class=\"am\">﴿٦٤﴾</span> ٱلۡيَوۡمَ نَخۡتِمُ عَلَىٰٓ أَفۡوَٰهِهِمۡ وَتُكَلِّمُنَآ أَيۡدِيهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم بِمَا كَانُواْ يَكۡسِبُونَ <span class=\"am\">﴿٦٥﴾</span> وَلَوۡ نَشَآءُ لَطَمَسۡنَا عَلَىٰٓ أَعۡيُنِهِمۡ فَٱسۡتَبَقُواْ ٱلصِّرَٰطَ فَأَنَّىٰ يُبۡصِرُونَ <span class=\"am\">﴿٦٦﴾</span> وَلَوۡ نَشَآءُ لَمَسَخۡنَٰهُمۡ عَلَىٰ مَكَانَتِهِمۡ فَمَا ٱسۡتَطَٰعُواْ مُضِيࣰّا وَلَا يَرۡجِعُونَ <span class=\"am\">﴿٦٧﴾</span></p>\n<p class=\"fa\">و در صور دمیده شود، پس ناگهان از گورها شتابان به سوی پروردگارشان روان می‌شوند. <span class=\"fn\">(۵۱)</span> می‌گویند: «وای بر ما! چه کسی ما را از خوابگاهمان برانگیخت؟» [پاسخ آید:] «این همان است که [خدای] رحمان وعده داده بود، و فرستادگان راست گفتند.» <span class=\"fn\">(۵۲)</span> تنها یک بانگ است، و ناگهان همه نزد ما حاضر می‌شوند. <span class=\"fn\">(۵۳)</span> پس امروز به هیچ کس ذرّه‌ای ستم نمی‌شود، و جز در برابر آنچه می‌کردید جزا داده نمی‌شوید. <span class=\"fn\">(۵۴)</span> به‌راستی اهل بهشت امروز سرگرم [نعمت‌ها] و شادمان‌اند؛ <span class=\"fn\">(۵۵)</span> آنان و همسرانشان در سایه‌ها بر تخت‌ها تکیه زده‌اند. <span class=\"fn\">(۵۶)</span> در آنجا برایشان میوه‌ای هست و هرچه بخواهند برایشان فراهم است. <span class=\"fn\">(۵۷)</span> «سلام»؛ سخنی از سوی پروردگاری مهربان. <span class=\"fn\">(۵۸)</span> و [گفته شود:] «ای گنهکاران، امروز [از مؤمنان] جدا شوید! <span class=\"fn\">(۵۹)</span> ای فرزندان آدم، آیا با شما پیمان نبستم که شیطان را نپرستید، که او برای شما دشمنی آشکار است؟ <span class=\"fn\">(۶۰)</span> و اینکه مرا بپرستید؛ این است راه راست. <span class=\"fn\">(۶۱)</span> و به‌راستی گروه بسیاری از شما را گمراه کرد؛ آیا نمی‌اندیشیدید؟ <span class=\"fn\">(۶۲)</span> این همان دوزخی است که به شما وعده داده می‌شد. <span class=\"fn\">(۶۳)</span> امروز به سزای آنکه کفر می‌ورزیدید، در آن درآیید [و سوزش آن را بچشید].» <span class=\"fn\">(۶۴)</span> امروز بر دهان‌هایشان مُهر می‌نهیم، و دست‌هایشان با ما سخن می‌گویند و پاهایشان به آنچه می‌کردند گواهی می‌دهند. <span class=\"fn\">(۶۵)</span> و اگر بخواهیم چشمانشان را محو می‌کنیم؛ آن‌گاه [برای یافتن] راه بر هم پیشی می‌گیرند، اما چگونه ببینند؟ <span class=\"fn\">(۶۶)</span> و اگر بخواهیم آنان را در جای خودشان مسخ می‌کنیم، تا نه بتوانند پیش بروند و نه بازگردند. <span class=\"fn\">(۶۷)</span></p></section><section class=\"pa\"><span class=\"n\">آیات ۶۸ تا ۸۳</span><p class=\"q\">وَمَن نُّعَمِّرۡهُ نُنَكِّسۡهُ فِي ٱلۡخَلۡقِۚ أَفَلَا يَعۡقِلُونَ <span class=\"am\">﴿٦٨﴾</span> وَمَا عَلَّمۡنَٰهُ ٱلشِّعۡرَ وَمَا يَنۢبَغِي لَهُۥٓۚ إِنۡ هُوَ إِلَّا ذِكۡرࣱ وَقُرۡءَانࣱ مُّبِينࣱ <span class=\"am\">﴿٦٩﴾</span> لِّيُنذِرَ مَن كَانَ حَيࣰّا وَيَحِقَّ ٱلۡقَوۡلُ عَلَى ٱلۡكَٰفِرِينَ <span class=\"am\">﴿٧٠﴾</span> أَوَلَمۡ يَرَوۡاْ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَيۡدِينَآ أَنۡعَٰمࣰا فَهُمۡ لَهَا مَٰلِكُونَ <span class=\"am\">﴿٧١﴾</span> وَذَلَّلۡنَٰهَا لَهُمۡ فَمِنۡهَا رَكُوبُهُمۡ وَمِنۡهَا يَأۡكُلُونَ <span class=\"am\">﴿٧٢﴾</span> وَلَهُمۡ فِيهَا مَنَٰفِعُ وَمَشَارِبُۚ أَفَلَا يَشۡكُرُونَ <span class=\"am\">﴿٧٣﴾</span> وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةࣰ لَّعَلَّهُمۡ يُنصَرُونَ <span class=\"am\">﴿٧٤﴾</span> لَا يَسۡتَطِيعُونَ نَصۡرَهُمۡ وَهُمۡ لَهُمۡ جُندࣱ مُّحۡضَرُونَ <span class=\"am\">﴿٧٥﴾</span> فَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّا نَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ <span class=\"am\">﴿٧٦﴾</span> أَوَلَمۡ يَرَ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن نُّطۡفَةࣲ فَإِذَا هُوَ خَصِيمࣱ مُّبِينࣱ <span class=\"am\">﴿٧٧﴾</span> وَضَرَبَ لَنَا مَثَلࣰا وَنَسِيَ خَلۡقَهُۥۖ قَالَ مَن يُحۡيِ ٱلۡعِظَٰمَ وَهِيَ رَمِيمࣱ <span class=\"am\">﴿٧٨﴾</span> قُلۡ يُحۡيِيهَا ٱلَّذِيٓ أَنشَأَهَآ أَوَّلَ مَرَّةࣲۖ وَهُوَ بِكُلِّ خَلۡقٍ عَلِيمٌ <span class=\"am\">﴿٧٩﴾</span> ٱلَّذِي جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارࣰا فَإِذَآ أَنتُم مِّنۡهُ تُوقِدُونَ <span class=\"am\">﴿٨٠﴾</span> أَوَلَيۡسَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۚ بَلَىٰ وَهُوَ ٱلۡخَلَّٰقُ ٱلۡعَلِيمُ <span class=\"am\">﴿٨١﴾</span> إِنَّمَآ أَمۡرُهُۥٓ إِذَآ أَرَادَ شَيۡـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ <span class=\"am\">﴿٨٢﴾</span> فَسُبۡحَٰنَ ٱلَّذِي بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءࣲ وَإِلَيۡهِ تُرۡجَعُونَ <span class=\"am\">﴿٨٣﴾</span></p>\n<p class=\"fa\">و هر که را عمر طولانی دهیم، در آفرینش واژگونه‌اش می‌کنیم [و توانش را بازمی‌ستانیم]؛ آیا نمی‌اندیشند؟ <span class=\"fn\">(۶۸)</span> و ما به او [پیامبر] شعر نیاموختیم و سزاوار او هم نیست؛ این [کتاب] جز یادآوری و قرآنی روشن نیست، <span class=\"fn\">(۶۹)</span> تا هر که را زنده [دل] است هشدار دهد، و سخن [عذاب] بر کافران محقق شود. <span class=\"fn\">(۷۰)</span> آیا ندیده‌اند که ما از آنچه دست‌های [قدرت] ما ساخته است، چهارپایانی برایشان آفریدیم که آنان مالکشان هستند؟ <span class=\"fn\">(۷۱)</span> و آنها را رامشان کردیم؛ پس بر برخی سوار می‌شوند و از برخی می‌خورند. <span class=\"fn\">(۷۲)</span> و برایشان در آنها سودها و نوشیدنی‌هاست؛ پس آیا سپاس نمی‌گزارند؟ <span class=\"fn\">(۷۳)</span> و به جای خدا معبودانی گرفتند، به امید آنکه یاری شوند. <span class=\"fn\">(۷۴)</span> [آن معبودان] نمی‌توانند یاری‌شان کنند، و [در قیامت] آنان برای آن معبودان سپاهی احضارشده‌اند. <span class=\"fn\">(۷۵)</span> پس سخنشان تو را اندوهگین نکند؛ ما آنچه را پنهان می‌کنند و آنچه را آشکار می‌کنند می‌دانیم. <span class=\"fn\">(۷۶)</span> آیا انسان ندیده است که ما او را از نطفه‌ای آفریدیم، و ناگهان ستیزه‌جویی آشکار شده است؟ <span class=\"fn\">(۷۷)</span> و برای ما مَثَلی زد و آفرینش خود را فراموش کرد؛ گفت: «چه کسی این استخوان‌ها را زنده می‌کند در حالی که پوسیده‌اند؟» <span class=\"fn\">(۷۸)</span> بگو: «همان کسی آنها را زنده می‌کند که نخستین بار پدیدشان آورد، و او به هر آفرینشی داناست.» <span class=\"fn\">(۷۹)</span> همان که برایتان از درخت سبز آتش پدید آورد، و شما از آن آتش می‌افروزید. <span class=\"fn\">(۸۰)</span> آیا کسی که آسمان‌ها و زمین را آفرید، توانا نیست که همانند آنان را بیافریند؟ آری، و اوست آفرینندهٔ دانا. <span class=\"fn\">(۸۱)</span> فرمان او چون چیزی را بخواهد، تنها این است که به آن می‌گوید: «باش»، پس [بی‌درنگ] موجود می‌شود. <span class=\"fn\">(۸۲)</span> پس پاک و منزّه است آن [خدایی] که فرمانروایی هر چیزی به دست اوست، و به سوی او بازگردانده می‌شوید. <span class=\"fn\">(۸۳)</span></p></section>"}, {"id": "arsh", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۳", "title": "درود بر حاملان عرش و فرشتگان مقرّب", "sub": "جبرئیل، میکائیل، اسرافیل و همهٔ فرشتگان", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي الصَّلَاةِ عَلَى حَمَلَةِ الْعَرْشِ وَكُلِّ مَلَكٍ مُقَرَّبٍ</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) در درود فرستادن بر حاملان عرش و هر فرشتهٔ مقرّب</p><div class=\"player\"><span>🔊 دعای حاملان عرش (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/dua3.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">اللَّهُمَّ وَحَمَلَةُ عَرْشِكَ الَّذِينَ لَا يَفْتُرُونَ مِنْ تَسْبِيحِكَ، وَلَا يَسْأَمُونَ مِنْ تَقْدِيسِكَ، وَلَا يَسْتَحْسِرُونَ مِنْ عِبَادَتِكَ، وَلَا يُؤْثِرُونَ التَّقْصِيرَ عَلَى الْجِدِّ فِي أَمْرِكَ، وَلَا يَغْفُلُونَ عَنِ الْوَلَهِ إِلَيْكَ؛</p><p class=\"fa\">خدایا، و حاملان عرشت؛ آنان که از تسبیح تو سست نمی‌شوند، از تقدیس تو ملول نمی‌گردند، از عبادتت درمانده نمی‌شوند، کوتاهی را بر کوشش در فرمانت برنمی‌گزینند، و از شیفتگی به تو غافل نمی‌شوند؛</p></section>\n<section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">وَ<span class=\"name\">إِسْرَافِيلُ</span> صَاحِبُ الصُّورِ، الشَّاخِصُ الَّذِي يَنْتَظِرُ مِنْكَ الْإِذْنَ وَحُلُولَ الْأَمْرِ، فَيُنَبِّهُ بِالنَّفْخَةِ صَرْعَى رَهَائِنِ الْقُبُورِ؛</p><p class=\"fa\">و <span class=\"name\">اسرافیل</span>، صاحب صور، که چشم دوخته و منتظر اذن تو و فرا رسیدن فرمان است، تا با دمیدن [در صور] به‌خاک‌افتادگانی را که در گروِ گورها هستند بیدار کند؛</p></section>\n<section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">وَ<span class=\"name\">مِيكَائِيلُ</span> ذُو الْجَاهِ عِنْدَكَ، وَالْمَكَانِ الرَّفِيعِ مِنْ طَاعَتِكَ؛</p><p class=\"fa\">و <span class=\"name\">میکائیل</span>، که نزد تو آبرومند است و در فرمانبری از تو جایگاهی بلند دارد؛</p></section>\n<section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">وَ<span class=\"name\">جِبْرِيلُ</span> الْأَمِينُ عَلَى وَحْيِكَ، الْمُطَاعُ فِي أَهْلِ سَمَاوَاتِكَ، الْمَكِينُ لَدَيْكَ، الْمُقَرَّبُ عِنْدَكَ؛ وَالرُّوحُ الَّذِي هُوَ عَلَى مَلَائِكَةِ الْحُجُبِ، وَالرُّوحُ الَّذِي هُوَ مِنْ أَمْرِكَ؛</p><p class=\"fa\">و <span class=\"name\">جبرئیل</span>، امینِ وحی تو، که در میان اهل آسمان‌هایت فرمانش برده می‌شود، نزد تو صاحب‌منزلت و مقرّب است؛ و روح، که بر فرشتگانِ حجاب‌ها [گمارده] است؛ و روح، که از امر توست؛</p></section>\n<section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">فَصَلِّ عَلَيْهِمْ، وَعَلَى الْمَلَائِكَةِ الَّذِينَ مِنْ دُونِهِمْ مِنْ سُكَّانِ سَمَاوَاتِكَ، وَأَهْلِ الْأَمَانَةِ عَلَى رِسَالَاتِكَ، وَالَّذِينَ لَا تَدْخُلُهُمْ سَأْمَةٌ مِنْ دُؤُوبٍ، وَلَا إِعْيَاءٌ مِنْ لُغُوبٍ وَلَا فُتُورٌ، وَلَا تَشْغَلُهُمْ عَنْ تَسْبِيحِكَ الشَّهَوَاتُ، وَلَا يَقْطَعُهُمْ عَنْ تَعْظِيمِكَ سَهْوُ الْغَفَلَاتِ؛</p><p class=\"fa\">پس بر آنان درود فرست؛ و بر فرشتگانی که پایین‌تر از ایشان‌اند، از ساکنان آسمان‌هایت و امانت‌داران پیام‌هایت؛ و آنان که نه از کوشش پیوسته ملالی به ایشان راه می‌یابد، نه از رنج درماندگی‌ای و نه سستی‌ای؛ خواهش‌ها آنان را از تسبیحت باز نمی‌دارد، و فراموشیِ ناشی از غفلت، آنان را از بزرگداشت تو جدا نمی‌کند؛</p></section>\n<section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">الْخُشَّعُ الْأَبْصَارِ فَلَا يَرُومُونَ النَّظَرَ إِلَيْكَ، النَّوَاكِسُ الْأَذْقَانِ، الَّذِينَ قَدْ طَالَتْ رَغْبَتُهُمْ فِيمَا لَدَيْكَ، الْمُسْتَهْتَرُونَ بِذِكْرِ آلَائِكَ، وَالْمُتَوَاضِعُونَ دُونَ عَظَمَتِكَ وَجَلَالِ كِبْرِيَائِكَ؛ وَالَّذِينَ يَقُولُونَ إِذَا نَظَرُوا إِلَى جَهَنَّمَ تَزْفِرُ عَلَى أَهْلِ مَعْصِيَتِكَ: <span class=\"q\">سُبْحَانَكَ مَا عَبَدْنَاكَ حَقَّ عِبَادَتِكَ</span>.</p><p class=\"fa\">چشم‌هایشان از خشوع فروافتاده است و آهنگِ نگریستن به تو نمی‌کنند؛ سرها به زیر افکنده‌اند؛ آنان که شوقشان به آنچه نزد توست به درازا کشیده است؛ شیفتهٔ یاد نعمت‌هایت‌اند؛ و در برابر عظمت تو و شکوه کبریایی‌ات فروتن‌اند؛ و آنان که چون به دوزخ می‌نگرند که بر اهل نافرمانی‌ات می‌خروشد، می‌گویند: <span class=\"q\">«پاک و منزّهی تو! تو را چنان‌که سزاوار پرستش توست نپرستیدیم.»</span></p></section>\n<section class=\"pa\"><span class=\"n\">۷</span><p class=\"ar\">فَصَلِّ عَلَيْهِمْ وَعَلَى الرَّوْحَانِيِّينَ مِنْ مَلَائِكَتِكَ، وَأَهْلِ الزُّلْفَةِ عِنْدَكَ، وَحُمَّالِ الْغَيْبِ إِلَى رُسُلِكَ، وَالْمُؤْتَمَنِينَ عَلَى وَحْيِكَ؛ وَقَبَائِلِ الْمَلَائِكَةِ الَّذِينَ اخْتَصَصْتَهُمْ لِنَفْسِكَ، وَأَغْنَيْتَهُمْ عَنِ الطَّعَامِ وَالشَّرَابِ بِتَقْدِيسِكَ، وَأَسْكَنْتَهُمْ بُطُونَ أَطْبَاقِ سَمَاوَاتِكَ؛</p><p class=\"fa\">پس بر آنان درود فرست؛ و بر فرشتگانِ روحانیِ خود، و مقرّبان درگاهت، و رسانندگان غیب به پیامبرانت، و امینان وحی‌ات؛ و بر گروه‌های فرشتگان که آنان را ویژهٔ خود ساختی، و با تقدیس خویش از خوراک و نوشیدنی بی‌نیازشان کردی، و در درون طبقه‌های آسمان‌هایت جایشان دادی؛</p></section>\n<section class=\"pa\"><span class=\"n\">۸</span><p class=\"ar\">وَالَّذِينَ عَلَى أَرْجَائِهَا إِذَا نَزَلَ الْأَمْرُ بِتَمَامِ وَعْدِكَ؛ وَخُزَّانِ الْمَطَرِ، وَزَوَاجِرِ السَّحَابِ، وَالَّذِي بِصَوْتِ زَجْرِهِ يُسْمَعُ زَجَلُ الرُّعُودِ، وَإِذَا سَبَحَتْ بِهِ حَفِيفَةُ السَّحَابِ الْتَمَعَتْ صَوَاعِقُ الْبُرُوقِ؛ وَمُشَيِّعِي الثَّلْجِ وَالْبَرَدِ، وَالْهَابِطِينَ مَعَ قَطْرِ الْمَطَرِ إِذَا نَزَلَ، وَالْقُوَّامِ عَلَى خَزَائِنِ الرِّيَاحِ، وَالْمُوَكَّلِينَ بِالْجِبَالِ فَلَا تَزُولُ؛</p><p class=\"fa\">و بر آنان که چون فرمان برای تحقق کامل وعده‌ات فرود آید، بر کرانه‌های آسمان‌ها ایستاده‌اند؛ و بر خزانه‌داران باران، و رانندگان ابر؛ و بر آن [فرشته] که با بانگِ راندنش غرّش رعدها شنیده می‌شود، و چون ابرِ پرخروش با او روان شود، آذرخش‌ها می‌درخشد؛ و بر همراهان برف و تگرگ، و آنان که با قطره‌های باران، هنگامی که فرو می‌بارد، فرود می‌آیند، و نگهبانان گنجینه‌های بادها، و گماشتگان بر کوه‌ها تا از جای نروند؛</p></section>\n<section class=\"pa\"><span class=\"n\">۹</span><p class=\"ar\">وَالَّذِينَ عَرَّفْتَهُمْ مَثَاقِيلَ الْمِيَاهِ، وَكَيْلَ مَا تَحْوِيهِ لَوَاعِجُ الْأَمْطَارِ وَعَوَالِجُهَا؛ وَرُسُلِكَ مِنَ الْمَلَائِكَةِ إِلَى أَهْلِ الْأَرْضِ بِمَكْرُوهِ مَا يَنْزِلُ مِنَ الْبَلَاءِ وَمَحْبُوبِ الرَّخَاءِ؛ وَالسَّفَرَةِ الْكِرَامِ الْبَرَرَةِ، وَالْحَفَظَةِ الْكِرَامِ الْكَاتِبِينَ؛ وَمَلَكِ الْمَوْتِ وَأَعْوَانِهِ، وَمُنْكَرٍ وَنَكِيرٍ، وَرُومَانَ فَتَّانِ الْقُبُورِ، وَالطَّائِفِينَ بِالْبَيْتِ الْمَعْمُورِ؛ وَمَالِكٍ وَالْخَزَنَةِ، وَرِضْوَانَ وَسَدَنَةِ الْجِنَانِ؛</p><p class=\"fa\">و بر آنان که وزن آب‌ها را به ایشان شناساندی، و پیمانهٔ آنچه باران‌های تند و انبوه در خود دارند؛ و بر فرستادگانت از فرشتگان به سوی اهل زمین، چه با بلای ناخوشایندی که فرود می‌آید و چه با آسایشِ دلپسند؛ و بر سفیرانِ گرامیِ نیکوکار، و نگهبانانِ گرامیِ نویسندهٔ اعمال؛ و بر فرشتهٔ مرگ و یارانش، و منکر و نکیر، و رومان، آزمایندهٔ اهل گور، و طواف‌کنندگانِ بیت‌المعمور؛ و بر مالک و نگهبانان [دوزخ]، و رضوان و دیگر خادمان بهشت‌ها؛</p></section>\n<section class=\"pa\"><span class=\"n\">۱۰</span><p class=\"ar\">وَالَّذِينَ لَا يَعْصُونَ اللَّهَ مَا أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ؛ وَالَّذِينَ يَقُولُونَ: <span class=\"q\">سَلَامٌ عَلَيْكُمْ بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِ</span>؛ وَالزَّبَانِيَةِ الَّذِينَ إِذَا قِيلَ لَهُمْ: <span class=\"q\">خُذُوهُ فَغُلُّوهُ ثُمَّ الْجَحِيمَ صَلُّوهُ</span>، ابْتَدَرُوهُ سِرَاعاً وَلَمْ يُنْظِرُوهُ؛ وَمَنْ أَوْهَمْنَا ذِكْرَهُ، وَلَمْ نَعْلَمْ مَكَانَهُ مِنْكَ، وَبِأَيِّ أَمْرٍ وَكَّلْتَهُ؛ وَسُكَّانِ الْهَوَاءِ وَالْأَرْضِ وَالْمَاءِ، وَمَنْ مِنْهُمْ عَلَى الْخَلْقِ؛</p><p class=\"fa\">و بر آنان که خدا را در آنچه فرمانشان داده نافرمانی نمی‌کنند و هر چه فرمان یابند انجام می‌دهند؛ و آنان که [به بهشتیان] می‌گویند: <span class=\"q\">«سلام بر شما به پاس آنکه شکیبایی ورزیدید؛ پس چه نیکوست سرانجامِ آن سرای»</span>؛ و بر زبانیه، مأموران دوزخ، که چون به آنان گفته شود: <span class=\"q\">«او را بگیرید و در غل کنید، سپس به دوزخش درافکنید»</span>، شتابان به سویش می‌روند و مهلتش نمی‌دهند؛ و بر هر کس که یادش از خاطر ما رفت و ندانستیم جایگاهش نزد تو چیست و او را به چه کاری گماشته‌ای؛ و بر ساکنان هوا و زمین و آب، و آنان از ایشان که بر آفریدگان گماشته شده‌اند؛</p></section>\n<section class=\"pa\"><span class=\"n\">۱۱</span><p class=\"ar\">فَصَلِّ عَلَيْهِمْ يَوْمَ تَأْتِي كُلُّ نَفْسٍ مَعَهَا سَائِقٌ وَشَهِيدٌ، وَصَلِّ عَلَيْهِمْ صَلَاةً تَزِيدُهُمْ كَرَامَةً عَلَى كَرَامَتِهِمْ، وَطَهَارَةً عَلَى طَهَارَتِهِمْ.</p><p class=\"fa\">پس بر همهٔ آنان درود فرست، در روزی که هر کس می‌آید و همراهش راننده‌ای و گواهی است؛ و بر آنان درودی فرست که کرامتی بر کرامتشان و پاکی‌ای بر پاکی‌شان بیفزاید.</p></section>\n<section class=\"pa\"><span class=\"n\">۱۲</span><p class=\"ar\">اللَّهُمَّ وَإِذَا صَلَّيْتَ عَلَى مَلَائِكَتِكَ وَرُسُلِكَ، وَبَلَّغْتَهُمْ صَلَاتَنَا عَلَيْهِمْ، فَصَلِّ عَلَيْنَا بِمَا فَتَحْتَ لَنَا مِنْ حُسْنِ الْقَوْلِ فِيهِمْ، إِنَّكَ جَوَادٌ كَرِيمٌ.</p><p class=\"fa\">خدایا، و چون بر فرشتگان و فرستادگانت درود فرستادی و درود ما را به آنان رساندی، به پاس آنکه زبان ما را به نیکوگویی دربارهٔ ایشان گشودی، بر ما نیز درود فرست؛ که تو بخشنده و کریمی.</p></section>"}, {"id": "estegh", "color": "ruby", "eyebrow": "امیرالمؤمنین (ع) · دستور معالم الحکم", "title": "استغفار امیرالمؤمنین", "sub": "آموزش استغفار به مردی که از فقر شکایت داشت", "body": "<p class=\"intro-fa\">مردی نزد امیرالمؤمنین (ع) آمد و گفت: «من مردی فقیرم؛ نه مالی دارم و نه فرزندی.» حضرت فرمود: «چرا از این سخن خدای عزّوجلّ غافلی؟»</p><section class=\"pa\"><span class=\"n\">نوح ۱۰ تا ۱۲</span><p class=\"q\">فَقُلۡتُ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارࣰا <span class=\"am\">﴿١٠﴾</span> يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارࣰا <span class=\"am\">﴿١١﴾</span> وَيُمۡدِدۡكُم بِأَمۡوَٰلࣲ وَبَنِينَ وَيَجۡعَل لَّكُمۡ جَنَّٰتࣲ وَيَجۡعَل لَّكُمۡ أَنۡهَٰرࣰا <span class=\"am\">﴿١٢﴾</span></p>\n<p class=\"fa\">پس [به آنان] گفتم: از پروردگارتان آمرزش بخواهید که او همواره بسیار آمرزنده است؛ <span class=\"fn\">(۱۰)</span> تا باران آسمان را پی‌درپی بر شما فرو فرستد، <span class=\"fn\">(۱۱)</span> و شما را با اموال و فرزندان یاری کند، و برایتان باغ‌ها و نهرها قرار دهد. <span class=\"fn\">(۱۲)</span></p></section><a class=\"listen\" href=\"https://quran.com/71/10-12\" target=\"_blank\" rel=\"noopener\">▶ شنیدن قرائت این آیات در Quran.com</a><p class=\"intro-fa\">مرد گفت: «به من بیاموز چگونه استغفار کنم.» حضرت فرمود: بگو:</p><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">اللَّهُمَّ إِنِّي أَسْتَغْفِرُكَ مِنْ كُلِّ ذَنْبٍ قَوِيَ عَلَيْهِ بَدَنِي بِعَافِيَتِكَ، أَوْ نَالَتْهُ قُدْرَتِي بِفَضْلِ نِعْمَتِكَ، أَوْ بَسَطْتُ إِلَيْهِ يَدِي بِسَابِغِ رِزْقِكَ، أَوِ اتَّكَلْتُ فِيهِ عِنْدَ خَوْفِي مِنْهُ عَلَى أَنَاتِكَ، أَوْ عَوَّلْتُ فِيهِ عَلَى كَرِيمِ عَفْوِكَ، أَوْ وَثِقْتُ مِنْهُ بِحِلْمِكَ.</p><p class=\"fa\">خدایا، از تو آمرزش می‌خواهم برای هر گناهی که بدنم با عافیتی که تو دادی بر آن توانا شد؛ یا به برکت فزونی نعمت تو از دستم برآمد؛ یا با روزی فراوان تو دستم را به سویش گشودم؛ یا هنگامی که از آن می‌ترسیدم، به درنگ و مهلت دادنِ تو تکیه کردم؛ یا به عفو کریمانهٔ تو دل بستم؛ یا از بابت آن به بردباری تو اطمینان کردم.</p></section>\n<section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">اللَّهُمَّ وَأَسْتَغْفِرُكَ مِنْ كُلِّ ذَنْبٍ خُنْتُ فِيهِ أَمَانَتِي، أَوْ بَخَسْتُ بِفِعْلِهِ نَفْسِي، أَوْ خَطِئْتُ بِهِ عَلَى بَدَنِي، أَوْ قَدَّمْتُ فِيهِ لَذَّتِي، أَوْ آثَرْتُ فِيهِ شَهْوَتِي، أَوْ قَهَرْتُ فِيهِ مَنْ مَنَعَنِي.</p><p class=\"fa\">خدایا، و از تو آمرزش می‌خواهم برای هر گناهی که در آن به امانتم خیانت کردم؛ یا با انجامش به خود زیان زدم؛ یا با آن بر تن خود خطا کردم؛ یا در آن لذتم را مقدم داشتم؛ یا خواهش نفسم را برگزیدم؛ یا در آن بر کسی که مرا از آن باز می‌داشت چیره شدم.</p></section>\n<section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">اللَّهُمَّ وَأَسْتَغْفِرُكَ مِنْ كُلِّ ذَنْبٍ سَبَقَ عَلَيَّ فِي عِلْمِكَ أَنِّي فَاعِلُهُ، فَدَخَلْتُ فِيهِ بِإِرَادَتِي، وَاجْتَرَحْتُهُ بِمَحَبَّتِي، أَوْ أَتَيْتُهُ بِشَهْوَتِي، ثُمَّ أَحَلْتُ عَلَيْكَ رَبِّي، فَلَمْ أُغَالِبْكَ بِفِعْلِي إِذْ كُنْتَ كَارِهاً لِمَعْصِيَتِي، لٰكِنْ سَبَقَ عِلْمُكَ فِيَّ فَحَلُمْتَ عَنِّي، فَلَمْ تُدْخِلْنِي فِيهِ جَبْراً، وَلَمْ تَحْمِلْنِي عَلَيْهِ قَسْراً، وَلَمْ تَظْلِمْنِي فِيهِ شَيْئاً؛ فَاغْفِرْ لِي يَا إِلٰهِي، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ.</p><p class=\"fa\">خدایا، و از تو آمرزش می‌خواهم برای هر گناهی که در علم تو گذشته بود که من انجامش می‌دهم؛ پس به ارادهٔ خود در آن وارد شدم، و از سر دلخواه مرتکبش شدم، یا با شهوتم به سراغش رفتم؛ سپس، پروردگارا، [گناهش را] به گردن تو انداختم. حال آنکه من با کارم بر تو چیره نشدم، چون تو از نافرمانی من ناخشنود بودی؛ بلکه علم تو دربارهٔ من پیشی گرفته بود و تو بر من بردباری کردی. نه مرا به زور در آن وارد کردی، نه به اجبار بر آن واداشتی، و نه در آن ذره‌ای بر من ستم کردی. پس مرا بیامرز، ای معبود من، که جز تو کسی گناهان را نمی‌آمرزد.</p></section>"}, {"id": "afv", "color": "violet", "eyebrow": "صحیفهٔ سجادیه · دعای ۳۹", "title": "دعای طلب عفو و رحمت", "sub": "بخشیدن کسانی که به ما ستم کرده‌اند و آمرزش خواستن برای خود", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي طَلَبِ الْعَفْوِ وَالرَّحْمَةِ</p><p class=\"intro-fa\">از دعاهای آن حضرت (ع) در طلب عفو و رحمت</p><div class=\"player\"><span>🔊 دعای طلب عفو (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/dua39.mp3\"></audio></div><p class=\"note\">این دعا برای وقتی است که کسی آزارمان داده است: امام (ع) از خدا می‌خواهد ستمکار را ببخشد، این گذشت را صدقه‌ای پاک بپذیرد و در عوض، عفو و رحمت خود را به ما بدهد.</p><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاكْسِرْ شَهْوَتِي عَنْ كُلِّ مَحْرَمٍ، وَازْوِ حِرْصِي عَنْ كُلِّ مَأْثَمٍ، وَامْنَعْنِي عَنْ أَذَى كُلِّ مُؤْمِنٍ وَمُؤْمِنَةٍ، وَمُسْلِمٍ وَمُسْلِمَةٍ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست؛ و خواهش مرا از هر حرامی بشکن، و آزمندی‌ام را از هر گناهی بازگردان، و مرا از آزردن هر مرد و زن مؤمن و هر مرد و زن مسلمان بازدار.</p></section>\n<section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">اللَّهُمَّ وَأَيُّمَا عَبْدٍ نَالَ مِنِّي مَا حَظَرْتَ عَلَيْهِ، وَانْتَهَكَ مِنِّي مَا حَجَرْتَ عَلَيْهِ، فَمَضَى بِظُلَامَتِي مَيِّتاً، أَوْ حَصَلَتْ لِي قِبَلَهُ حَيّاً، فَاغْفِرْ لَهُ مَا أَلَمَّ بِهِ مِنِّي، وَاعْفُ لَهُ عَمَّا أَدْبَرَ بِهِ عَنِّي، وَلَا تَقِفْهُ عَلَى مَا ارْتَكَبَ فِيَّ، وَلَا تَكْشِفْهُ عَمَّا اكْتَسَبَ بِي، وَاجْعَلْ مَا سَمَحْتُ بِهِ مِنَ الْعَفْوِ عَنْهُمْ، وَتَبَرَّعْتُ بِهِ مِنَ الصَّدَقَةِ عَلَيْهِمْ، أَزْكَى صَدَقَاتِ الْمُتَصَدِّقِينَ، وَأَعْلَى صِلَاتِ الْمُتَقَرِّبِينَ؛ وَعَوِّضْنِي مِنْ عَفْوِي عَنْهُمْ عَفْوَكَ، وَمِنْ دُعَائِي لَهُمْ رَحْمَتَكَ، حَتَّى يَسْعَدَ كُلُّ وَاحِدٍ مِنَّا بِفَضْلِكَ، وَيَنْجُوَ كُلٌّ مِنَّا بِمَنِّكَ.</p><p class=\"fa\">خدایا، و هر بنده‌ای که از من به چیزی دست یافت که تو بر او ممنوع کرده بودی، و حرمتی از مرا شکست که تو او را از آن بازداشته بودی، و آنگاه با حقی که از من بر گردن داشت از دنیا رفت، یا در زندگی‌اش حقی از من بر عهده‌اش ماند؛ پس آنچه را که از سوی من بر گردن دارد بر او ببخش، و از آنچه از من برد و رفت درگذر؛ او را بر آنچه دربارهٔ من مرتکب شد بازخواست نکن، و به سبب آنچه از من به دست آورد رسوایش مکن. و آن گذشتی را که از آنان روا داشتم، و آن صدقه‌ای را که به رایگان بر ایشان کردم، پاک‌ترین صدقهٔ صدقه‌دهندگان و والاترین هدیهٔ تقرب‌جویان قرار ده؛ و در برابر گذشت من از آنان، گذشت خودت را، و در برابر دعای من برایشان، رحمتت را به من عوض ده؛ تا هر یک از ما به فضل تو نیک‌بخت شود، و هر یک از ما به احسان تو رهایی یابد.</p></section>\n<section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">اللَّهُمَّ وَأَيُّمَا عَبْدٍ مِنْ عَبِيدِكَ أَدْرَكَهُ مِنِّي دَرَكٌ، أَوْ مَسَّهُ مِنْ نَاحِيَتِي أَذًى، أَوْ لَحِقَهُ بِي أَوْ بِسَبَبِي ظُلْمٌ، فَفُتُّهُ بِحَقِّهِ، أَوْ سَبَقْتُهُ بِمَظْلِمَتِهِ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَأَرْضِهِ عَنِّي مِنْ وُجْدِكَ، وَأَوْفِهِ حَقَّهُ مِنْ عِنْدِكَ، ثُمَّ قِنِي مَا يُوجِبُ لَهُ حُكْمُكَ، وَخَلِّصْنِي مِمَّا يَحْكُمُ بِهِ عَدْلُكَ؛ فَإِنَّ قُوَّتِي لَا تَسْتَقِلُّ بِنَقِمَتِكَ، وَإِنَّ طَاقَتِي لَا تَنْهَضُ بِسُخْطِكَ، فَإِنَّكَ إِنْ تُكَافِنِي بِالْحَقِّ تُهْلِكْنِي، وَإِلَّا تَغَمَّدْنِي بِرَحْمَتِكَ تُوبِقْنِي.</p><p class=\"fa\">خدایا، و هر بنده‌ای از بندگانت که از سوی من زیانی به او رسید، یا از جانب من آزاری دید، یا به دست من یا به سبب من ستمی بر او رفت، و من حقش را از دست دادم [و ادا نکردم]، یا پیش از جبران ستمی که بر او کرده بودم فرصت از دست رفت؛ پس بر محمد و خاندانش درود فرست، و او را با توانگری خود از من خشنود کن، و حقش را از نزد خود به تمامی به او بپرداز؛ سپس مرا از آنچه حکم تو به سود او واجب می‌کند نگاه دار، و از آنچه عدل تو به آن حکم می‌کند رهایی بخش. زیرا توان من تاب کیفر تو را ندارد، و طاقتم یارای خشم تو را ندارد؛ که اگر مرا به حق جزا دهی نابودم می‌کنی، و اگر مرا در رحمتت نپوشانی هلاکم می‌سازی.</p></section>\n<section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">اللَّهُمَّ إِنِّي أَسْتَوْهِبُكَ يَا إِلٰهِي مَا لَا يَنْقُصُكَ بَذْلُهُ، وَأَسْتَحْمِلُكَ مَا لَا يَبْهَظُكَ حَمْلُهُ؛ أَسْتَوْهِبُكَ يَا إِلٰهِي نَفْسِيَ الَّتِي لَمْ تَخْلُقْهَا لِتَمْتَنِعَ بِهَا مِنْ سُوءٍ، أَوْ لِتَطَرَّقَ بِهَا إِلَى نَفْعٍ، وَلٰكِنْ أَنْشَأْتَهَا إِثْبَاتاً لِقُدْرَتِكَ عَلَى مِثْلِهَا، وَاحْتِجَاجاً بِهَا عَلَى شَكْلِهَا؛ وَأَسْتَحْمِلُكَ مِنْ ذُنُوبِي مَا قَدْ بَهَظَنِي حَمْلُهُ، وَأَسْتَعِينُ بِكَ عَلَى مَا قَدْ فَدَحَنِي ثِقْلُهُ؛ فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَهَبْ لِنَفْسِي عَلَى ظُلْمِهَا نَفْسِي، وَوَكِّلْ رَحْمَتَكَ بِاحْتِمَالِ إِصْرِي؛ فَكَمْ قَدْ لَحِقَتْ رَحْمَتُكَ بِالْمُسِيئِينَ، وَكَمْ قَدْ شَمِلَ عَفْوُكَ الظَّالِمِينَ.</p><p class=\"fa\">خدایا، ای معبود من، از تو چیزی را به بخشش می‌خواهم که بخشیدنش از تو نمی‌کاهد، و می‌خواهم باری را برداری که برداشتنش بر تو گران نیست. ای معبود من، جانم را از تو به بخشش می‌خواهم؛ جانی که آن را نیافریدی تا با آن خود را از بدی‌ای در امان داری یا به سودی راه یابی، بلکه آن را پدید آوردی تا توانایی‌ات را بر آفریدن همانندش نشان دهی و با آن بر همگونانش حجت آوری. و از تو می‌خواهم از گناهانم آنچه را که بارش بر من سنگینی کرده بر دوش گیری، و برای آنچه سنگینی‌اش مرا از پا درآورده از تو یاری می‌جویم. پس بر محمد و خاندانش درود فرست، و با همهٔ ستمی که جانم بر خود کرده، آن را به من ببخش، و رحمتت را به برداشتن بار گرانم بگمار؛ که چه بسیار رحمتت به بدکاران رسیده، و چه بسیار عفوت ستمکاران را فرا گرفته است.</p></section>\n<section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْنِي أُسْوَةَ مَنْ قَدْ أَنْهَضْتَهُ بِتَجَاوُزِكَ عَنْ مَصَارِعِ الْخَاطِئِينَ، وَخَلَّصْتَهُ بِتَوْفِيقِكَ مِنْ وَرَطَاتِ الْمُجْرِمِينَ، فَأَصْبَحَ طَلِيقَ عَفْوِكَ مِنْ إِسَارِ سُخْطِكَ، وَعَتِيقَ صُنْعِكَ مِنْ وَثَاقِ عَدْلِكَ؛ إِنَّكَ إِنْ تَفْعَلْ ذٰلِكَ يَا إِلٰهِي تَفْعَلْهُ بِمَنْ لَا يَجْحَدُ اسْتِحْقَاقَ عُقُوبَتِكَ، وَلَا يُبَرِّئُ نَفْسَهُ مِنِ اسْتِيجَابِ نَقِمَتِكَ؛ تَفْعَلْ ذٰلِكَ يَا إِلٰهِي بِمَنْ خَوْفُهُ مِنْكَ أَكْثَرُ مِنْ طَمَعِهِ فِيكَ، وَبِمَنْ يَأْسُهُ مِنَ النَّجَاةِ أَوْكَدُ مِنْ رَجَائِهِ لِلْخَلَاصِ؛ لَا أَنْ يَكُونَ يَأْسُهُ قُنُوطاً، أَوْ أَنْ يَكُونَ طَمَعُهُ اغْتِرَاراً، بَلْ لِقِلَّةِ حَسَنَاتِهِ بَيْنَ سَيِّئَاتِهِ، وَضَعْفِ حُجَجِهِ فِي جَمِيعِ تَبِعَاتِهِ.</p><p class=\"fa\">پس بر محمد و خاندانش درود فرست، و مرا مانند کسی قرار ده که با درگذشتن از او، از افتادنگاه خطاکاران برش خیزاندی، و با توفیقت از گرداب‌های گنهکاران رهایش کردی؛ تا آزادشدهٔ عفو تو از بند خشمت، و رهاشدهٔ احسان تو از بند عدلت گشت. ای معبود من، اگر چنین کنی، با کسی چنین کرده‌ای که سزاواری‌اش را برای کیفرت انکار نمی‌کند، و خود را از مستحق شدن عقوبتت مبرا نمی‌داند. ای معبود من، با کسی چنین کرده‌ای که ترسش از تو بیش از امیدش به توست، و ناامیدی‌اش از نجات استوارتر از امیدش به رهایی است؛ نه از آن رو که ناامیدی‌اش نومیدی [از رحمت تو] باشد، یا امیدش فریفتگی باشد، بلکه از آن رو که نیکی‌هایش در میان بدی‌هایش اندک است، و دلیل‌هایش در برابر همهٔ پیامدهای گناهانش ناتوان.</p></section>\n<section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">فَأَمَّا أَنْتَ يَا إِلٰهِي فَأَهْلٌ أَنْ لَا يَغْتَرَّ بِكَ الصِّدِّيقُونَ، وَلَا يَيْأَسَ مِنْكَ الْمُجْرِمُونَ؛ لِأَنَّكَ الرَّبُّ الْعَظِيمُ الَّذِي لَا يَمْنَعُ أَحَداً فَضْلَهُ، وَلَا يَسْتَقْصِي مِنْ أَحَدٍ حَقَّهُ؛ تَعَالَى ذِكْرُكَ عَنِ الْمَذْكُورِينَ، وَتَقَدَّسَتْ أَسْمَاؤُكَ عَنِ الْمَنْسُوبِينَ، وَفَشَتْ نِعْمَتُكَ فِي جَمِيعِ الْمَخْلُوقِينَ؛ فَلَكَ الْحَمْدُ عَلَى ذٰلِكَ يَا رَبَّ الْعَالَمِينَ.</p><p class=\"fa\">اما تو، ای معبود من، سزاوار آنی که راستگویان به تو مغرور نشوند و گنهکاران از تو ناامید نگردند؛ زیرا تو پروردگار بزرگی هستی که فضلش را از هیچ کس دریغ نمی‌کند و حقش را از هیچ کس تا آخرین ذره نمی‌ستاند. یاد تو برتر از یاد همهٔ یادشدگان است، و نام‌هایت پاک‌تر از نام همهٔ دیگران، و نعمتت در میان همهٔ آفریدگان گسترده است. پس تو را بر این ستایش باد، ای پروردگار جهانیان.</p></section>"}, {"id": "namaz", "color": "amber", "eyebrow": "نماز مستحب", "title": "نماز دورکعتی", "sub": "روش خواندن، با نیتِ برای خدا", "body": "<div class=\"honest\"><strong>دربارهٔ منبع:</strong> نماز مستحبِ دورکعتی که برای خدا خوانده شود و ثوابش هدیه گردد، کاری پذیرفته‌شده است. اما برای «نماز هدیه به چهار فرشتهٔ مقرّب» روایت مشخصی پیدا نکردم؛ این پیشنهاد گویندهٔ فایل صوتی بود. پس نماز را <b>فقط برای خدا</b> بخوانید و اگر خواستید، ثوابش را هدیه کنید.</div>\n<ol class=\"steps\">\n<li><b>وضو</b> بگیرید و رو به قبله بایستید.</li>\n<li><b>نیت</b> در دل: «دو رکعت نماز مستحب می‌خوانم، قربةً الی الله.» گفتن آن به زبان لازم نیست.</li>\n<li><b>تکبیرة‌الاحرام:</b> <span class=\"ar-i\">اللَّهُ أَكْبَرُ</span></li>\n<li><b>رکعت اول:</b> سورهٔ حمد، و اگر خواستید یک سورهٔ کوتاه مثل اخلاص. در نماز مستحب، خواندن سوره پس از حمد واجب نیست.</li>\n<li><b>رکوع:</b> <span class=\"ar-i\">سُبْحَانَ رَبِّيَ الْعَظِيمِ وَبِحَمْدِهِ</span></li>\n<li><b>دو سجده:</b> در هر سجده <span class=\"ar-i\">سُبْحَانَ رَبِّيَ الْأَعْلَى وَبِحَمْدِهِ</span></li>\n<li><b>رکعت دوم:</b> حمد و سوره، سپس <b>قنوت</b>: دست‌ها را بالا بیاورید و هر دعایی خواستید بخوانید؛ به فارسی هم درست است.</li>\n<li>رکوع و دو سجده، مثل رکعت اول.</li>\n<li><b>تشهد:</b> <span class=\"ar-i\">أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ، اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ</span></li>\n<li><b>سلام:</b> <span class=\"ar-i\">السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ</span></li>\n<li><b>پس از نماز (اختیاری):</b> «خدایا، ثواب این نماز را به [نام کسی که می‌خواهید] هدیه می‌کنم.»</li>\n</ol>\n<h3>سورهٔ حمد</h3>\n<section class=\"pa\"><p class=\"q\">بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ <span class=\"am\">﴿١﴾</span> ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ <span class=\"am\">﴿٢﴾</span> ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ <span class=\"am\">﴿٣﴾</span> مَٰلِكِ يَوۡمِ ٱلدِّينِ <span class=\"am\">﴿٤﴾</span> إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ <span class=\"am\">﴿٥﴾</span> ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ <span class=\"am\">﴿٦﴾</span> صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ <span class=\"am\">﴿٧﴾</span></p>\n<p class=\"fa\">به نام خداوند بخشندهٔ مهربان. <span class=\"fn\">(۱)</span> ستایش از آنِ خداست، پروردگار جهانیان؛ <span class=\"fn\">(۲)</span> بخشندهٔ مهربان؛ <span class=\"fn\">(۳)</span> فرمانروای روز جزا. <span class=\"fn\">(۴)</span> تنها تو را می‌پرستیم و تنها از تو یاری می‌جوییم. <span class=\"fn\">(۵)</span> ما را به راه راست هدایت کن؛ <span class=\"fn\">(۶)</span> راه کسانی که به آنان نعمت دادی؛ نه [راه] کسانی که بر آنان خشم گرفته شده و نه گمراهان. <span class=\"fn\">(۷)</span></p></section><div class=\"player\"><span>🔊 سورهٔ حمد (تلاوت عربی)</span><audio controls preload=\"metadata\" src=\"audio/q001.mp3\"></audio></div>\n<p class=\"note\">پیشنهاد: پس از نماز، دعای حاملان عرش را بخوانید؛ چون در آن بر جبرئیل، میکائیل، اسرافیل و همهٔ فرشتگان درود فرستاده می‌شود.</p>"}, {"id": "amal", "color": "slate", "eyebrow": "کنار دعا", "title": "اعمال همراه", "sub": "آنچه سند معتبر دارد", "body": "<ul class=\"tips\">\n<li><b>صدقه:</b> هر روز، حتی اندک. صدقه دادن و غذا دادن به یتیم در قرآن و روایات بارها سفارش شده است.</li>\n<li><b>روزه:</b> هر وقت توانستید، با نیت برای خدا.</li>\n<li><b>پزشک:</b> اگر بیماری یا ناراحتی جسمی دارید، اول به پزشک مراجعه کنید.</li>\n<li><b>دوری:</b> از دعانویس، فال، طلسم و هر کاری که پول بگیرد و وعدهٔ «باطل کردن» بدهد دوری کنید.</li>\n</ul>"}, {"id": "s6", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۶", "title": "دعای صبح و شام", "sub": "سپاس بر روز و شب، و درخواست روزی نیک", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ عِنْدَ الصَّبَاحِ وَالْمَسَاءِ</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) هنگام صبح و شام</p><div class=\"player\"><span>🔊 قرائت دعای ۶ (عربی)</span><audio controls preload=\"none\" src=\"audio/dua6.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">الْحَمْدُ لِلّٰهِ الَّذِي خَلَقَ اللَّيْلَ وَالنَّهَارَ بِقُوَّتِهِ، وَمَيَّزَ بَيْنَهُمَا بِقُدْرَتِهِ، وَجَعَلَ لِكُلِّ وَاحِدٍ مِنْهُمَا حَدّاً مَحْدُوداً، وَأَمَداً مَمْدُوداً،</p><p class=\"fa\">ستایش از آنِ خدایی است که شب و روز را به نیروی خود آفرید، و به قدرت خود میانشان جدایی نهاد، و برای هر یک مرزی معیّن و زمانی گسترده قرار داد.</p></section><section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">يُولِجُ كُلَّ وَاحِدٍ مِنْهُمَا فِي صَاحِبِهِ، وَيُولِجُ صَاحِبَهُ فِيهِ، بِتَقْدِيرٍ مِنْهُ لِلْعِبَادِ فِيمَا يَغْذُوهُمْ بِهِ، وَيُنْشِئُهُمْ عَلَيْهِ،</p><p class=\"fa\">هر یک را در دیگری درمی‌آورد، و دیگری را در آن؛ با اندازه‌گیری‌ای از سوی خود برای بندگان، در آنچه با آن روزی‌شان می‌دهد و بر آن پرورششان می‌دهد.</p></section><section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">فَخَلَقَ لَهُمُ اللَّيْلَ لِيَسْكُنُوا فِيهِ مِنْ حَرَكَاتِ التَّعَبِ، وَنَهَضَاتِ النَّصَبِ، وَجَعَلَهُ لِبَاساً لِيَلْبَسُوا مِنْ رَاحَتِهِ وَمَنَامِهِ، فَيَكُونَ ذَلِكَ لَهُمْ جَمَاماً وَقُوَّةً، وَلِيَنَالُوا بِهِ لَذَّةً وَشَهْوَةً،</p><p class=\"fa\">پس شب را برایشان آفرید تا در آن از تکاپوهای خستگی و برخاستن‌های رنج آرام گیرند، و آن را پوششی قرار داد تا از آسایش و خوابش بپوشند، و این برایشان مایهٔ تجدید نیرو و توان باشد، و با آن به لذت و خواسته‌ای برسند.</p></section><section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">وَخَلَقَ لَهُمُ النَّهَارَ مُبْصِراً لِيَبْتَغُوا فِيهِ مِنْ فَضْلِهِ، وَلِيَتَسَبَّبُوا إِلَى رِزْقِهِ، وَيَسْرَحُوا فِي أَرْضِهِ، طَلَباً لِمَا فِيهِ نَيْلُ الْعَاجِلِ مِنْ دُنْيَاهُمْ، وَدَرَكُ الْآجِلِ فِي أُخْرَاهُمْ.</p><p class=\"fa\">و روز را برایشان روشن آفرید تا در آن از فضلش بجویند، و برای روزی‌اش وسیله فراهم کنند، و در زمینش روان شوند؛ در جستجوی آنچه بهرهٔ نقدِ دنیایشان و رسیدن به [پاداشِ] آینده در آخرتشان در آن است.</p></section><section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">بِكُلِّ ذَلِكَ يُصْلِحُ شَأْنَهُمْ، وَيَبْلُو أَخْبَارَهُمْ، وَيَنْظُرُ كَيْفَ هُمْ فِي أَوْقَاتِ طَاعَتِهِ، وَمَنَازِلِ فُرُوضِهِ، وَمَوَاقِعِ أَحْكَامِهِ، لِيَجْزِيَ الَّذِينَ أَسَاؤُوا بِمَا عَمِلُوا، وَيَجْزِيَ الَّذِينَ أَحْسَنُوا بِالْحُسْنَى.</p><p class=\"fa\">با همهٔ اینها کارشان را سامان می‌دهد، و حالشان را می‌آزماید، و می‌نگرد که در هنگام‌های طاعتش، و جایگاه‌های واجباتش، و موارد احکامش چگونه‌اند؛ تا بدکاران را به آنچه کرده‌اند کیفر دهد، و نیکوکاران را پاداش نیکو دهد.</p></section><section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">اللّٰهُمَّ فَلَكَ الْحَمْدُ عَلَى مَا فَلَقْتَ لَنَا مِنَ الْإِصْبَاحِ، وَمَتَّعْتَنَا بِهِ مِنْ ضَوْءِ النَّهَارِ، وَبَصَّرْتَنَا مِنْ مَطَالِبِ الْأَقْوَاتِ، وَوَقَيْتَنَا فِيهِ مِنْ طَوَارِقِ الْآفَاتِ.</p><p class=\"fa\">خدایا، پس ستایش تو راست بر سپیده‌ای که برای ما شکافتی، و روشنی روز که ما را از آن بهره‌مند کردی، و راه‌های به دست آوردن روزی که به ما نشان دادی، و آفت‌های ناگهانی که در آن از ما دور کردی.</p></section><section class=\"pa\"><span class=\"n\">۷</span><p class=\"ar\">أَصْبَحْنَا وَأَصْبَحَتِ الْأَشْيَاءُ كُلُّهَا بِجُمْلَتِهَا لَكَ: سَمَاؤُهَا وَأَرْضُهَا، وَمَا بَثَثْتَ فِي كُلِّ وَاحِدٍ مِنْهُمَا، سَاكِنُهُ وَمُتَحَرِّكُهُ، وَمُقِيمُهُ وَشَاخِصُهُ، وَمَا عَلَا فِي الْهَوَاءِ، وَمَا كَنَّ تَحْتَ الثَّرَى.</p><p class=\"fa\">صبح کردیم و همهٔ چیزها، یکسره، از آنِ تو صبح کردند: آسمان و زمینش، و آنچه در هر یک پراکندی، ساکن و جنبنده‌اش، ماندگار و رونده‌اش، و آنچه در هوا بالا رفته، و آنچه زیر خاک پنهان است.</p></section><section class=\"pa\"><span class=\"n\">۸</span><p class=\"ar\">أَصْبَحْنَا فِي قَبْضَتِكَ، يَحْوِينَا مُلْكُكَ وَسُلْطَانُكَ، وَتَضُمُّنَا مَشِيَّتُكَ، وَنَتَصَرَّفُ عَنْ أَمْرِكَ، وَنَتَقَلَّبُ فِي تَدْبِيرِكَ، لَيْسَ لَنَا مِنَ الْأَمْرِ إِلَّا مَا قَضَيْتَ، وَلَا مِنَ الْخَيْرِ إِلَّا مَا أَعْطَيْتَ.</p><p class=\"fa\">در چنگ تو صبح کردیم؛ فرمانروایی و سلطنتت ما را در بر گرفته، و خواستت ما را فرا گرفته، و به فرمان تو رفتار می‌کنیم، و در تدبیر تو دگرگون می‌شویم؛ از کار جز آنچه تو حکم کردی، و از خیر جز آنچه تو دادی، چیزی برای ما نیست.</p></section><section class=\"pa\"><span class=\"n\">۹</span><p class=\"ar\">وَهَذَا يَوْمٌ حَادِثٌ جَدِيدٌ، وَهُوَ عَلَيْنَا شَاهِدٌ عَتِيدٌ، إِنْ أَحْسَنَّا وَدَّعَنَا بِحَمْدٍ، وَإِنْ أَسَأْنَا فَارَقَنَا بِذَمٍّ.</p><p class=\"fa\">و این روزی نو و تازه است، و گواهی آماده بر ماست؛ اگر نیکی کنیم با ستایش بدرودمان می‌گوید، و اگر بدی کنیم با نکوهش از ما جدا می‌شود.</p></section><section class=\"pa\"><span class=\"n\">۱۰</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَارْزُقْنَا حُسْنَ مُصَاحَبَتِهِ، وَاعْصِمْنَا مِنْ سُوءِ مُفَارَقَتِهِ بِارْتِكَابِ جَرِيرَةٍ، أَوِ اقْتِرَافِ صَغِيرَةٍ أَوْ كَبِيرَةٍ،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و هم‌نشینی نیکو با این روز را روزی ما کن، و ما را از جدایی بد از آن، با انجام گناهی یا مرتکب شدن [خطای] کوچک یا بزرگی، نگاه دار.</p></section><section class=\"pa\"><span class=\"n\">۱۱</span><p class=\"ar\">وَأَجْزِلْ لَنَا فِيهِ مِنَ الْحَسَنَاتِ، وَأَخْلِنَا فِيهِ مِنَ السَّيِّئَاتِ، وَامْلَأْ لَنَا مَا بَيْنَ طَرَفَيْهِ حَمْداً وَشُكْراً، وَأَجْراً وَذُخْراً، وَفَضْلاً وَإِحْسَاناً.</p><p class=\"fa\">و در آن نیکی‌های ما را فراوان کن، و ما را در آن از بدی‌ها خالی دار، و میان آغاز و پایانش را برای ما از ستایش و سپاس، و پاداش و اندوخته، و فضل و نیکی پر کن.</p></section><section class=\"pa\"><span class=\"n\">۱۲</span><p class=\"ar\">اللّٰهُمَّ يَسِّرْ عَلَى الْكِرَامِ الْكَاتِبِينَ مَؤُونَتَنَا، وَامْلَأْ لَنَا مِنْ حَسَنَاتِنَا صَحَائِفَنَا، وَلَا تُخْزِنَا عِنْدَهُمْ بِسُوءِ أَعْمَالِنَا.</p><p class=\"fa\">خدایا، زحمت ما را بر نویسندگان بزرگوار [فرشتگان ثبت اعمال] آسان کن، و نامه‌هایمان را از نیکی‌هایمان پر کن، و ما را نزد آنان با کارهای بدمان رسوا مکن.</p></section><section class=\"pa\"><span class=\"n\">۱۳</span><p class=\"ar\">اللّٰهُمَّ اجْعَلْ لَنَا فِي كُلِّ سَاعَةٍ مِنْ سَاعَاتِهِ حَظّاً مِنْ عِبَادِكَ، وَنَصِيباً مِنْ شُكْرِكَ، وَشَاهِدَ صِدْقٍ مِنْ مَلَائِكَتِكَ.</p><p class=\"fa\">خدایا، در هر ساعت از ساعت‌های این روز برای ما بهره‌ای از [دعای] بندگانت، و سهمی از سپاس‌گزاری‌ات، و گواهی راستگو از فرشتگانت قرار ده.</p></section><section class=\"pa\"><span class=\"n\">۱۴</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاحْفَظْنَا مِنْ بَيْنِ أَيْدِينَا وَمِنْ خَلْفِنَا، وَعَنْ أَيْمَانِنَا وَعَنْ شَمَائِلِنَا، وَمِنْ جَمِيعِ نَوَاحِينَا، حِفْظاً عَاصِماً مِنْ مَعْصِيَتِكَ، هَادِياً إِلَى طَاعَتِكَ، مُسْتَعْمِلاً لِمَحَبَّتِكَ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و ما را از پیش رو و پشت سر، و از راست و چپ، و از همهٔ سوها نگاه دار؛ نگاهداشتنی که از نافرمانی‌ات بازدارد، به طاعتت راه نماید، و به کاری که دوست داری بگمارد.</p></section><section class=\"pa\"><span class=\"n\">۱۵</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَوَفِّقْنَا فِي يَوْمِنَا هَذَا، وَلَيْلَتِنَا هَذِهِ، وَفِي جَمِيعِ أَيَّامِنَا، لِاسْتِعْمَالِ الْخَيْرِ، وَهِجْرَانِ الشَّرِّ، وَشُكْرِ النِّعَمِ، وَاتِّبَاعِ السُّنَنِ، وَمُجَانَبَةِ الْبِدَعِ، وَالْأَمْرِ بِالْمَعْرُوفِ، وَالنَّهْيِ عَنِ الْمُنْكَرِ،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و ما را در این روز و این شب و در همهٔ روزهایمان توفیق ده برای به کار بستن خیر، و دوری از شر، و سپاس نعمت‌ها، و پیروی از سنت‌ها، و کناره‌گیری از بدعت‌ها، و امر به معروف، و نهی از منکر،</p></section><section class=\"pa\"><span class=\"n\">۱۶</span><p class=\"ar\">وَحِيَاطَةِ الْإِسْلَامِ، وَانْتِقَاصِ الْبَاطِلِ وَإِذْلَالِهِ، وَنُصْرَةِ الْحَقِّ وَإِعْزَازِهِ، وَإِرْشَادِ الضَّالِّ، وَمُعَاوَنَةِ الضَّعِيفِ، وَإِدْرَاكِ اللَّهِيفِ.</p><p class=\"fa\">و پاسداری از اسلام، و کاستن از باطل و خوار کردنش، و یاری حق و عزیز داشتنش، و راهنمایی گمراه، و یاری ناتوان، و دستگیری از اندوهگینِ دادخواه.</p></section><section class=\"pa\"><span class=\"n\">۱۷</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْهُ أَيْمَنَ يَوْمٍ عَهِدْنَاهُ، وَأَفْضَلَ صَاحِبٍ صَحِبْنَاهُ، وَخَيْرَ وَقْتٍ ظَلِلْنَا فِيهِ،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و این روز را خجسته‌ترین روزی که دیده‌ایم، و بهترین همراهی که همراهش بوده‌ایم، و بهترین هنگامی که در آن به سر برده‌ایم قرار ده.</p></section><section class=\"pa\"><span class=\"n\">۱۸</span><p class=\"ar\">وَاجْعَلْنَا مِنْ أَرْضَى مَنْ مَرَّ عَلَيْهِ اللَّيْلُ وَالنَّهَارُ مِنْ جُمْلَةِ خَلْقِكَ، أَشْكَرَهُمْ لِمَا أَوْلَيْتَ مِنْ نِعَمِكَ، وَأَقْوَمَهُمْ بِمَا شَرَعْتَ مِنْ شَرَائِعِكَ، وَأَوْقَفَهُمْ عَمَّا حَذَّرْتَ مِنْ نَهْيِكَ.</p><p class=\"fa\">و ما را از پسندیده‌ترینِ آفریدگانت که شب و روز بر آنان گذشته قرار ده؛ سپاس‌گزارترینشان برای نعمت‌هایی که دادی، و پایدارترینشان در آیین‌هایی که نهادی، و بازایستاده‌ترینشان از آنچه با نهی‌ات از آن پرهیز دادی.</p></section><section class=\"pa\"><span class=\"n\">۱۹</span><p class=\"ar\">اللّٰهُمَّ إِنِّي أُشْهِدُكَ، وَكَفَى بِكَ شَهِيداً، وَأُشْهِدُ سَمَاءَكَ وَأَرْضَكَ، وَمَنْ أَسْكَنْتَهُمَا مِنْ مَلَائِكَتِكَ وَسَائِرِ خَلْقِكَ، فِي يَوْمِي هَذَا، وَسَاعَتِي هَذِهِ، وَلَيْلَتِي هَذِهِ، وَمُسْتَقَرِّي هَذَا،</p><p class=\"fa\">خدایا، تو را گواه می‌گیرم، و تو برای گواهی بسنده‌ای، و آسمان و زمینت را، و فرشتگان و دیگر آفریدگانت را که در آن دو جای دادی، گواه می‌گیرم؛ در این روز، و این ساعت، و این شب، و این جایی که هستم:</p></section><section class=\"pa\"><span class=\"n\">۲۰</span><p class=\"ar\">أَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللّٰهُ الَّذِي لَا إِلَهَ إِلَّا أَنْتَ، قَائِمٌ بِالْقِسْطِ، عَدْلٌ فِي الْحُكْمِ، رَؤُوفٌ بِالْعِبَادِ، مَالِكُ الْمُلْكِ، رَحِيمٌ بِالْخَلْقِ،</p><p class=\"fa\">که گواهی می‌دهم تو خدایی هستی که معبودی جز تو نیست؛ برپادارندهٔ دادی، در داوری عادلی، با بندگان مهربانی، دارندهٔ فرمانروایی، و با آفریدگان بخشاینده‌ای.</p></section><section class=\"pa\"><span class=\"n\">۲۱</span><p class=\"ar\">وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ، وَخِيَرَتُكَ مِنْ خَلْقِكَ، حَمَّلْتَهُ رِسَالَتَكَ فَأَدَّاهَا، وَأَمَرْتَهُ بِالنُّصْحِ لِأُمَّتِهِ فَنَصَحَ لَهَا.</p><p class=\"fa\">و [گواهی می‌دهم] که محمد بنده و فرستادهٔ تو، و برگزیده‌ات از میان آفریدگان است؛ پیامت را بر دوشش نهادی و آن را رساند، و فرمانش دادی که خیرخواه امتش باشد، و خیرخواهی کرد.</p></section><section class=\"pa\"><span class=\"n\">۲۲</span><p class=\"ar\">اللّٰهُمَّ فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ أَكْثَرَ مَا صَلَّيْتَ عَلَى أَحَدٍ مِنْ خَلْقِكَ، وَآتِهِ عَنَّا أَفْضَلَ مَا آتَيْتَ أَحَداً مِنْ عِبَادِكَ، وَاجْزِهِ عَنَّا أَفْضَلَ وَأَكْرَمَ مَا جَزَيْتَ أَحَداً مِنْ أَنْبِيَائِكَ عَنْ أُمَّتِهِ،</p><p class=\"fa\">خدایا، پس بر محمد و خاندانش درود فرست، بیش از هر درودی که بر یکی از آفریدگانت فرستادی، و از سوی ما بهترین چیزی را به او بده که به یکی از بندگانت دادی، و از سوی ما برتر و گرامی‌ترین پاداشی را به او بده که به یکی از پیامبرانت از سوی امتش دادی.</p></section><section class=\"pa\"><span class=\"n\">۲۳</span><p class=\"ar\">إِنَّكَ أَنْتَ الْمَنَّانُ بِالْجَسِيمِ، الْغَافِرُ لِلْعَظِيمِ، وَأَنْتَ أَرْحَمُ مِنْ كُلِّ رَحِيمٍ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ الطَّيِّبِينَ الطَّاهِرِينَ الْأَخْيَارِ الْأَنْجَبِينَ.</p><p class=\"fa\">که تو بخشندهٔ نعمت‌های بزرگی، و آمرزندهٔ گناه بزرگی، و تو از هر مهربانی مهربان‌تری؛ پس بر محمد و خاندان پاکیزه، پاک، نیکان و برگزیدگانش درود فرست.</p></section>"}, {"id": "s7", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۷", "title": "دعا در کارهای مهم و سختی‌ها", "sub": "وقتی کار مهمی پیش آمد یا گرفتاری‌ای رسید", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ إِذَا عَرَضَتْ لَهُ مُهِمَّةٌ أَوْ نَزَلَتْ بِهِ مُلِمَّةٌ وَعِنْدَ الْكَرْبِ</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) هنگامی که کار مهمی پیش می‌آمد یا گرفتاری‌ای فرود می‌آمد، و هنگام اندوه سخت</p><div class=\"player\"><span>🔊 قرائت دعای ۷ (عربی)</span><audio controls preload=\"none\" src=\"audio/dua7.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">يَا مَنْ تُحَلُّ بِهِ عُقَدُ الْمَكَارِهِ، وَيَا مَنْ يُفْثَأُ بِهِ حَدُّ الشَّدَائِدِ، وَيَا مَنْ يُلْتَمَسُ مِنْهُ الْمَخْرَجُ إِلَى رَوْحِ الْفَرَجِ،</p><p class=\"fa\">ای کسی که گره‌های ناخوشایندی‌ها به [دست] او گشوده می‌شود، و ای کسی که تیزی سختی‌ها به [دست] او کُند می‌گردد، و ای کسی که راه بیرون شدن به سوی آسایشِ گشایش از او خواسته می‌شود،</p></section><section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">ذَلَّتْ لِقُدْرَتِكَ الصِّعَابُ، وَتَسَبَّبَتْ بِلُطْفِكَ الْأَسْبَابُ، وَجَرَى بِقُدْرَتِكَ الْقَضَاءُ، وَمَضَتْ عَلَى إِرَادَتِكَ الْأَشْيَاءُ،</p><p class=\"fa\">کارهای دشوار در برابر قدرت تو رام شده‌اند، و سبب‌ها به لطف تو سبب شده‌اند، و قضا به قدرت تو جاری گشته، و همه چیز بر پایهٔ ارادهٔ تو پیش رفته است؛</p></section><section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">فَهِيَ بِمَشِيَّتِكَ دُونَ قَوْلِكَ مُؤْتَمِرَةٌ، وَبِإِرَادَتِكَ دُونَ نَهْيِكَ مُنْزَجِرَةٌ.</p><p class=\"fa\">پس همه چیز به خواست تو، بی‌آنکه سخنی بگویی، فرمان‌بردار است، و به ارادهٔ تو، بی‌آنکه نهی کنی، بازمی‌ایستد.</p></section><section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">أَنْتَ الْمَدْعُوُّ لِلْمُهِمَّاتِ، وَأَنْتَ الْمَفْزَعُ فِي الْمُلِمَّاتِ، لَا يَنْدَفِعُ مِنْهَا إِلَّا مَا دَفَعْتَ، وَلَا يَنْكَشِفُ مِنْهَا إِلَّا مَا كَشَفْتَ.</p><p class=\"fa\">تویی که برای کارهای مهم خوانده می‌شوی، و تویی پناهگاه در پیشامدهای سخت؛ از آنها چیزی دفع نمی‌شود مگر آنچه تو دفع کنی، و چیزی برطرف نمی‌شود مگر آنچه تو برطرف کنی.</p></section><section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">وَقَدْ نَزَلَ بِي يَا رَبِّ مَا قَدْ تَكَأَّدَنِي ثِقْلُهُ، وَأَلَمَّ بِي مَا قَدْ بَهَظَنِي حَمْلُهُ، وَبِقُدْرَتِكَ أَوْرَدْتَهُ عَلَيَّ، وَبِسُلْطَانِكَ وَجَّهْتَهُ إِلَيَّ،</p><p class=\"fa\">و پروردگارا، بر من چیزی فرود آمده که سنگینی‌اش مرا به رنج انداخته، و به من چیزی رسیده که بردنش مرا از پا درآورده است؛ و تو به قدرتت آن را بر من وارد کردی، و به فرمانروایی‌ات آن را به سوی من روانه ساختی.</p></section><section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">فَلَا مُصْدِرَ لِمَا أَوْرَدْتَ، وَلَا صَارِفَ لِمَا وَجَّهْتَ، وَلَا فَاتِحَ لِمَا أَغْلَقْتَ، وَلَا مُغْلِقَ لِمَا فَتَحْتَ، وَلَا مُيَسِّرَ لِمَا عَسَّرْتَ، وَلَا نَاصِرَ لِمَنْ خَذَلْتَ،</p><p class=\"fa\">پس آنچه را تو وارد کرده‌ای کسی بیرون نمی‌برد، و آنچه را روانه کرده‌ای کسی بازنمی‌گرداند، و آنچه را بسته‌ای کسی نمی‌گشاید، و آنچه را گشوده‌ای کسی نمی‌بندد، و آنچه را دشوار کرده‌ای کسی آسان نمی‌کند، و کسی را که تو وانهاده‌ای کسی یاری نمی‌کند.</p></section><section class=\"pa\"><span class=\"n\">۷</span><p class=\"ar\">فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَافْتَحْ لِي يَا رَبِّ بَابَ الْفَرَجِ بِطَوْلِكَ، وَاكْسِرْ عَنِّي سُلْطَانَ الْهَمِّ بِحَوْلِكَ، وَأَنِلْنِي حُسْنَ النَّظَرِ فِيمَا شَكَوْتُ، وَأَذِقْنِي حَلَاوَةَ الصُّنْعِ فِيمَا سَأَلْتُ،</p><p class=\"fa\">پس بر محمد و خاندانش درود فرست، و پروردگارا، با بخشش خود درِ گشایش را به رویم بگشا، و با نیروی خود چیرگی اندوه را از من بشکن، و در آنچه شکایت کردم نگاه نیکویت را به من برسان، و در آنچه خواستم شیرینی کارسازی‌ات را به من بچشان.</p></section><section class=\"pa\"><span class=\"n\">۸</span><p class=\"ar\">وَهَبْ لِي مِنْ لَدُنْكَ رَحْمَةً وَفَرَجاً هَنِيئاً، وَاجْعَلْ لِي مِنْ عِنْدِكَ مَخْرَجاً وَحِيّاً، وَلَا تَشْغَلْنِي بِالِاهْتِمَامِ عَنْ تَعَاهُدِ فُرُوضِكَ، وَاسْتِعْمَالِ سُنَّتِكَ،</p><p class=\"fa\">و از نزد خود رحمتی و گشایشی گوارا به من ببخش، و از جانب خود راه بیرون شدنی شتابان برایم قرار ده، و مرا با این دل‌نگرانی از پایبندی به واجباتت و به کار بستن سنت تو بازمدار.</p></section><section class=\"pa\"><span class=\"n\">۹</span><p class=\"ar\">فَقَدْ ضِقْتُ لِمَا نَزَلَ بِي يَا رَبِّ ذَرْعاً، وَامْتَلَأْتُ بِحَمْلِ مَا حَدَثَ عَلَيَّ هَمّاً، وَأَنْتَ الْقَادِرُ عَلَى كَشْفِ مَا مُنِيتُ بِهِ، وَدَفْعِ مَا وَقَعْتُ فِيهِ،</p><p class=\"fa\">پروردگارا، از آنچه بر من فرود آمده طاقتم تنگ شده، و از بردن بار آنچه بر من پیش آمده سرشار از اندوه شده‌ام؛ و تویی که بر برطرف کردن آنچه بدان گرفتار شده‌ام، و دفع آنچه در آن افتاده‌ام توانایی.</p></section><section class=\"pa\"><span class=\"n\">۱۰</span><p class=\"ar\">فَافْعَلْ بِي ذَلِكَ وَإِنْ لَمْ أَسْتَوْجِبْهُ مِنْكَ، يَا ذَا الْعَرْشِ الْعَظِيمِ.</p><p class=\"fa\">پس این کار را با من بکن، هرچند از تو سزاوارش نباشم؛ ای صاحب عرش بزرگ.</p></section><section class=\"pa\"><span class=\"n\">۱۱</span><p class=\"ar\">وَذَا الْمَنِّ الْكَرِيمِ، فَأَنْتَ قَادِرٌ يَا أَرْحَمَ الرَّاحِمِينَ، آمِينَ رَبَّ الْعَالَمِينَ.</p><p class=\"fa\">[این بند در برخی نسخه‌ها هست:] و ای صاحب نعمت بزرگوارانه؛ که تو توانایی، ای مهربان‌ترین مهربانان. آمین، ای پروردگار جهانیان.</p></section>"}, {"id": "s8", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۸", "title": "پناه بردن از بدی‌ها و خوی‌های زشت", "sub": "پناه از حرص، خشم، حسد و هر بدی", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي الِاسْتِعَاذَةِ مِنَ الْمَكَارِهِ، وَسَيِّئِ الْأَخْلَاقِ، وَمَذَامِّ الْأَفْعَالِ</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) در پناه بردن [به خدا] از ناخوشایندی‌ها، خوی‌های بد و کارهای نکوهیده</p><div class=\"player\"><span>🔊 قرائت دعای ۸ (عربی)</span><audio controls preload=\"none\" src=\"audio/dua8.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ هَيَجَانِ الْحِرْصِ، وَسَوْرَةِ الْغَضَبِ، وَغَلَبَةِ الْحَسَدِ، وَضَعْفِ الصَّبْرِ، وَقِلَّةِ الْقَنَاعَةِ، وَشَكَاسَةِ الْخُلُقِ، وَإِلْحَاحِ الشَّهْوَةِ، وَمَلَكَةِ الْحَمِيَّةِ،</p><p class=\"fa\">خدایا، به تو پناه می‌برم از برانگیختگی حرص، و تندی خشم، و چیرگی حسد، و سستی صبر، و کمی قناعت، و بدخویی، و پافشاری شهوت، و چیرگی تعصب،</p></section><section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">وَمُتَابَعَةِ الْهَوَى، وَمُخَالَفَةِ الْهُدَى، وَسِنَةِ الْغَفْلَةِ، وَتَعَاطِي الْكُلْفَةِ، وَإِيثَارِ الْبَاطِلِ عَلَى الْحَقِّ، وَالْإِصْرَارِ عَلَى الْمَأْثَمِ، وَاسْتِصْغَارِ الْمَعْصِيَةِ، وَاسْتِكْبَارِ الطَّاعَةِ،</p><p class=\"fa\">و پیروی از هوس، و مخالفت با هدایت، و خواب سبک غفلت، و خود را به رنجِ [کارهای بی‌جا] انداختن، و برگزیدن باطل بر حق، و پافشاری بر گناه، و کوچک شمردن نافرمانی، و بزرگ شمردن طاعت [خود]،</p></section><section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">وَمُبَاهَاةِ الْمُكْثِرِينَ، وَالْإِزْرَاءِ بِالْمُقِلِّينَ، وَسُوءِ الْوِلَايَةِ لِمَنْ تَحْتَ أَيْدِينَا، وَتَرْكِ الشُّكْرِ لِمَنِ اصْطَنَعَ الْعَارِفَةَ عِنْدَنَا،</p><p class=\"fa\">و فخرفروشی به ثروتمندان، و خوار شمردن تهیدستان، و بد سرپرستی کردنِ زیردستانمان، و سپاس نگزاردن از کسی که به ما نیکی کرده است،</p></section><section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">أَوْ أَنْ نَعْضُدَ ظَالِماً، أَوْ نَخْذُلَ مَلْهُوفاً، أَوْ نَرُومَ مَا لَيْسَ لَنَا بِحَقٍّ، أَوْ نَقُولَ فِي الْعِلْمِ بِغَيْرِ عِلْمٍ.</p><p class=\"fa\">یا اینکه ستمگری را یاری کنیم، یا ستمدیدهٔ دادخواه را تنها بگذاریم، یا چیزی را بخواهیم که حق ما نیست، یا دربارهٔ دانش بی‌دانش سخن بگوییم.</p></section><section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">وَنَعُوذُ بِكَ أَنْ نَنْطَوِيَ عَلَى غِشِّ أَحَدٍ، وَأَنْ نُعْجَبَ بِأَعْمَالِنَا، وَنَمُدَّ فِي آمَالِنَا،</p><p class=\"fa\">و به تو پناه می‌بریم از اینکه در دل با کسی ناخالصی و فریب داشته باشیم، و از اینکه به کارهای خود ببالیم، و آرزوهایمان را دراز کنیم.</p></section><section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">وَنَعُوذُ بِكَ مِنْ سُوءِ السَّرِيرَةِ، وَاحْتِقَارِ الصَّغِيرَةِ، وَأَنْ يَسْتَحْوِذَ عَلَيْنَا الشَّيْطَانُ، أَوْ يَنْكُبَنَا الزَّمَانُ، أَوْ يَتَهَضَّمَنَا السُّلْطَانُ،</p><p class=\"fa\">و به تو پناه می‌بریم از بدیِ درون، و ناچیز شمردن گناه کوچک، و از اینکه شیطان بر ما چیره شود، یا روزگار ما را گرفتار کند، یا فرمانروا بر ما ستم کند.</p></section><section class=\"pa\"><span class=\"n\">۷</span><p class=\"ar\">وَنَعُوذُ بِكَ مِنْ تَنَاوُلِ الْإِسْرَافِ، وَمِنْ فِقْدَانِ الْكَفَافِ، وَنَعُوذُ بِكَ مِنْ شَمَاتَةِ الْأَعْدَاءِ، وَمِنَ الْفَقْرِ إِلَى الْأَكْفَاءِ، وَمِنْ مَعِيشَةٍ فِي شِدَّةٍ، وَمِيتَةٍ عَلَى غَيْرِ عُدَّةٍ،</p><p class=\"fa\">و به تو پناه می‌بریم از دست زدن به اسراف، و از نداشتن روزیِ به‌اندازه؛ و به تو پناه می‌بریم از شماتت دشمنان، و از نیازمندی به هم‌ترازان، و از زندگی در سختی، و از مرگی بی‌توشه.</p></section><section class=\"pa\"><span class=\"n\">۸</span><p class=\"ar\">وَنَعُوذُ بِكَ مِنَ الْحَسْرَةِ الْعُظْمَى، وَالْمُصِيبَةِ الْكُبْرَى، وَأَشْقَى الشَّقَاءِ، وَسُوءِ الْمَآبِ، وَحِرْمَانِ الثَّوَابِ، وَحُلُولِ الْعِقَابِ.</p><p class=\"fa\">و به تو پناه می‌بریم از بزرگ‌ترین حسرت، و بزرگ‌ترین مصیبت، و بدترینِ بدبختی، و بدیِ بازگشت، و محرومیت از پاداش، و فرود آمدن کیفر.</p></section><section class=\"pa\"><span class=\"n\">۹</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَأَعِذْنِي مِنْ كُلِّ ذَلِكَ بِرَحْمَتِكَ وَجَمِيعَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ، يَا أَرْحَمَ الرَّاحِمِينَ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و به رحمتت مرا و همهٔ مردان و زنان مؤمن را از همهٔ اینها پناه ده؛ ای مهربان‌ترین مهربانان.</p></section>"}, {"id": "s17", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۱۷", "title": "پناه بردن از شیطان", "sub": "پناه از وسوسه و نیرنگ شیطان، برای خود و خانواده", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ إِذَا ذُكِرَ الشَّيْطَانُ فَاسْتَعَاذَ مِنْهُ وَمِنْ عَدَاوَتِهِ وَكَيْدِهِ</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) هنگامی که از شیطان یاد می‌شد و از او و دشمنی و نیرنگش [به خدا] پناه می‌برد</p><div class=\"player\"><span>🔊 قرائت دعای ۱۷ (عربی)</span><audio controls preload=\"none\" src=\"audio/dua17.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">اللّٰهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ نَزَغَاتِ الشَّيْطَانِ الرَّجِيمِ وَكَيْدِهِ وَمَكَائِدِهِ، وَمِنَ الثِّقَةِ بِأَمَانِيِّهِ وَمَوَاعِيدِهِ وَغُرُورِهِ وَمَصَائِدِهِ،</p><p class=\"fa\">خدایا، به تو پناه می‌بریم از وسوسه‌های شیطان رانده‌شده و نیرنگ و دام‌هایش، و از اعتماد کردن به آرزوها و وعده‌ها و فریب و تله‌هایش؛</p></section><section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">وَأَنْ يُطْمِعَ نَفْسَهُ فِي إِضْلَالِنَا عَنْ طَاعَتِكَ، وَامْتِهَانِنَا بِمَعْصِيَتِكَ، أَوْ أَنْ يَحْسُنَ عِنْدَنَا مَا حَسَّنَ لَنَا، أَوْ أَنْ يَثْقُلَ عَلَيْنَا مَا كَرَّهَ إِلَيْنَا.</p><p class=\"fa\">و از اینکه در گمراه کردن ما از طاعتت و خوار کردن ما با نافرمانی‌ات به خود امید دهد، یا آنچه را برای ما آراسته در نظرمان نیکو آید، یا آنچه را ناپسند جلوه داده بر ما سنگین آید.</p></section><section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">اللّٰهُمَّ اخْسَأْهُ عَنَّا بِعِبَادَتِكَ، وَاكْبِتْهُ بِدُؤُوبِنَا فِي مَحَبَّتِكَ، وَاجْعَلْ بَيْنَنَا وَبَيْنَهُ سِتْراً لَا يَهْتِكُهُ، وَرَدْماً مُصْمَتاً لَا يَفْتُقُهُ.</p><p class=\"fa\">خدایا، با عبادتت او را از ما دور و خوار کن، و با کوشش پیوستهٔ ما در محبتت سرکوبش کن، و میان ما و او پرده‌ای قرار ده که آن را ندرد، و سدّی یکپارچه که آن را نشکافد.</p></section><section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاشْغَلْهُ عَنَّا بِبَعْضِ أَعْدَائِكَ، وَاعْصِمْنَا مِنْهُ بِحُسْنِ رِعَايَتِكَ، وَاكْفِنَا خَتْرَهُ، وَوَلِّنَا ظَهْرَهُ، وَاقْطَعْ عَنَّا إِثْرَهُ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و او را با برخی از دشمنانت از ما سرگرم کن، و با نگهبانی نیکویت ما را از او نگاه دار، و ما را از پیمان‌شکنی و فریبش کفایت کن، و او را پشت‌کرده به ما بازگردان، و ردّ پایش را از ما ببُر.</p></section><section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَأَمْتِعْنَا مِنَ الْهُدَى بِمِثْلِ ضَلَالَتِهِ، وَزَوِّدْنَا مِنَ التَّقْوَى ضِدَّ غَوَايَتِهِ، وَاسْلُكْ بِنَا مِنَ التُّقَى خِلَافَ سَبِيلِهِ مِنَ الرَّدَى.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و ما را به اندازهٔ گمراهی‌اش از هدایت بهره‌مند کن، و از پرهیزگاری، ضدِّ گمراه‌گری‌اش را توشهٔ ما کن، و ما را از راه پرهیزگاری، برخلاف راه هلاکت‌بارش ببر.</p></section><section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">اللّٰهُمَّ لَا تَجْعَلْ لَهُ فِي قُلُوبِنَا مَدْخَلاً، وَلَا تُوطِنَنَّ لَهُ فِيمَا لَدَيْنَا مَنْزِلاً.</p><p class=\"fa\">خدایا، برای او در دل‌های ما راهی برای درآمدن قرار مده، و در آنچه نزد ماست برایش جایگاهی ماندگار مگذار.</p></section><section class=\"pa\"><span class=\"n\">۷</span><p class=\"ar\">اللّٰهُمَّ وَمَا سَوَّلَ لَنَا مِنْ بَاطِلٍ فَعَرِّفْنَاهُ، وَإِذَا عَرَّفْتَنَاهُ فَقِنَاهُ، وَبَصِّرْنَا مَا نُكَائِدُهُ بِهِ، وَأَلْهِمْنَا مَا نُعِدُّهُ لَهُ، وَأَيْقِظْنَا عَنْ سِنَةِ الْغَفْلَةِ بِالرُّكُونِ إِلَيْهِ، وَأَحْسِنْ بِتَوْفِيقِكَ عَوْنَنَا عَلَيْهِ.</p><p class=\"fa\">خدایا، هر باطلی را که برای ما آراست به ما بشناسان، و چون شناساندی ما را از آن نگاه دار؛ و آنچه را با آن با او مقابله کنیم به ما بنما، و آنچه را برای [رویارویی با] او آماده کنیم به دلمان بینداز، و ما را از خواب سبکِ غفلت که با تکیه بر او پیش می‌آید بیدار کن، و با توفیقت یاری ما را بر او نیکو گردان.</p></section><section class=\"pa\"><span class=\"n\">۸</span><p class=\"ar\">اللّٰهُمَّ وَأَشْرِبْ قُلُوبَنَا إِنْكَارَ عَمَلِهِ، وَالْطُفْ لَنَا فِي نَقْضِ حِيَلِهِ.</p><p class=\"fa\">خدایا، و انکار کار او را در دل‌های ما بنشان، و در درهم شکستن نیرنگ‌هایش با ما لطف کن.</p></section><section class=\"pa\"><span class=\"n\">۹</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَحَوِّلْ سُلْطَانَهُ عَنَّا، وَاقْطَعْ رَجَاءَهُ مِنَّا، وَادْرَأْهُ عَنِ الْوُلُوعِ بِنَا.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و چیرگی‌اش را از ما بگردان، و امیدش را از ما ببُر، و او را از چسبیدن و آزمندی به ما بازدار.</p></section><section class=\"pa\"><span class=\"n\">۱۰</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْ آبَاءَنَا وَأُمَّهَاتِنَا وَأَوْلَادَنَا وَأَهَالِيَنَا وَذَوِي أَرْحَامِنَا وَقَرَابَاتِنَا وَجِيرَانَنَا مِنَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ مِنْهُ فِي حِرْزٍ حَارِزٍ، وَحِصْنٍ حَافِظٍ، وَكَهْفٍ مَانِعٍ،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و پدران و مادران و فرزندان و خانواده‌ها و خویشان و نزدیکان و همسایگان مؤمن ما را از او در پناهی استوار، و دژی نگهدارنده، و پناهگاهی بازدارنده قرار ده؛</p></section><section class=\"pa\"><span class=\"n\">۱۱</span><p class=\"ar\">وَأَلْبِسْهُمْ مِنْهُ جُنَناً وَاقِيَةً، وَأَعْطِهِمْ عَلَيْهِ أَسْلِحَةً مَاضِيَةً.</p><p class=\"fa\">و بر آنان در برابر او سپرهایی نگهدارنده بپوشان، و برای [مقابله با] او سلاح‌هایی برّنده به آنان بده.</p></section><section class=\"pa\"><span class=\"n\">۱۲</span><p class=\"ar\">اللّٰهُمَّ وَاعْمُمْ بِذَلِكَ مَنْ شَهِدَ لَكَ بِالرُّبُوبِيَّةِ، وَأَخْلَصَ لَكَ بِالْوَحْدَانِيَّةِ، وَعَادَاهُ لَكَ بِحَقِيقَةِ الْعُبُودِيَّةِ، وَاسْتَظْهَرَ بِكَ عَلَيْهِ فِي مَعْرِفَةِ الْعُلُومِ الرَّبَّانِيَّةِ.</p><p class=\"fa\">خدایا، و این را شامل حال هر کس کن که به پروردگاری‌ات گواهی داده، و با یگانه دانستنت خود را برای تو خالص کرده، و با بندگی راستین برای تو با او دشمنی کرده، و در شناخت دانش‌های الهی بر ضد او از تو پشتیبانی خواسته است.</p></section><section class=\"pa\"><span class=\"n\">۱۳</span><p class=\"ar\">اللّٰهُمَّ احْلُلْ مَا عَقَدَ، وَافْتُقْ مَا رَتَقَ، وَافْسَخْ مَا دَبَّرَ، وَثَبِّطْهُ إِذَا عَزَمَ، وَانْقُضْ مَا أَبْرَمَ.</p><p class=\"fa\">خدایا، آنچه را گره زده بگشا، و آنچه را به هم دوخته بشکاف، و آنچه را تدبیر کرده باطل کن، و هرگاه قصد کرد بازش دار، و آنچه را محکم کرده درهم بشکن.</p></section><section class=\"pa\"><span class=\"n\">۱۴</span><p class=\"ar\">اللّٰهُمَّ وَاهْزِمْ جُنْدَهُ، وَأَبْطِلْ كَيْدَهُ، وَاهْدِمْ كَهْفَهُ، وَأَرْغِمْ أَنْفَهُ.</p><p class=\"fa\">خدایا، و لشکرش را شکست ده، و نیرنگش را باطل کن، و پناهگاهش را ویران کن، و بینی‌اش را به خاک بمال.</p></section><section class=\"pa\"><span class=\"n\">۱۵</span><p class=\"ar\">اللّٰهُمَّ اجْعَلْنَا فِي نَظْمِ أَعْدَائِهِ، وَاعْزِلْنَا عَنْ عِدَادِ أَوْلِيَائِهِ، لَا نُطِيعُ لَهُ إِذَا اسْتَهْوَانَا، وَلَا نَسْتَجِيبُ لَهُ إِذَا دَعَانَا، نَأْمُرُ بِمُنَاوَاتِهِ مَنْ أَطَاعَ أَمْرَنَا، وَنَعِظُ عَنْ مُتَابَعَتِهِ مَنِ اتَّبَعَ زَجْرَنَا.</p><p class=\"fa\">خدایا، ما را در رشتهٔ دشمنان او قرار ده، و از شمار دوستانش جدا کن؛ تا هرگاه ما را به هوس بخواند فرمانش نبریم، و هرگاه ما را فرا خواند پاسخش ندهیم؛ و هر کس فرمان ما را می‌برد به دشمنی با او فرمان دهیم، و هر کس از بازداشتن ما پیروی می‌کند از پیروی او پندش دهیم.</p></section><section class=\"pa\"><span class=\"n\">۱۶</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ خَاتَمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ، وَعَلَى أَهْلِ بَيْتِهِ الطَّيِّبِينَ الطَّاهِرِينَ،</p><p class=\"fa\">خدایا، بر محمد، پایان‌بخش پیامبران و سرور فرستادگان، و بر خاندان پاکیزه و پاکش درود فرست؛</p></section><section class=\"pa\"><span class=\"n\">۱۷</span><p class=\"ar\">وَأَعِذْنَا وَأَهَالِيَنَا وَإِخْوَانَنَا وَجَمِيعَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ مِمَّا اسْتَعَذْنَا مِنْهُ، وَأَجِرْنَا مِمَّا اسْتَجَرْنَا بِكَ مِنْ خَوْفِهِ،</p><p class=\"fa\">و ما و خانواده‌ها و برادرانمان و همهٔ مردان و زنان مؤمن را از آنچه از آن پناه خواستیم پناه ده، و از ترسِ آنچه از آن به تو امان جستیم امانمان ده؛</p></section><section class=\"pa\"><span class=\"n\">۱۸</span><p class=\"ar\">وَاسْمَعْ لَنَا مَا دَعَوْنَا بِهِ، وَأَعْطِنَا مَا أَغْفَلْنَاهُ، وَاحْفَظْ لَنَا مَا نَسِينَاهُ، وَصَيِّرْنَا بِذَلِكَ فِي دَرَجَاتِ الصَّالِحِينَ، وَمَرَاتِبِ الْمُؤْمِنِينَ، آمِينَ رَبَّ الْعَالَمِينَ.</p><p class=\"fa\">و آنچه را با آن تو را خواندیم بشنو [و بپذیر]، و آنچه را از آن غافل ماندیم به ما عطا کن، و آنچه را فراموش کردیم برایمان نگاه دار، و با این [ها] ما را به درجه‌های شایستگان و مرتبه‌های مؤمنان برسان. آمین، ای پروردگار جهانیان.</p></section>"}, {"id": "s20", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۲۰", "title": "دعای مکارم الاخلاق", "sub": "درخواست خوی‌های نیک و کارهای پسندیده", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي مَكَارِمِ الْأَخْلَاقِ وَمَرْضِيِّ الْأَفْعَالِ</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) در [درخواست] خوی‌های بزرگوارانه و کارهای پسندیده</p><div class=\"player\"><span>🔊 قرائت دعای ۲۰ (عربی)</span><audio controls preload=\"none\" src=\"audio/dua20.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَبَلِّغْ بِإِيمَانِي أَكْمَلَ الْإِيمَانِ، وَاجْعَلْ يَقِينِي أَفْضَلَ الْيَقِينِ، وَانْتَهِ بِنِيَّتِي إِلَى أَحْسَنِ النِّيَّاتِ، وَبِعَمَلِي إِلَى أَحْسَنِ الْأَعْمَالِ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و ایمانم را به کامل‌ترین ایمان برسان، و یقینم را برترین یقین قرار ده، و نیتم را به بهترین نیت‌ها، و کارم را به بهترین کارها برسان.</p></section><section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">اللّٰهُمَّ وَفِّرْ بِلُطْفِكَ نِيَّتِي، وَصَحِّحْ بِمَا عِنْدَكَ يَقِينِي، وَاسْتَصْلِحْ بِقُدْرَتِكَ مَا فَسَدَ مِنِّي.</p><p class=\"fa\">خدایا، با لطفت نیتم را کامل کن، و با آنچه نزد توست یقینم را درست گردان، و با قدرتت آنچه از من تباه شده را اصلاح کن.</p></section><section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاكْفِنِي مَا يَشْغَلُنِي الِاهْتِمَامُ بِهِ، وَاسْتَعْمِلْنِي بِمَا تَسْأَلُنِي غَداً عَنْهُ، وَاسْتَفْرِغْ أَيَّامِي فِيمَا خَلَقْتَنِي لَهُ،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مرا از آنچه دل‌مشغولی به آن سرگرمم می‌کند کفایت کن، و مرا به کاری بگمار که فردا [ی قیامت] از آن بازخواستم می‌کنی، و روزهایم را در راهی که برای آن آفریده‌ای صرف کن.</p></section><section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">وَأَغْنِنِي وَأَوْسِعْ عَلَيَّ فِي رِزْقِكَ، وَلَا تَفْتِنِّي بِالنَّظَرِ، وَأَعِزَّنِي وَلَا تَبْتَلِيَنِّي بِالْكِبْرِ، وَعَبِّدْنِي لَكَ وَلَا تُفْسِدْ عِبَادَتِي بِالْعُجْبِ، وَأَجْرِ لِلنَّاسِ عَلَى يَدِيَ الْخَيْرَ وَلَا تَمْحَقْهُ بِالْمَنِّ، وَهَبْ لِي مَعَالِيَ الْأَخْلَاقِ، وَاعْصِمْنِي مِنَ الْفَخْرِ.</p><p class=\"fa\">و بی‌نیازم کن و روزی‌ات را بر من گشاده گردان، و مرا با چشم دوختن [به دارایی دیگران] گرفتار مکن، و عزیزم کن و به تکبر مبتلایم مساز، و مرا بندهٔ خودت کن و عبادتم را با خودپسندی تباه مکن، و خیر را برای مردم به دست من روان کن و آن را با منت گذاشتن نابود مکن، و خوی‌های والا را به من ببخش، و مرا از فخرفروشی نگاه دار.</p></section><section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَلَا تَرْفَعْنِي فِي النَّاسِ دَرَجَةً إِلَّا حَطَطْتَنِي عِنْدَ نَفْسِي مِثْلَهَا، وَلَا تُحْدِثْ لِي عِزّاً ظَاهِراً إِلَّا أَحْدَثْتَ لِي ذِلَّةً بَاطِنَةً عِنْدَ نَفْسِي بِقَدَرِهَا.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مرا در میان مردم درجه‌ای بالا مبر مگر آنکه به همان اندازه در نظر خودم پایینم آوری، و برایم عزتی آشکار پدید میاور مگر آنکه به اندازهٔ آن، در نظر خودم فروتنیِ پنهانی برایم پدید آوری.</p></section><section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَمَتِّعْنِي بِهُدًى صَالِحٍ لَا أَسْتَبْدِلُ بِهِ، وَطَرِيقَةِ حَقٍّ لَا أَزِيغُ عَنْهَا، وَنِيَّةِ رُشْدٍ لَا أَشُكُّ فِيهَا،</p><p class=\"fa\">خدایا، بر محمد و خاندان محمد درود فرست، و مرا از هدایتی شایسته که آن را با چیزی عوض نکنم، و راه حقی که از آن منحرف نشوم، و نیت درستی که در آن تردید نکنم بهره‌مند ساز.</p></section><section class=\"pa\"><span class=\"n\">۷</span><p class=\"ar\">وَعَمِّرْنِي مَا كَانَ عُمُرِي بِذْلَةً فِي طَاعَتِكَ، فَإِذَا كَانَ عُمُرِي مَرْتَعاً لِلشَّيْطَانِ فَاقْبِضْنِي إِلَيْكَ قَبْلَ أَنْ يَسْبِقَ مَقْتُكَ إِلَيَّ، أَوْ يَسْتَحْكِمَ غَضَبُكَ عَلَيَّ.</p><p class=\"fa\">و تا وقتی عمرم در طاعت تو به کار می‌رود، عمرم ده؛ و هرگاه عمرم چراگاه شیطان شد، پیش از آنکه بیزاری‌ات به سویم بشتابد یا خشمت بر من استوار گردد، جانم را به سوی خود بگیر.</p></section><section class=\"pa\"><span class=\"n\">۸</span><p class=\"ar\">اللّٰهُمَّ لَا تَدَعْ خَصْلَةً تُعَابُ مِنِّي إِلَّا أَصْلَحْتَهَا، وَلَا عَائِبَةً أُؤَنَّبُ بِهَا إِلَّا حَسَّنْتَهَا، وَلَا أُكْرُومَةً فِيَّ نَاقِصَةً إِلَّا أَتْمَمْتَهَا.</p><p class=\"fa\">خدایا، هیچ خصلتی در من که سرزنش شود وامگذار مگر آنکه اصلاحش کنی، و هیچ عیبی که به خاطرش نکوهش شوم مگر آنکه نیکویش کنی، و هیچ خوی بزرگوارانهٔ ناقصی در من مگر آنکه کاملش کنی.</p></section><section class=\"pa\"><span class=\"n\">۹</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَأَبْدِلْنِي مِنْ بِغْضَةِ أَهْلِ الشَّنَآنِ الْمَحَبَّةَ، وَمِنْ حَسَدِ أَهْلِ الْبَغْيِ الْمَوَدَّةَ، وَمِنْ ظِنَّةِ أَهْلِ الصَّلَاحِ الثِّقَةَ، وَمِنْ عَدَاوَةِ الْأَدْنَيْنَ الْوَلَايَةَ، وَمِنْ عُقُوقِ ذَوِي الْأَرْحَامِ الْمَبَرَّةَ،</p><p class=\"fa\">خدایا، بر محمد و خاندان محمد درود فرست، و به جای کینهٔ کینه‌توزان محبت، و به جای حسد ستمگران دوستی، و به جای بدگمانی شایستگان اعتماد، و به جای دشمنی نزدیکان دوستی و یاری، و به جای بدرفتاری خویشاوندان نیکی را نصیبم کن،</p></section><section class=\"pa\"><span class=\"n\">۱۰</span><p class=\"ar\">وَمِنْ خِذْلَانِ الْأَقْرَبِينَ النُّصْرَةَ، وَمِنْ حُبِّ الْمُدَارِينَ تَصْحِيحَ الْمِقَةِ، وَمِنْ رَدِّ الْمُلَابِسِينَ كَرَمَ الْعِشْرَةِ، وَمِنْ مَرَارَةِ خَوْفِ الظَّالِمِينَ حَلَاوَةَ الْأَمَنَةِ.</p><p class=\"fa\">و به جای تنها گذاشتنِ نزدیکان یاری، و به جای دوستیِ ظاهریِ مدارا‌کنندگان دوستیِ راستین، و به جای طرد شدن از سوی معاشران رفتار بزرگوارانه، و به جای تلخی ترس از ستمگران شیرینی امنیت را.</p></section><section class=\"pa\"><span class=\"n\">۱۱</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْ لِي يَداً عَلَى مَنْ ظَلَمَنِي، وَلِسَاناً عَلَى مَنْ خَاصَمَنِي، وَظَفَراً بِمَنْ عَانَدَنِي، وَهَبْ لِي مَكْراً عَلَى مَنْ كَايَدَنِي، وَقُدْرَةً عَلَى مَنِ اضْطَهَدَنِي، وَتَكْذِيباً لِمَنْ قَصَبَنِي، وَسَلَامَةً مِمَّنْ تَوَعَّدَنِي،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و برایم در برابر کسی که به من ستم کرده توانی، و در برابر کسی که با من ستیزه کرده زبانی [گویا]، و بر کسی که با من دشمنی ورزیده پیروزی قرار ده؛ و در برابر کسی که با من نیرنگ کرده تدبیری، و بر کسی که به من زور گفته توانی، و برای [رد] کسی که به من عیب بسته دلیلی بر دروغش، و از کسی که مرا تهدید کرده سلامتی به من ببخش.</p></section><section class=\"pa\"><span class=\"n\">۱۲</span><p class=\"ar\">وَوَفِّقْنِي لِطَاعَةِ مَنْ سَدَّدَنِي، وَمُتَابَعَةِ مَنْ أَرْشَدَنِي.</p><p class=\"fa\">و مرا به فرمان‌برداری از کسی که استوارم می‌دارد، و پیروی از کسی که راهنمایی‌ام می‌کند، توفیق ده.</p></section><section class=\"pa\"><span class=\"n\">۱۳</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَسَدِّدْنِي لِأَنْ أُعَارِضَ مَنْ غَشَّنِي بِالنُّصْحِ، وَأَجْزِيَ مَنْ هَجَرَنِي بِالْبِرِّ، وَأُثِيبَ مَنْ حَرَمَنِي بِالْبَذْلِ، وَأُكَافِئَ مَنْ قَطَعَنِي بِالصِّلَةِ، وَأُخَالِفَ مَنِ اغْتَابَنِي إِلَى حُسْنِ الذِّكْرِ، وَأَنْ أَشْكُرَ الْحَسَنَةَ، وَأُغْضِيَ عَنِ السَّيِّئَةِ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و استوارم کن تا با کسی که با من دغلی کرده با خیرخواهی روبه‌رو شوم، و به کسی که از من دوری کرده با نیکی پاداش دهم، و به کسی که مرا محروم کرده با بخشش عوض دهم، و کسی را که از من بریده با پیوند جبران کنم، و برخلاف کسی که پشت سرم بدگویی کرده، از او به نیکی یاد کنم، و نیکی را سپاس گویم، و از بدی چشم بپوشم.</p></section><section class=\"pa\"><span class=\"n\">۱۴</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَحَلِّنِي بِحِلْيَةِ الصَّالِحِينَ، وَأَلْبِسْنِي زِينَةَ الْمُتَّقِينَ، فِي بَسْطِ الْعَدْلِ، وَكَظْمِ الْغَيْظِ، وَإِطْفَاءِ النَّائِرَةِ، وَضَمِّ أَهْلِ الْفُرْقَةِ، وَإِصْلَاحِ ذَاتِ الْبَيْنِ، وَإِفْشَاءِ الْعَارِفَةِ، وَسَتْرِ الْعَائِبَةِ،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مرا به زیور شایستگان بیارای، و جامهٔ زینت پرهیزگاران را بر من بپوشان: در گستردن عدالت، و فرو خوردن خشم، و خاموش کردن آتش دشمنی، و گرد آوردن پراکندگان، و آشتی دادن میان مردم، و آشکار کردن نیکی، و پوشاندن عیب،</p></section><section class=\"pa\"><span class=\"n\">۱۵</span><p class=\"ar\">وَلِينِ الْعَرِيكَةِ، وَخَفْضِ الْجَنَاحِ، وَحُسْنِ السِّيرَةِ، وَسُكُونِ الرِّيحِ، وَطِيبِ الْمُخَالَقَةِ، وَالسَّبْقِ إِلَى الْفَضِيلَةِ، وَإِيثَارِ التَّفَضُّلِ، وَتَرْكِ التَّعْيِيرِ، وَالْإِفْضَالِ عَلَى غَيْرِ الْمُسْتَحِقِّ،</p><p class=\"fa\">و نرم‌خویی، و فروتنی، و نیک‌رفتاری، و آرامش و وقار، و خوش‌برخوردی، و پیشی گرفتن در فضیلت، و برگزیدن بخشش، و ترک سرزنش کردن، و نیکی به کسی که سزاوارش نیست،</p></section><section class=\"pa\"><span class=\"n\">۱۶</span><p class=\"ar\">وَالْقَوْلِ بِالْحَقِّ وَإِنْ عَزَّ، وَاسْتِقْلَالِ الْخَيْرِ وَإِنْ كَثُرَ مِنْ قَوْلِي وَفِعْلِي، وَاسْتِكْثَارِ الشَّرِّ وَإِنْ قَلَّ مِنْ قَوْلِي وَفِعْلِي،</p><p class=\"fa\">و گفتن حق هرچند دشوار باشد، و اندک شمردن خوبیِ گفتار و کردارم هرچند بسیار باشد، و بسیار شمردن بدیِ گفتار و کردارم هرچند اندک باشد.</p></section><section class=\"pa\"><span class=\"n\">۱۷</span><p class=\"ar\">وَأَكْمِلْ ذَلِكَ لِي بِدَوَامِ الطَّاعَةِ، وَلُزُومِ الْجَمَاعَةِ، وَرَفْضِ أَهْلِ الْبِدَعِ، وَمُسْتَعْمِلِ الرَّأْيِ الْمُخْتَرَعِ.</p><p class=\"fa\">و این‌ها را برایم با پایداری در طاعت، و همراهی با جماعت [حق]، و کنار گذاشتن اهل بدعت و کسانی که رأیِ ساختگی را به کار می‌بندند، کامل کن.</p></section><section class=\"pa\"><span class=\"n\">۱۸</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْ أَوْسَعَ رِزْقِكَ عَلَيَّ إِذَا كَبِرْتُ، وَأَقْوَى قُوَّتِكَ فِيَّ إِذَا نَصِبْتُ، وَلَا تَبْتَلِيَنِّي بِالْكَسَلِ عَنْ عِبَادَتِكَ، وَلَا الْعَمَى عَنْ سَبِيلِكَ، وَلَا بِالتَّعَرُّضِ لِخِلَافِ مَحَبَّتِكَ، وَلَا مُجَامَعَةِ مَنْ تَفَرَّقَ عَنْكَ، وَلَا مُفَارَقَةِ مَنِ اجْتَمَعَ إِلَيْكَ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و گشاده‌ترین روزی‌ات را هنگام پیری‌ام، و نیرومندترین نیرویت را هنگام خستگی‌ام در من قرار ده؛ و مرا به سستی در عبادتت، و کوری از راهت، و رفتن به سوی آنچه برخلاف محبت توست، و همراهی با کسی که از تو جدا شده، و جدایی از کسی که به سوی تو گرد آمده، گرفتار مکن.</p></section><section class=\"pa\"><span class=\"n\">۱۹</span><p class=\"ar\">اللّٰهُمَّ اجْعَلْنِي أَصُولُ بِكَ عِنْدَ الضَّرُورَةِ، وَأَسْأَلُكَ عِنْدَ الْحَاجَةِ، وَأَتَضَرَّعُ إِلَيْكَ عِنْدَ الْمَسْكَنَةِ،</p><p class=\"fa\">خدایا، چنانم کن که هنگام ناچاری به [نیروی] تو حمله کنم، و هنگام نیاز از تو بخواهم، و هنگام بیچارگی به درگاهت زاری کنم؛</p></section><section class=\"pa\"><span class=\"n\">۲۰</span><p class=\"ar\">وَلَا تَفْتِنِّي بِالِاسْتِعَانَةِ بِغَيْرِكَ إِذَا اضْطُرِرْتُ، وَلَا بِالْخُضُوعِ لِسُؤَالِ غَيْرِكَ إِذَا افْتَقَرْتُ، وَلَا بِالتَّضَرُّعِ إِلَى مَنْ دُونَكَ إِذَا رَهِبْتُ، فَأَسْتَحِقَّ بِذَلِكَ خِذْلَانَكَ وَمَنْعَكَ وَإِعْرَاضَكَ، يَا أَرْحَمَ الرَّاحِمِينَ.</p><p class=\"fa\">و مرا به یاری خواستن از غیر تو هنگام ناچاری، و به فروتنی برای درخواست از غیر تو هنگام نیاز، و به زاری کردن نزد کسی جز تو هنگام ترس گرفتار مکن، که با این کار سزاوار وانهادن و بازداشتن و روی‌گردانی تو شوم؛ ای مهربان‌ترین مهربانان.</p></section><section class=\"pa\"><span class=\"n\">۲۱</span><p class=\"ar\">اللّٰهُمَّ اجْعَلْ مَا يُلْقِي الشَّيْطَانُ فِي رُوعِي مِنَ التَّمَنِّي وَالتَّظَنِّي وَالْحَسَدِ ذِكْراً لِعَظَمَتِكَ، وَتَفَكُّراً فِي قُدْرَتِكَ، وَتَدْبِيراً عَلَى عَدُوِّكَ،</p><p class=\"fa\">خدایا، آنچه شیطان از آرزوپروری و بدگمانی و حسد در دلم می‌افکند، به یاد بزرگی‌ات، و اندیشیدن در قدرتت، و چاره‌اندیشی در برابر دشمنت تبدیل کن؛</p></section><section class=\"pa\"><span class=\"n\">۲۲</span><p class=\"ar\">وَمَا أَجْرَى عَلَى لِسَانِي مِنْ لَفْظَةِ فُحْشٍ، أَوْ هُجْرٍ، أَوْ شَتْمِ عِرْضٍ، أَوْ شَهَادَةِ بَاطِلٍ، أَوِ اغْتِيَابِ مُؤْمِنٍ غَائِبٍ، أَوْ سَبِّ حَاضِرٍ، وَمَا أَشْبَهَ ذَلِكَ، نُطْقاً بِالْحَمْدِ لَكَ، وَإِغْرَاقاً فِي الثَّنَاءِ عَلَيْكَ، وَذَهَاباً فِي تَمْجِيدِكَ، وَشُكْراً لِنِعْمَتِكَ، وَاعْتِرَافاً بِإِحْسَانِكَ، وَإِحْصَاءً لِمِنَنِكَ.</p><p class=\"fa\">و هر سخن زشت، یا یاوه، یا دشنام به آبروی کسی، یا گواهی باطل، یا غیبت مؤمنی که حاضر نیست، یا ناسزا به حاضر، و مانند اینها را که [شیطان] بر زبانم می‌آورد، به گفتن ستایش تو، و غرق شدن در ثنای تو، و پیش رفتن در بزرگداشت تو، و سپاس نعمتت، و اعتراف به نیکی‌ات، و برشمردن منت‌هایت تبدیل کن.</p></section><section class=\"pa\"><span class=\"n\">۲۳</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَلَا أُظْلَمَنَّ وَأَنْتَ مُطِيقٌ لِلدَّفْعِ عَنِّي، وَلَا أَظْلِمَنَّ وَأَنْتَ الْقَادِرُ عَلَى الْقَبْضِ مِنِّي، وَلَا أَضِلَّنَّ وَقَدْ أَمْكَنَتْكَ هِدَايَتِي، وَلَا أَفْتَقِرَنَّ وَمِنْ عِنْدِكَ وُسْعِي، وَلَا أَطْغَيَنَّ وَمِنْ عِنْدِكَ وُجْدِي.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مبادا به من ستم شود در حالی که تو توان دفع آن از من را داری، و مبادا ستم کنم در حالی که تو بر بازداشتنم توانایی، و مبادا گمراه شوم در حالی که هدایتم برایت ممکن است، و مبادا نیازمند شوم در حالی که گشایشم از نزد توست، و مبادا سرکش شوم در حالی که توانگری‌ام از نزد توست.</p></section><section class=\"pa\"><span class=\"n\">۲۴</span><p class=\"ar\">اللّٰهُمَّ إِلَى مَغْفِرَتِكَ وَفَدْتُ، وَإِلَى عَفْوِكَ قَصَدْتُ، وَإِلَى تَجَاوُزِكَ اشْتَقْتُ، وَبِفَضْلِكَ وَثِقْتُ، وَلَيْسَ عِنْدِي مَا يُوجِبُ لِي مَغْفِرَتَكَ، وَلَا فِي عَمَلِي مَا أَسْتَحِقُّ بِهِ عَفْوَكَ، وَمَا لِي بَعْدَ أَنْ حَكَمْتُ عَلَى نَفْسِي إِلَّا فَضْلُكَ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَتَفَضَّلْ عَلَيَّ.</p><p class=\"fa\">خدایا، به سوی آمرزشت آمده‌ام، و آهنگ گذشتت کرده‌ام، و مشتاق چشم‌پوشی‌ات شده‌ام، و به فضلت اعتماد کرده‌ام؛ و نزد من چیزی نیست که آمرزشت را برایم واجب کند، و در کارم چیزی نیست که با آن سزاوار گذشتت شوم، و پس از آنکه بر ضد خود حکم کردم، جز فضل تو چیزی ندارم؛ پس بر محمد و خاندانش درود فرست، و بر من فضل کن.</p></section><section class=\"pa\"><span class=\"n\">۲۵</span><p class=\"ar\">اللّٰهُمَّ وَأَنْطِقْنِي بِالْهُدَى، وَأَلْهِمْنِي التَّقْوَى، وَوَفِّقْنِي لِلَّتِي هِيَ أَزْكَى، وَاسْتَعْمِلْنِي بِمَا هُوَ أَرْضَى.</p><p class=\"fa\">خدایا، و مرا به هدایت گویا کن، و پرهیزگاری را به دلم بیفکن، و به آنچه پاکیزه‌تر است توفیقم ده، و به آنچه پسندیده‌تر است بگمارم.</p></section><section class=\"pa\"><span class=\"n\">۲۶</span><p class=\"ar\">اللّٰهُمَّ اسْلُكْ بِيَ الطَّرِيقَةَ الْمُثْلَى، وَاجْعَلْنِي عَلَى مِلَّتِكَ أَمُوتُ وَأَحْيَا.</p><p class=\"fa\">خدایا، مرا در بهترین راه ببر، و چنانم کن که بر آیین تو بمیرم و زنده باشم.</p></section><section class=\"pa\"><span class=\"n\">۲۷</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَمَتِّعْنِي بِالِاقْتِصَادِ، وَاجْعَلْنِي مِنْ أَهْلِ السَّدَادِ، وَمِنْ أَدِلَّةِ الرَّشَادِ، وَمِنْ صَالِحِ الْعِبَادِ، وَارْزُقْنِي فَوْزَ الْمَعَادِ، وَسَلَامَةَ الْمِرْصَادِ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مرا از میانه‌روی بهره‌مند کن، و مرا از اهل درستی، و از راهنمایان به راه راست، و از بندگان شایسته قرار ده، و رستگاری روز بازگشت و سلامت در گذرگاهِ [حساب] را روزی‌ام کن.</p></section><section class=\"pa\"><span class=\"n\">۲۸</span><p class=\"ar\">اللّٰهُمَّ خُذْ لِنَفْسِكَ مِنْ نَفْسِي مَا يُخَلِّصُهَا، وَأَبْقِ لِنَفْسِي مِنْ نَفْسِي مَا يُصْلِحُهَا، فَإِنَّ نَفْسِي هَالِكَةٌ أَوْ تَعْصِمَهَا.</p><p class=\"fa\">خدایا، از جانم برای خودت آن را بگیر که رهایی‌اش دهد، و از جانم برای خودم آن را باقی گذار که سامانش دهد؛ زیرا جانم نابود است مگر آنکه تو نگاهش داری.</p></section><section class=\"pa\"><span class=\"n\">۲۹</span><p class=\"ar\">اللّٰهُمَّ أَنْتَ عُدَّتِي إِنْ حَزِنْتُ، وَأَنْتَ مُنْتَجَعِي إِنْ حُرِمْتُ، وَبِكَ اسْتِغَاثَتِي إِنْ كَرِثْتُ، وَعِنْدَكَ مِمَّا فَاتَ خَلَفٌ، وَلِمَا فَسَدَ صَلَاحٌ، وَفِيمَا أَنْكَرْتَ تَغْيِيرٌ،</p><p class=\"fa\">خدایا، اگر اندوهگین شوم تو ساز و برگ منی، و اگر محروم شوم تو مقصد منی، و اگر گرفتار شوم فریادخواهی‌ام از توست؛ و نزد توست جایگزینِ آنچه از دست رفته، و اصلاحِ آنچه تباه شده، و دگرگون کردنِ آنچه ناپسند داشتی.</p></section><section class=\"pa\"><span class=\"n\">۳۰</span><p class=\"ar\">فَامْنُنْ عَلَيَّ قَبْلَ الْبَلَاءِ بِالْعَافِيَةِ، وَقَبْلَ الطَّلَبِ بِالْجِدَةِ، وَقَبْلَ الضَّلَالِ بِالرَّشَادِ، وَاكْفِنِي مَؤُونَةَ مَعَرَّةِ الْعِبَادِ، وَهَبْ لِي أَمْنَ يَوْمِ الْمَعَادِ، وَامْنَحْنِي حُسْنَ الْإِرْشَادِ.</p><p class=\"fa\">پس پیش از بلا با عافیت، و پیش از درخواست با توانگری، و پیش از گمراهی با راه راست بر من منت گذار؛ و مرا از رنج آزار بندگان کفایت کن، و امنیت روز بازگشت را به من ببخش، و راهنمایی نیکو را به من عطا کن.</p></section><section class=\"pa\"><span class=\"n\">۳۱</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَادْرَأْ عَنِّي بِلُطْفِكَ، وَاغْذُنِي بِنِعْمَتِكَ، وَأَصْلِحْنِي بِكَرَمِكَ، وَدَاوِنِي بِصُنْعِكَ، وَأَظِلَّنِي فِي ذَرَاكَ، وَجَلِّلْنِي رِضَاكَ،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و با لطفت [بدی‌ها را] از من دور کن، و با نعمتت مرا بپرور، و با کرمت اصلاحم کن، و با کارسازی‌ات درمانم کن، و در پناهت بر من سایه افکن، و خشنودی‌ات را سراپای من بپوشان.</p></section><section class=\"pa\"><span class=\"n\">۳۲</span><p class=\"ar\">وَوَفِّقْنِي إِذَا اشْتَكَلَتْ عَلَيَّ الْأُمُورُ لِأَهْدَاهَا، وَإِذَا تَشَابَهَتِ الْأَعْمَالُ لِأَزْكَاهَا، وَإِذَا تَنَاقَضَتِ الْمِلَلُ لِأَرْضَاهَا.</p><p class=\"fa\">و هرگاه کارها بر من مشتبه شد، به درست‌ترینشان، و هرگاه کارها به هم ماننده شد، به پاکیزه‌ترینشان، و هرگاه آیین‌ها با هم ناسازگار شد، به پسندیده‌ترینشان توفیقم ده.</p></section><section class=\"pa\"><span class=\"n\">۳۳</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَتَوِّجْنِي بِالْكِفَايَةِ، وَسُمْنِي حُسْنَ الْوِلَايَةِ، وَهَبْ لِي صِدْقَ الْهِدَايَةِ، وَلَا تَفْتِنِّي بِالسَّعَةِ، وَامْنَحْنِي حُسْنَ الدَّعَةِ، وَلَا تَجْعَلْ عَيْشِي كَدّاً كَدّاً، وَلَا تَرُدَّ دُعَائِي عَلَيَّ رَدّاً، فَإِنِّي لَا أَجْعَلُ لَكَ ضِدّاً، وَلَا أَدْعُو مَعَكَ نِدّاً.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و تاج بی‌نیازی بر سرم بگذار، و سرپرستی نیکو را نشان من کن، و هدایت راستین را به من ببخش، و مرا با گشایش [مال] گرفتار مکن، و آسایش نیکو به من عطا کن، و زندگی‌ام را رنج پشت رنج قرار مده، و دعایم را به من بازمگردان؛ زیرا من برای تو ضدی قرار نمی‌دهم، و همتایی را همراه تو نمی‌خوانم.</p></section><section class=\"pa\"><span class=\"n\">۳۴</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَامْنَعْنِي مِنَ السَّرَفِ، وَحَصِّنْ رِزْقِي مِنَ التَّلَفِ، وَوَفِّرْ مَلَكَتِي بِالْبَرَكَةِ فِيهِ، وَأَصِبْ بِي سَبِيلَ الْهِدَايَةِ لِلْبِرِّ فِيمَا أُنْفِقُ مِنْهُ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مرا از اسراف بازدار، و روزی‌ام را از تباه شدن نگاه دار، و دارایی‌ام را با برکت دادن در آن فزونی بخش، و در آنچه از آن خرج می‌کنم، مرا به راه درستِ نیکوکاری برسان.</p></section><section class=\"pa\"><span class=\"n\">۳۵</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاكْفِنِي مَؤُونَةَ الِاكْتِسَابِ، وَارْزُقْنِي مِنْ غَيْرِ احْتِسَابٍ، فَلَا أَشْتَغِلَ عَنْ عِبَادَتِكَ بِالطَّلَبِ، وَلَا أَحْتَمِلَ إِصْرَ تَبِعَاتِ الْمَكْسَبِ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مرا از رنج کسب کفایت کن، و از جایی که گمان ندارم روزی‌ام ده، تا با جستجوی روزی از عبادتت بازنمانم، و بار سنگین پیامدهای کسب را بر دوش نکشم.</p></section><section class=\"pa\"><span class=\"n\">۳۶</span><p class=\"ar\">اللّٰهُمَّ فَأَطْلِبْنِي بِقُدْرَتِكَ مَا أَطْلُبُ، وَأَجِرْنِي بِعِزَّتِكَ مِمَّا أَرْهَبُ.</p><p class=\"fa\">خدایا، پس با قدرتت آنچه را می‌جویم برایم فراهم کن، و با عزتت از آنچه می‌ترسم پناهم ده.</p></section><section class=\"pa\"><span class=\"n\">۳۷</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَصُنْ وَجْهِي بِالْيَسَارِ، وَلَا تَبْتَذِلْ جَاهِي بِالْإِقْتَارِ، فَأَسْتَرْزِقَ أَهْلَ رِزْقِكَ، وَأَسْتَعْطِيَ شِرَارَ خَلْقِكَ، فَأَفْتَتِنَ بِحَمْدِ مَنْ أَعْطَانِي، وَأُبْتَلَى بِذَمِّ مَنْ مَنَعَنِي، وَأَنْتَ مِنْ دُونِهِمْ وَلِيُّ الْإِعْطَاءِ وَالْمَنْعِ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و آبرویم را با توانگری نگاه دار، و جایگاهم را با تنگدستی بی‌ارزش مکن، که از روزی‌خورانِ تو روزی بخواهم، و از بدترین آفریدگانت بخشش طلبم، و آنگاه به ستایش کسی که به من داده گرفتار شوم، و به نکوهش کسی که دریغ کرده مبتلا گردم؛ در حالی که تو، نه آنان، صاحب اختیار دادن و ندادنی.</p></section><section class=\"pa\"><span class=\"n\">۳۸</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَارْزُقْنِي صِحَّةً فِي عِبَادَةٍ، وَفَرَاغاً فِي زَهَادَةٍ، وَعِلْماً فِي اسْتِعْمَالٍ، وَوَرَعاً فِي إِجْمَالٍ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و تندرستی همراه با عبادت، و فراغت همراه با بی‌رغبتی به دنیا، و دانشی همراه با به کار بستن، و پارسایی همراه با میانه‌روی را روزی‌ام کن.</p></section><section class=\"pa\"><span class=\"n\">۳۹</span><p class=\"ar\">اللّٰهُمَّ اخْتِمْ بِعَفْوِكَ أَجَلِي، وَحَقِّقْ فِي رَجَاءِ رَحْمَتِكَ أَمَلِي، وَسَهِّلْ إِلَى بُلُوغِ رِضَاكَ سُبُلِي، وَحَسِّنْ فِي جَمِيعِ أَحْوَالِي عَمَلِي.</p><p class=\"fa\">خدایا، پایان عمرم را با گذشتت به سر رسان، و آرزویم را در امید به رحمتت تحقق بخش، و راه‌هایم را برای رسیدن به خشنودی‌ات هموار کن، و کارم را در همهٔ حالاتم نیکو گردان.</p></section><section class=\"pa\"><span class=\"n\">۴۰</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَنَبِّهْنِي لِذِكْرِكَ فِي أَوْقَاتِ الْغَفْلَةِ، وَاسْتَعْمِلْنِي بِطَاعَتِكَ فِي أَيَّامِ الْمُهْلَةِ، وَانْهَجْ لِي إِلَى مَحَبَّتِكَ سَبِيلاً سَهْلَةً، أَكْمِلْ لِي بِهَا خَيْرَ الدُّنْيَا وَالْآخِرَةِ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و در هنگام‌های غفلت مرا به یاد خود بیدار کن، و در روزهای مهلت مرا به طاعتت بگمار، و راهی هموار به سوی محبتت برایم بگشا، که با آن خیر دنیا و آخرت را برایم کامل کنی.</p></section><section class=\"pa\"><span class=\"n\">۴۱</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، كَأَفْضَلِ مَا صَلَّيْتَ عَلَى أَحَدٍ مِنْ خَلْقِكَ قَبْلَهُ، وَأَنْتَ مُصَلٍّ عَلَى أَحَدٍ بَعْدَهُ، وَآتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً، وَقِنِي بِرَحْمَتِكَ عَذَابَ النَّارِ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، مانند برترین درودی که پیش از او بر یکی از آفریدگانت فرستادی، و پس از او بر کسی خواهی فرستاد؛ و در دنیا به ما نیکی و در آخرت نیکی عطا کن، و به رحمتت مرا از عذاب آتش نگاه دار.</p></section>"}, {"id": "s21", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۲۱", "title": "دعا هنگام اندوه و نگرانی از گناه", "sub": "تنهایی، ترس و پناه بردن به خدا", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ إِذَا حَزَنَهُ أَمْرٌ وَأَهَمَّتْهُ الْخَطَايَا</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) هنگامی که کاری اندوهگینش می‌کرد و گناهان نگرانش می‌ساخت</p><div class=\"player\"><span>🔊 قرائت دعای ۲۱ (عربی)</span><audio controls preload=\"none\" src=\"audio/dua21.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">اللّٰهُمَّ يَا كَافِيَ الْفَرْدِ الضَّعِيفِ، وَوَاقِيَ الْأَمْرِ الْمَخُوفِ، أَفْرَدَتْنِي الْخَطَايَا فَلَا صَاحِبَ مَعِي، وَضَعُفْتُ عَنْ غَضَبِكَ فَلَا مُؤَيِّدَ لِي، وَأَشْرَفْتُ عَلَى خَوْفِ لِقَائِكَ فَلَا مُسَكِّنَ لِرَوْعَتِي،</p><p class=\"fa\">خدایا، ای کفایت‌کنندهٔ تنهای ناتوان، و ای نگه‌دارنده از کار هراسناک، گناهان مرا تنها کرده‌اند و همراهی ندارم، و در برابر خشم تو ناتوانم و پشتیبانی ندارم، و به ترسِ دیدارت نزدیک شده‌ام و کسی نیست که هراسم را آرام کند.</p></section><section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">وَمَنْ يُؤْمِنُنِي مِنْكَ وَأَنْتَ أَخَفْتَنِي، وَمَنْ يُسَاعِدُنِي وَأَنْتَ أَفْرَدْتَنِي، وَمَنْ يُقَوِّينِي وَأَنْتَ أَضْعَفْتَنِي.</p><p class=\"fa\">و چه کسی مرا از تو ایمن کند، حال آنکه تو مرا ترسانده‌ای؟ و چه کسی یاری‌ام دهد، حال آنکه تو تنهایم گذاشته‌ای؟ و چه کسی نیرومندم کند، حال آنکه تو ناتوانم ساخته‌ای؟</p></section><section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">لَا يُجِيرُ يَا إِلَهِي إِلَّا رَبٌّ عَلَى مَرْبُوبٍ، وَلَا يُؤْمِنُ إِلَّا غَالِبٌ عَلَى مَغْلُوبٍ، وَلَا يُعِينُ إِلَّا طَالِبٌ عَلَى مَطْلُوبٍ،</p><p class=\"fa\">معبودا، جز پروردگار به پرورده‌اش پناه نمی‌دهد، و جز چیره به مغلوبش امان نمی‌دهد، و جز جوینده کسی بر جسته‌شده یاری نمی‌رساند.</p></section><section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">وَبِيَدِكَ يَا إِلَهِي جَمِيعُ ذَلِكَ السَّبَبِ، وَإِلَيْكَ الْمَفَرُّ وَالْمَهْرَبُ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَأَجِرْ هَرَبِي، وَأَنْجِحْ مَطْلَبِي.</p><p class=\"fa\">و معبودا، همهٔ این رشته‌ها به دست توست، و گریزگاه و پناه به سوی توست؛ پس بر محمد و خاندانش درود فرست، و گریختنم [به سوی تو] را پناه ده، و خواسته‌ام را برآور.</p></section><section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">اللّٰهُمَّ إِنَّكَ إِنْ صَرَفْتَ عَنِّي وَجْهَكَ الْكَرِيمَ، أَوْ مَنَعْتَنِي فَضْلَكَ الْجَسِيمَ، أَوْ حَظَرْتَ عَلَيَّ رِزْقَكَ، أَوْ قَطَعْتَ عَنِّي سَبَبَكَ، لَمْ أَجِدِ السَّبِيلَ إِلَى شَيْءٍ مِنْ أَمَلِي غَيْرَكَ، وَلَمْ أَقْدِرْ عَلَى مَا عِنْدَكَ بِمَعُونَةِ سِوَاكَ،</p><p class=\"fa\">خدایا، اگر روی کریمت را از من بگردانی، یا فضل بزرگت را از من بازداری، یا روزی‌ات را بر من ببندی، یا رشتهٔ پیوندت را از من ببری، به هیچ چیز از آرزویم راهی جز تو نمی‌یابم، و با یاری کسی جز تو به آنچه نزد توست دست نمی‌یابم؛</p></section><section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">فَإِنِّي عَبْدُكَ وَفِي قَبْضَتِكَ، نَاصِيَتِي بِيَدِكَ، لَا أَمْرَ لِي مَعَ أَمْرِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، وَلَا قُوَّةَ لِي عَلَى الْخُرُوجِ مِنْ سُلْطَانِكَ، وَلَا أَسْتَطِيعُ مُجَاوَزَةَ قُدْرَتِكَ، وَلَا أَسْتَمِيلُ هَوَاكَ، وَلَا أَبْلُغُ رِضَاكَ، وَلَا أَنَالُ مَا عِنْدَكَ إِلَّا بِطَاعَتِكَ وَبِفَضْلِ رَحْمَتِكَ.</p><p class=\"fa\">زیرا من بندهٔ توام و در چنگ توام؛ اختیارم به دست توست؛ با فرمان تو مرا فرمانی نیست؛ حکمت دربارهٔ من روان است، و داوری‌ات دربارهٔ من عادلانه است؛ و مرا نیرویی برای بیرون رفتن از فرمانروایی‌ات نیست، و نمی‌توانم از قدرتت فراتر روم، و نمی‌توانم خواست تو را به سوی خود بگردانم، و به خشنودی‌ات نمی‌رسم، و به آنچه نزد توست دست نمی‌یابم، مگر با طاعتت و به فضل رحمتت.</p></section><section class=\"pa\"><span class=\"n\">۷</span><p class=\"ar\">إِلَهِي أَصْبَحْتُ وَأَمْسَيْتُ عَبْداً دَاخِراً لَكَ، لَا أَمْلِكُ لِنَفْسِي نَفْعاً وَلَا ضَرّاً إِلَّا بِكَ، أَشْهَدُ بِذَلِكَ عَلَى نَفْسِي، وَأَعْتَرِفُ بِضَعْفِ قُوَّتِي وَقِلَّةِ حِيلَتِي، فَأَنْجِزْ لِي مَا وَعَدْتَنِي، وَتَمِّمْ لِي مَا آتَيْتَنِي،</p><p class=\"fa\">معبودا، صبح و شام کردم در حالی که بنده‌ای فروتن برای توام؛ جز به [یاری] تو برای خودم سود و زیانی در اختیار ندارم؛ به این بر خود گواهی می‌دهم، و به سستی نیرو و کمی چاره‌ام اعتراف می‌کنم؛ پس آنچه را به من وعده دادی برایم انجام ده، و آنچه را به من دادی برایم کامل کن؛</p></section><section class=\"pa\"><span class=\"n\">۸</span><p class=\"ar\">فَإِنِّي عَبْدُكَ الْمِسْكِينُ الْمُسْتَكِينُ الضَّعِيفُ الضَّرِيرُ الذَّلِيلُ الْحَقِيرُ الْمَهِينُ الْفَقِيرُ الْخَائِفُ الْمُسْتَجِيرُ.</p><p class=\"fa\">زیرا من بندهٔ بیچاره، فروتن، ناتوان، درمانده، خوار، ناچیز، بی‌مقدار، نیازمند، ترسان و پناه‌جوی توام.</p></section><section class=\"pa\"><span class=\"n\">۹</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَلَا تَجْعَلْنِي نَاسِياً لِذِكْرِكَ فِيمَا أَوْلَيْتَنِي، وَلَا غَافِلاً لِإِحْسَانِكَ فِيمَا أَبْلَيْتَنِي، وَلَا آيِساً مِنْ إِجَابَتِكَ لِي وَإِنْ أَبْطَأَتْ عَنِّي، فِي سَرَّاءَ كُنْتُ أَوْ ضَرَّاءَ، أَوْ شِدَّةٍ أَوْ رَخَاءٍ، أَوْ عَافِيَةٍ أَوْ بَلَاءٍ، أَوْ بُؤْسٍ أَوْ نَعْمَاءَ، أَوْ جِدَةٍ أَوْ لَأْوَاءَ، أَوْ فَقْرٍ أَوْ غِنًى.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مرا در نعمت‌هایی که به من دادی فراموش‌کار یاد تو، و در آنچه به آن آزمودی‌ام غافل از نیکی‌ات، و از پاسخ دادنت به من، هرچند دیر کند، ناامید قرار مده؛ چه در شادی باشم یا در گرفتاری، در سختی یا آسایش، در عافیت یا بلا، در تنگدستی یا نعمت، در توانگری یا تنگنا، در فقر یا بی‌نیازی.</p></section><section class=\"pa\"><span class=\"n\">۱۰</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْ ثَنَائِي عَلَيْكَ، وَمَدْحِي إِيَّاكَ، وَحَمْدِي لَكَ فِي كُلِّ حَالَاتِي، حَتَّى لَا أَفْرَحَ بِمَا آتَيْتَنِي مِنَ الدُّنْيَا، وَلَا أَحْزَنَ عَلَى مَا مَنَعْتَنِي فِيهَا،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و ثنا و ستایش و سپاسم را برای تو در همهٔ حالاتم [پیوسته] قرار ده، تا به آنچه از دنیا به من دادی سرمست نشوم، و بر آنچه از آن بازم داشتی اندوهگین نگردم.</p></section><section class=\"pa\"><span class=\"n\">۱۱</span><p class=\"ar\">وَأَشْعِرْ قَلْبِي تَقْوَاكَ، وَاسْتَعْمِلْ بَدَنِي فِيمَا تَقْبَلُهُ مِنِّي، وَاشْغَلْ بِطَاعَتِكَ نَفْسِي عَنْ كُلِّ مَا يَرِدُ عَلَيَّ، حَتَّى لَا أُحِبَّ شَيْئاً مِنْ سُخْطِكَ، وَلَا أَسْخَطَ شَيْئاً مِنْ رِضَاكَ.</p><p class=\"fa\">و پروای خودت را با دلم همراه کن، و تنم را در کاری به کار گیر که از من بپذیری، و جانم را با طاعتت از هر چه بر من وارد می‌شود سرگرم کن، تا هیچ چیز از آنچه تو را خشمگین می‌کند دوست نداشته باشم، و از هیچ چیز که تو را خشنود می‌کند ناخشنود نباشم.</p></section><section class=\"pa\"><span class=\"n\">۱۲</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَفَرِّغْ قَلْبِي لِمَحَبَّتِكَ، وَاشْغَلْهُ بِذِكْرِكَ، وَانْعَشْهُ بِخَوْفِكَ وَبِالْوَجَلِ مِنْكَ، وَقَوِّهِ بِالرَّغْبَةِ إِلَيْكَ، وَأَمِلْهُ إِلَى طَاعَتِكَ، وَأَجْرِ بِهِ فِي أَحَبِّ السُّبُلِ إِلَيْكَ، وَذَلِّلْهُ بِالرَّغْبَةِ فِيمَا عِنْدَكَ أَيَّامَ حَيَاتِي كُلَّهَا.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و دلم را برای محبتت فارغ کن، و آن را به یادت سرگرم ساز، و با ترس و هراس از تو زنده‌اش بدار، و با اشتیاق به سویت نیرومندش کن، و به سوی طاعتت متمایلش ساز، و آن را در محبوب‌ترین راه‌ها نزد خودت روان کن، و در همهٔ روزهای زندگی‌ام با اشتیاق به آنچه نزد توست رامش گردان.</p></section><section class=\"pa\"><span class=\"n\">۱۳</span><p class=\"ar\">وَاجْعَلْ تَقْوَاكَ مِنَ الدُّنْيَا زَادِي، وَإِلَى رَحْمَتِكَ رِحْلَتِي، وَفِي مَرْضَاتِكَ مَدْخَلِي، وَاجْعَلْ فِي جَنَّتِكَ مَثْوَايَ، وَهَبْ لِي قُوَّةً أَحْتَمِلُ بِهَا جَمِيعَ مَرْضَاتِكَ، وَاجْعَلْ فِرَارِي إِلَيْكَ، وَرَغْبَتِي فِيمَا عِنْدَكَ،</p><p class=\"fa\">و پروای خودت را توشهٔ من از دنیا، و رحمتت را مقصد سفرم، و خشنودی‌ات را جای درآمدنم قرار ده، و جایگاهم را در بهشتت بگذار، و نیرویی به من ببخش که با آن همهٔ آنچه تو را خشنود می‌کند بر دوش کشم، و گریزم را به سوی خودت، و اشتیاقم را به آنچه نزد توست قرار ده.</p></section><section class=\"pa\"><span class=\"n\">۱۴</span><p class=\"ar\">وَأَلْبِسْ قَلْبِيَ الْوَحْشَةَ مِنْ شِرَارِ خَلْقِكَ، وَهَبْ لِيَ الْأُنْسَ بِكَ وَبِأَوْلِيَائِكَ وَأَهْلِ طَاعَتِكَ، وَلَا تَجْعَلْ لِفَاجِرٍ وَلَا كَافِرٍ عَلَيَّ مِنَّةً، وَلَا لَهُ عِنْدِي يَداً، وَلَا بِي إِلَيْهِمْ حَاجَةً،</p><p class=\"fa\">و بر دلم جامهٔ دوری از بدترین آفریدگانت بپوشان، و انس با خودت و دوستانت و اهل طاعتت را به من ببخش، و برای هیچ بدکار و کافری بر من منتی، و نزد من حق نعمتی، و مرا به آنان نیازی قرار مده.</p></section><section class=\"pa\"><span class=\"n\">۱۵</span><p class=\"ar\">بَلِ اجْعَلْ سُكُونَ قَلْبِي، وَأُنْسَ نَفْسِي، وَاسْتِغْنَائِي وَكِفَايَتِي بِكَ وَبِخِيَارِ خَلْقِكَ.</p><p class=\"fa\">بلکه آرامش دلم، و انس جانم، و بی‌نیازی و کفایتم را به خودت و به بهترین آفریدگانت قرار ده.</p></section><section class=\"pa\"><span class=\"n\">۱۶</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْنِي لَهُمْ قَرِيناً، وَاجْعَلْنِي لَهُمْ نَصِيراً، وَامْنُنْ عَلَيَّ بِشَوْقٍ إِلَيْكَ، وَبِالْعَمَلِ لَكَ بِمَا تُحِبُّ وَتَرْضَى، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، وَذَلِكَ عَلَيْكَ يَسِيرٌ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مرا هم‌نشین و یاور آنان قرار ده، و با شوق به خودت، و کار کردن برای تو به آنچه دوست داری و می‌پسندی، بر من منت گذار؛ که تو بر هر چیز توانایی، و این بر تو آسان است.</p></section>"}, {"id": "s23", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۲۳", "title": "دعای عافیت", "sub": "تندرستی، امنیت و پناه از هر بدخواه", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ إِذَا سَأَلَ اللّٰهَ الْعَافِيَةَ وَشُكْرَهَا</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) هنگامی که از خدا عافیت و سپاس‌گزاری بر آن را می‌خواست</p><div class=\"player\"><span>🔊 قرائت دعای ۲۳ (عربی)</span><audio controls preload=\"none\" src=\"audio/dua23.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَأَلْبِسْنِي عَافِيَتَكَ، وَجَلِّلْنِي عَافِيَتَكَ، وَحَصِّنِّي بِعَافِيَتِكَ، وَأَكْرِمْنِي بِعَافِيَتِكَ، وَأَغْنِنِي بِعَافِيَتِكَ، وَتَصَدَّقْ عَلَيَّ بِعَافِيَتِكَ، وَهَبْ لِي عَافِيَتَكَ، وَأَفْرِشْنِي عَافِيَتَكَ، وَأَصْلِحْ لِي عَافِيَتَكَ، وَلَا تُفَرِّقْ بَيْنِي وَبَيْنَ عَافِيَتِكَ فِي الدُّنْيَا وَالْآخِرَةِ.</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و عافیتت را بر من بپوشان، و با عافیتت سراپایم را فرا گیر، و با عافیتت مرا در پناه نگه دار، و با عافیتت گرامی‌ام بدار، و با عافیتت بی‌نیازم کن، و عافیتت را بر من صدقه ده، و عافیتت را به من ببخش، و عافیتت را بستر من کن، و عافیتت را برایم سامان ده، و در دنیا و آخرت میان من و عافیتت جدایی مینداز.</p></section><section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَعَافِنِي عَافِيَةً كَافِيَةً شَافِيَةً عَالِيَةً نَامِيَةً، عَافِيَةً تُوَلِّدُ فِي بَدَنِي الْعَافِيَةَ، عَافِيَةَ الدُّنْيَا وَالْآخِرَةِ،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مرا عافیتی ده بسنده، شفابخش، والا و فزاینده؛ عافیتی که در تنم عافیت بزاید؛ عافیت دنیا و آخرت.</p></section><section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">وَامْنُنْ عَلَيَّ بِالصِّحَّةِ وَالْأَمْنِ وَالسَّلَامَةِ فِي دِينِي وَبَدَنِي، وَالْبَصِيرَةِ فِي قَلْبِي، وَالنَّفَاذِ فِي أُمُورِي، وَالْخَشْيَةِ لَكَ، وَالْخَوْفِ مِنْكَ، وَالْقُوَّةِ عَلَى مَا أَمَرْتَنِي بِهِ مِنْ طَاعَتِكَ، وَالِاجْتِنَابِ لِمَا نَهَيْتَنِي عَنْهُ مِنْ مَعْصِيَتِكَ.</p><p class=\"fa\">و بر من منت گذار با تندرستی و امنیت و سلامت در دین و تنم، و بینش در دلم، و پیش رفتن در کارهایم، و خشیت برای تو، و ترس از تو، و نیرو بر طاعتی که به آن فرمانم دادی، و دوری از نافرمانی‌ای که از آن بازم داشتی.</p></section><section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">اللّٰهُمَّ وَامْنُنْ عَلَيَّ بِالْحَجِّ وَالْعُمْرَةِ، وَزِيَارَةِ قَبْرِ رَسُولِكَ، صَلَوَاتُكَ عَلَيْهِ وَرَحْمَتُكَ وَبَرَكَاتُكَ عَلَيْهِ وَعَلَى آلِهِ، وَآلِ رَسُولِكَ عَلَيْهِمُ السَّلَامُ، أَبَداً مَا أَبْقَيْتَنِي، فِي عَامِي هَذَا وَفِي كُلِّ عَامٍ، وَاجْعَلْ ذَلِكَ مَقْبُولاً مَشْكُوراً، مَذْكُوراً لَدَيْكَ، مَذْخُوراً عِنْدَكَ،</p><p class=\"fa\">خدایا، و بر من منت گذار با حج و عمره، و زیارت مزار پیامبرت، که درودها و رحمت و برکت‌هایت بر او و خاندانش باد، و [زیارت] خاندان پیامبرت، که سلام بر آنان باد؛ همیشه تا وقتی مرا زنده می‌داری، در امسال و در هر سال؛ و آن را پذیرفته و سپاس‌شده، و نزد خودت یادشده و اندوخته قرار ده.</p></section><section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">وَأَنْطِقْ بِحَمْدِكَ وَشُكْرِكَ وَذِكْرِكَ وَحُسْنِ الثَّنَاءِ عَلَيْكَ لِسَانِي، وَاشْرَحْ لِمَرَاشِدِ دِينِكَ قَلْبِي،</p><p class=\"fa\">و زبانم را به ستایش و سپاس و یاد تو و ثنای نیکو بر تو گویا کن، و دلم را برای راه‌های رشدِ دینت گشاده گردان.</p></section><section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">وَأَعِذْنِي وَذُرِّيَّتِي مِنَ الشَّيْطَانِ الرَّجِيمِ، وَمِنْ شَرِّ السَّامَّةِ وَالْهَامَّةِ وَالْعَامَّةِ وَاللَّامَّةِ، وَمِنْ شَرِّ كُلِّ شَيْطَانٍ مَرِيدٍ، وَمِنْ شَرِّ كُلِّ سُلْطَانٍ عَنِيدٍ، وَمِنْ شَرِّ كُلِّ مُتْرَفٍ حَفِيدٍ،</p><p class=\"fa\">و مرا و فرزندانم را از شیطان رانده‌شده پناه ده؛ و از شرّ جانوران زهردار، و حشرات گزنده، و بلاهای همگانی، و چشم‌زخم؛ و از شرّ هر شیطان سرکش، و از شرّ هر فرمانروای ستیزه‌جو، و از شرّ هر خوش‌گذرانِ برخوردار از یاوران.</p></section><section class=\"pa\"><span class=\"n\">۷</span><p class=\"ar\">وَمِنْ شَرِّ كُلِّ ضَعِيفٍ وَشَدِيدٍ، وَمِنْ شَرِّ كُلِّ شَرِيفٍ وَوَضِيعٍ، وَمِنْ شَرِّ كُلِّ صَغِيرٍ وَكَبِيرٍ، وَمِنْ شَرِّ كُلِّ قَرِيبٍ وَبَعِيدٍ، وَمِنْ شَرِّ كُلِّ مَنْ نَصَبَ لِرَسُولِكَ وَلِأَهْلِ بَيْتِهِ حَرْباً مِنَ الْجِنِّ وَالْإِنْسِ، وَمِنْ شَرِّ كُلِّ دَابَّةٍ أَنْتَ آخِذٌ بِنَاصِيَتِهَا، إِنَّكَ عَلَى صِرَاطٍ مُسْتَقِيمٍ.</p><p class=\"fa\">و از شرّ هر ناتوان و نیرومند، و از شرّ هر بلندپایه و فرومایه، و از شرّ هر کوچک و بزرگ، و از شرّ هر نزدیک و دور، و از شرّ هر کس از جن و انس که با پیامبرت و خاندانش به جنگ برخاسته، و از شرّ هر جنبنده‌ای که اختیارش به دست توست؛ که تو بر راه راستی.</p></section><section class=\"pa\"><span class=\"n\">۸</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَمَنْ أَرَادَنِي بِسُوءٍ فَاصْرِفْهُ عَنِّي، وَادْحَرْ عَنِّي مَكْرَهُ، وَادْرَأْ عَنِّي شَرَّهُ، وَرُدَّ كَيْدَهُ فِي نَحْرِهِ،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و هر کس با من قصد بدی دارد او را از من بگردان، و نیرنگش را از من دور کن، و شرّش را از من بازدار، و حیله‌اش را به گلوی خودش بازگردان.</p></section><section class=\"pa\"><span class=\"n\">۹</span><p class=\"ar\">وَاجْعَلْ بَيْنَ يَدَيْهِ سَدّاً حَتَّى تُعْمِيَ عَنِّي بَصَرَهُ، وَتُصِمَّ عَنْ ذِكْرِي سَمْعَهُ، وَتُقْفِلَ دُونَ إِخْطَارِي قَلْبَهُ، وَتُخْرِسَ عَنِّي لِسَانَهُ، وَتَقْمَعَ رَأْسَهُ، وَتُذِلَّ عِزَّهُ، وَتَكْسِرَ جَبَرُوتَهُ، وَتُذِلَّ رَقَبَتَهُ، وَتَفْسَخَ كِبْرَهُ،</p><p class=\"fa\">و پیش رویش سدّی قرار ده تا چشمش را از [دیدن] من ببندی، و گوشش را از شنیدن نام من ناشنوا کنی، و دلش را از به یاد آوردن من قفل کنی، و زبانش را از [بدگویی] من بازداری، و سرکشی‌اش را بکوبی، و عزتش را خوار کنی، و زورگویی‌اش را بشکنی، و گردنش را فروتن کنی، و تکبرش را درهم شکنی.</p></section><section class=\"pa\"><span class=\"n\">۱۰</span><p class=\"ar\">وَتُؤْمِنَنِي مِنْ جَمِيعِ ضَرِّهِ وَشَرِّهِ، وَغَمْزِهِ وَهَمْزِهِ وَلَمْزِهِ، وَحَسَدِهِ وَعَدَاوَتِهِ، وَحَبَائِلِهِ وَمَصَائِدِهِ، وَرَجِلِهِ وَخَيْلِهِ، إِنَّكَ عَزِيزٌ قَدِيرٌ.</p><p class=\"fa\">و مرا از همهٔ زیان و شرّش، و طعنه و بدگویی و عیب‌جویی‌اش، و حسد و دشمنی‌اش، و دام‌ها و تله‌هایش، و پیاده‌ها و سواره‌هایش ایمن داری؛ که تو شکست‌ناپذیر و توانایی.</p></section>"}, {"id": "s29", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۲۹", "title": "دعا هنگام تنگی روزی", "sub": "یقین و اعتماد به روزی‌رسانی خدا", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ إِذَا قُتِّرَ عَلَيْهِ الرِّزْقُ</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) هنگامی که روزی بر او تنگ می‌شد</p><div class=\"player\"><span>🔊 قرائت دعای ۲۹ (عربی)</span><audio controls preload=\"none\" src=\"audio/dua29.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">اللّٰهُمَّ إِنَّكَ ابْتَلَيْتَنَا فِي أَرْزَاقِنَا بِسُوءِ الظَّنِّ، وَفِي آجَالِنَا بِطُولِ الْأَمَلِ، حَتَّى الْتَمَسْنَا أَرْزَاقَكَ مِنْ عِنْدِ الْمَرْزُوقِينَ، وَطَمِعْنَا بِآمَالِنَا فِي أَعْمَارِ الْمُعَمَّرِينَ،</p><p class=\"fa\">خدایا، تو ما را در روزی‌هایمان به بدگمانی، و در اجل‌هایمان به آرزوی دراز آزمودی؛ تا آنجا که روزی تو را از نزد روزی‌خوران جستیم، و با آرزوهایمان به عمر سالخوردگان چشم طمع دوختیم.</p></section><section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَهَبْ لَنَا يَقِيناً صَادِقاً تَكْفِينَا بِهِ مِنْ مَؤُونَةِ الطَّلَبِ، وَأَلْهِمْنَا ثِقَةً خَالِصَةً تُعْفِينَا بِهَا مِنْ شِدَّةِ النَّصَبِ،</p><p class=\"fa\">پس بر محمد و خاندانش درود فرست، و به ما یقینی راستین ببخش که با آن ما را از رنجِ جستجو بی‌نیاز کنی، و اعتمادی خالص [به خودت] در دل ما بیفکن که با آن ما را از سختیِ تلاش و رنج معاف داری.</p></section><section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">وَاجْعَلْ مَا صَرَّحْتَ بِهِ مِنْ عِدَتِكَ فِي وَحْيِكَ، وَأَتْبَعْتَهُ مِنْ قَسَمِكَ فِي كِتَابِكَ، قَاطِعاً لِاهْتِمَامِنَا بِالرِّزْقِ الَّذِي تَكَفَّلْتَ بِهِ، وَحَسْماً لِلِاشْتِغَالِ بِمَا ضَمِنْتَ الْكِفَايَةَ لَهُ،</p><p class=\"fa\">و وعده‌ای را که در وحی‌ات آشکارا گفتی، و سوگندی را که در کتابت در پی آن آوردی، مایهٔ بریدن دل‌مشغولی ما به روزی‌ای قرار ده که خود عهده‌دارش شده‌ای، و مایهٔ پایان سرگرم شدن به چیزی که کفایتش را ضمانت کرده‌ای.</p></section><section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">فَقُلْتَ وَقَوْلُكَ الْحَقُّ الْأَصْدَقُ، وَأَقْسَمْتَ وَقَسَمُكَ الْأَبَرُّ الْأَوْفَى: ﴿وَفِي السَّمَاءِ رِزْقُكُمْ وَمَا تُوعَدُونَ﴾، ثُمَّ قُلْتَ: ﴿فَوَرَبِّ السَّمَاءِ وَالْأَرْضِ إِنَّهُ لَحَقٌّ مِثْلَ مَا أَنَّكُمْ تَنْطِقُونَ﴾.</p><p class=\"fa\">پس فرمودی، و سخن تو حق و راست‌ترین سخن است، و سوگند خوردی، و سوگند تو راست‌ترین و وفادارترین سوگند است: «و روزی شما و آنچه وعده داده می‌شوید در آسمان است» (ذاریات ۲۲)؛ سپس فرمودی: «پس سوگند به پروردگار آسمان و زمین که آن حق است، همان‌گونه که شما سخن می‌گویید» (ذاریات ۲۳).</p></section>"}, {"id": "s30", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۳۰", "title": "دعا برای ادای وام", "sub": "رهایی از بدهی و میانه‌روی در خرج", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي الْمَعُونَةِ عَلَى قَضَاءِ الدَّيْنِ</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) در یاری خواستن [از خدا] برای ادای وام</p><div class=\"player\"><span>🔊 قرائت دعای ۳۰ (عربی)</span><audio controls preload=\"none\" src=\"audio/dua30.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَهَبْ لِيَ الْعَافِيَةَ مِنْ دَيْنٍ تُخْلِقُ بِهِ وَجْهِي، وَيَحَارُ فِيهِ ذِهْنِي، وَيَتَشَعَّبُ لَهُ فِكْرِي، وَيَطُولُ بِمُمَارَسَتِهِ شُغْلِي،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مرا از وامی در امان دار که با آن آبرویم را می‌بری، و ذهنم در آن سرگردان می‌شود، و فکرم به خاطرش پراکنده می‌گردد، و گرفتاری‌ام با درگیر بودن با آن طولانی می‌شود.</p></section><section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">وَأَعُوذُ بِكَ يَا رَبِّ مِنْ هَمِّ الدَّيْنِ وَفِكْرِهِ، وَشُغْلِ الدَّيْنِ وَسَهَرِهِ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَأَعِذْنِي مِنْهُ،</p><p class=\"fa\">و پروردگارا، به تو پناه می‌برم از اندوه وام و فکر آن، و گرفتاری وام و بی‌خوابی‌اش؛ پس بر محمد و خاندانش درود فرست و مرا از آن پناه ده.</p></section><section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">وَأَسْتَجِيرُ بِكَ يَا رَبِّ مِنْ ذِلَّتِهِ فِي الْحَيَاةِ، وَمِنْ تَبِعَتِهِ بَعْدَ الْوَفَاةِ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَأَجِرْنِي مِنْهُ بِوُسْعٍ فَاضِلٍ أَوْ كَفَافٍ وَاصِلٍ.</p><p class=\"fa\">و پروردگارا، از خواری آن در زندگی و از پیامدش پس از مرگ به تو امان می‌جویم؛ پس بر محمد و خاندانش درود فرست، و مرا با گشایشی افزون، یا روزیِ به‌اندازه‌ای که پیوسته برسد، از آن امان ده.</p></section><section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاحْجُبْنِي عَنِ السَّرَفِ وَالِازْدِيَادِ، وَقَوِّمْنِي بِالْبَذْلِ وَالِاقْتِصَادِ، وَعَلِّمْنِي حُسْنَ التَّقْدِيرِ، وَاقْبِضْنِي بِلُطْفِكَ عَنِ التَّبْذِيرِ، وَأَجْرِ مِنْ أَسْبَابِ الْحَلَالِ أَرْزَاقِي، وَوَجِّهْ فِي أَبْوَابِ الْبِرِّ إِنْفَاقِي،</p><p class=\"fa\">خدایا، بر محمد و خاندانش درود فرست، و مرا از زیاده‌روی و افزون‌خواهی بازدار، و با بخشش و میانه‌روی استوارم کن، و اندازه‌نگه‌داشتنِ نیکو را به من بیاموز، و به لطف خود مرا از ریخت‌وپاش بازدار، و روزی‌هایم را از راه‌های حلال روان کن، و خرج کردنم را به سوی کارهای نیک بگردان.</p></section><section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">وَازْوِ عَنِّي مِنَ الْمَالِ مَا يُحْدِثُ لِي مَخِيلَةً، أَوْ تَأَدِّياً إِلَى بَغْيٍ، أَوْ مَا أَتَعَقَّبُ مِنْهُ طُغْيَاناً.</p><p class=\"fa\">و از مال آنچه را که در من خودپسندی پدید آورد، یا مرا به ستم بکشاند، یا در پی آن سرکشی ببینم، از من دور کن.</p></section><section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">اللّٰهُمَّ حَبِّبْ إِلَيَّ صُحْبَةَ الْفُقَرَاءِ، وَأَعِنِّي عَلَى صُحْبَتِهِمْ بِحُسْنِ الصَّبْرِ، وَمَا زَوَيْتَ عَنِّي مِنْ مَتَاعِ الدُّنْيَا الْفَانِيَةِ فَاذْخَرْهُ لِي فِي خَزَائِنِكَ الْبَاقِيَةِ،</p><p class=\"fa\">خدایا، هم‌نشینی با تهیدستان را محبوب من گردان، و مرا با شکیبایی نیکو بر هم‌نشینی‌شان یاری کن؛ و آنچه از کالای دنیای فانی را از من دور داشتی، برایم در گنجینه‌های ماندگارت ذخیره کن.</p></section><section class=\"pa\"><span class=\"n\">۷</span><p class=\"ar\">وَاجْعَلْ مَا خَوَّلْتَنِي مِنْ حُطَامِهَا، وَعَجَّلْتَ لِي مِنْ مَتَاعِهَا، بُلْغَةً إِلَى جِوَارِكَ، وَوُصْلَةً إِلَى قُرْبِكَ، وَذَرِيعَةً إِلَى جَنَّتِكَ، إِنَّكَ ذُو الْفَضْلِ الْعَظِيمِ، وَأَنْتَ الْجَوَادُ الْكَرِيمُ.</p><p class=\"fa\">و آنچه از مال ناچیز دنیا به من بخشیدی، و از کالایش زودتر به من دادی، توشه‌ای برای رسیدن به جوار خودت، و پیوندی به نزدیکی‌ات، و وسیله‌ای به سوی بهشتت قرار ده؛ که تو صاحب فضل بزرگی، و تو بخشندهٔ کریمی.</p></section>"}, {"id": "s49", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۴۹", "title": "دعا برای دفع نیرنگ دشمنان", "sub": "سپاس بر یاری خدا در برابر بدخواهان و حسودان", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي دِفَاعِ كَيْدِ الْأَعْدَاءِ، وَرَدِّ بَأْسِهِمْ</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) در دفع نیرنگ دشمنان و بازگرداندن آزارشان</p><div class=\"player\"><span>🔊 قرائت دعای ۴۹ (عربی)</span><audio controls preload=\"none\" src=\"audio/dua49.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">إِلَهِي هَدَيْتَنِي فَلَهَوْتُ، وَوَعَظْتَ فَقَسَوْتُ، وَأَبْلَيْتَ الْجَمِيلَ فَعَصَيْتُ، ثُمَّ عَرَفْتُ مَا أَصْدَرْتَ إِذْ عَرَّفْتَنِيهِ، فَاسْتَغْفَرْتُ فَأَقَلْتَ، فَعُدْتُ فَسَتَرْتَ، فَلَكَ إِلَهِي الْحَمْدُ.</p><p class=\"fa\">معبودا، مرا راه نمودی و من سرگرم [بازی] شدم، و پندم دادی و سخت‌دل شدم، و نیکی‌ات را به من نمودی و نافرمانی کردم؛ سپس چون به من شناساندی، آنچه را [از من] سر زده بود شناختم، و آمرزش خواستم و تو درگذشتی، و باز [به گناه] برگشتم و تو پوشاندی؛ پس معبودا، ستایش از آنِ توست.</p></section><section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">تَقَحَّمْتُ أَوْدِيَةَ الْهَلَاكِ، وَحَلَلْتُ شِعَابَ تَلَفٍ، تَعَرَّضْتُ فِيهَا لِسَطَوَاتِكَ، وَبِحُلُولِهَا عُقُوبَاتِكَ،</p><p class=\"fa\">خود را در دره‌های هلاکت انداختم، و در گذرگاه‌های نابودی فرود آمدم؛ گذرگاه‌هایی که در آنها خود را در معرض خشم تو، و با فرود آمدن در آنها در معرض کیفرهایت قرار دادم.</p></section><section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">وَوَسِيلَتِي إِلَيْكَ التَّوْحِيدُ، وَذَرِيعَتِي أَنِّي لَمْ أُشْرِكْ بِكَ شَيْئاً، وَلَمْ أَتَّخِذْ مَعَكَ إِلَهاً، وَقَدْ فَرَرْتُ إِلَيْكَ بِنَفْسِي، وَإِلَيْكَ مَفَرُّ الْمُسِيءِ، وَمَفْزَعُ الْمُضَيِّعِ لِحَظِّ نَفْسِهِ الْمُلْتَجِئِ.</p><p class=\"fa\">و وسیلهٔ من به سوی تو یکتاپرستی است، و دستاویزم این است که چیزی را شریک تو نساختم و همراه تو معبودی نگرفتم؛ و با همهٔ وجودم به سوی تو گریخته‌ام، و گریزگاه بدکار، و پناهگاه کسی که بهرهٔ خود را تباه کرده و پناه می‌جوید، به سوی توست.</p></section><section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">فَكَمْ مِنْ عَدُوٍّ انْتَضَى عَلَيَّ سَيْفَ عَدَاوَتِهِ، وَشَحَذَ لِي ظُبَةَ مُدْيَتِهِ، وَأَرْهَفَ لِي شَبَا حَدِّهِ، وَدَافَ لِي قَوَاتِلَ سُمُومِهِ، وَسَدَّدَ نَحْوِي صَوَائِبَ سِهَامِهِ، وَلَمْ تَنَمْ عَنِّي عَيْنُ حِرَاسَتِهِ، وَأَضْمَرَ أَنْ يَسُومَنِي الْمَكْرُوهَ، وَيُجَرِّعَنِي زُعَاقَ مَرَارَتِهِ،</p><p class=\"fa\">چه بسا دشمنی که شمشیر دشمنی‌اش را بر من کشید، و لبهٔ کاردش را برایم تیز کرد، و تیزی سلاحش را برایم برّنده ساخت، و زهرهای کشنده‌اش را برایم آمیخت، و تیرهای کارگرش را به سوی من نشانه رفت، و چشم مراقبتش از من نخوابید، و در دل داشت که مرا به ناخوشایندی گرفتار کند و آب تلخِ تلخی‌اش را جرعه‌جرعه به من بنوشاند.</p></section><section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">فَنَظَرْتَ يَا إِلَهِي إِلَى ضَعْفِي عَنِ احْتِمَالِ الْفَوَادِحِ، وَعَجْزِي عَنِ الِانْتِصَارِ مِمَّنْ قَصَدَنِي بِمُحَارَبَتِهِ، وَوَحْدَتِي فِي كَثِيرِ عَدَدِ مَنْ نَاوَانِي، وَأَرْصَدَ لِي بِالْبَلَاءِ فِيمَا لَمْ أُعْمِلْ فِيهِ فِكْرِي،</p><p class=\"fa\">پس معبودا، تو به ناتوانی‌ام از تحمل سختی‌های کمرشکن، و ناتوانی‌ام از دادخواهی از کسی که با جنگیدنش آهنگ من کرده بود، و تنهایی‌ام در برابر شمار بسیارِ کسانی که با من دشمنی کردند و با بلا در کمین من نشستند، از جایی که فکرم را در آن به کار نینداخته بودم، نگریستی.</p></section><section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">فَابْتَدَأْتَنِي بِنَصْرِكَ، وَشَدَدْتَ أَزْرِي بِقُوَّتِكَ، ثُمَّ فَلَلْتَ لِي حَدَّهُ، وَصَيَّرْتَهُ مِنْ بَعْدِ جَمْعٍ عَدِيدٍ وَحْدَهُ، وَأَعْلَيْتَ كَعْبِي عَلَيْهِ، وَجَعَلْتَ مَا سَدَّدَهُ مَرْدُوداً عَلَيْهِ،</p><p class=\"fa\">پس تو [بی‌آنکه بخواهم] با یاری‌ات آغاز کردی، و با نیرویت پشتم را محکم کردی؛ سپس تیزی‌اش را برایم کُند کردی، و او را پس از [داشتن] جمعیتی بسیار، تنها گذاشتی، و مرا بر او برتری دادی، و آنچه را نشانه گرفته بود به خودش بازگرداندی.</p></section><section class=\"pa\"><span class=\"n\">۷</span><p class=\"ar\">فَرَدَدْتَهُ لَمْ يَشْفِ غَيْظَهُ، وَلَمْ يَسْكُنْ غَلِيلُهُ، قَدْ عَضَّ عَلَى شَوَاهُ، وَأَدْبَرَ مُوَلِّياً قَدْ أَخْلَفَتْ سَرَايَاهُ.</p><p class=\"fa\">پس او را بازگرداندی، در حالی که خشمش فرو ننشسته و سوز درونش آرام نگرفته بود؛ از پشیمانی انگشت به دندان گزید، و پشت کرد و رفت، در حالی که دسته‌های سپاهش ناکام مانده بودند.</p></section><section class=\"pa\"><span class=\"n\">۸</span><p class=\"ar\">وَكَمْ مِنْ بَاغٍ بَغَانِي بِمَكَائِدِهِ، وَنَصَبَ لِي شَرَكَ مَصَائِدِهِ، وَوَكَّلَ بِي تَفَقُّدَ رِعَايَتِهِ، وَأَضْبَأَ إِلَيَّ إِضْبَاءَ السَّبُعِ لِطَرِيدَتِهِ، انْتِظَاراً لِانْتِهَازِ الْفُرْصَةِ لِفَرِيسَتِهِ، وَهُوَ يُظْهِرُ لِي بَشَاشَةَ الْمَلَقِ، وَيَنْظُرُنِي عَلَى شِدَّةِ الْحَنَقِ،</p><p class=\"fa\">و چه بسا ستمگری که با نیرنگ‌هایش بر من ستم کرد، و دام‌های شکارش را برایم گسترد، و مراقبت و پاییدنش را بر من گماشت، و مانند درنده‌ای که برای شکارش کمین می‌کند در کمین من نشست، به انتظار فرصت برای [گرفتن] شکارش؛ در حالی که به من روی خوشِ چاپلوسانه نشان می‌داد، و با کینه‌ای سخت به من می‌نگریست.</p></section><section class=\"pa\"><span class=\"n\">۹</span><p class=\"ar\">فَلَمَّا رَأَيْتَ يَا إِلَهِي، تَبَارَكْتَ وَتَعَالَيْتَ، دَغَلَ سَرِيرَتِهِ، وَقُبْحَ مَا انْطَوَى عَلَيْهِ، أَرْكَسْتَهُ لِأُمِّ رَأْسِهِ فِي زُبْيَتِهِ، وَرَدَدْتَهُ فِي مَهْوَى حُفْرَتِهِ،</p><p class=\"fa\">پس معبودا، که خجسته و والایی، چون فریبکاری درونش و زشتی آنچه در دل داشت را دیدی، او را با سر در گودالِ [دامِ] خودش سرنگون کردی، و در ژرفای چاهی که کنده بود بازگرداندی.</p></section><section class=\"pa\"><span class=\"n\">۱۰</span><p class=\"ar\">فَانْقَمَعَ بَعْدَ اسْتِطَالَتِهِ ذَلِيلاً فِي رِبَقِ حِبَالَتِهِ الَّتِي كَانَ يُقَدِّرُ أَنْ يَرَانِي فِيهَا، وَقَدْ كَادَ أَنْ يَحُلَّ بِي، لَوْلَا رَحْمَتُكَ، مَا حَلَّ بِسَاحَتِهِ.</p><p class=\"fa\">پس پس از گردن‌فرازی‌اش، خوار در بندهای همان دامی که گمان داشت مرا در آن ببیند، سرکوب شد؛ و اگر رحمت تو نبود، نزدیک بود آنچه بر سر او آمد بر سر من بیاید.</p></section><section class=\"pa\"><span class=\"n\">۱۱</span><p class=\"ar\">وَكَمْ مِنْ حَاسِدٍ قَدْ شَرِقَ بِي بِغُصَّتِهِ، وَشَجِيَ مِنِّي بِغَيْظِهِ، وَسَلَقَنِي بِحَدِّ لِسَانِهِ، وَوَحَرَنِي بِقَرْفِ عُيُوبِهِ، وَجَعَلَ عِرْضِي غَرَضاً لِمَرَامِيهِ، وَقَلَّدَنِي خِلَالاً لَمْ تَزَلْ فِيهِ، وَوَحَرَنِي بِكَيْدِهِ، وَقَصَدَنِي بِمَكِيدَتِهِ،</p><p class=\"fa\">و چه بسا حسودی که از [حسد] من، غصه گلوگیرش شد، و خشمش از من در گلویش ماند، و با تیزی زبانش مرا آزرد، و با بستن عیب‌های خودش به من کینه‌اش را بر من ریخت، و آبرویم را نشانهٔ تیرهایش کرد، و خصلت‌هایی را که همیشه در خودش بود به گردن من انداخت، و با نیرنگش بر من کینه ورزید، و با حیله‌اش آهنگ من کرد.</p></section><section class=\"pa\"><span class=\"n\">۱۲</span><p class=\"ar\">فَنَادَيْتُكَ يَا إِلَهِي مُسْتَغِيثاً بِكَ، وَاثِقاً بِسُرْعَةِ إِجَابَتِكَ، عَالِماً أَنَّهُ لَا يُضْطَهَدُ مَنْ أَوَى إِلَى ظِلِّ كَنَفِكَ، وَلَا يَفْزَعُ مَنْ لَجَأَ إِلَى مَعْقِلِ انْتِصَارِكَ، فَحَصَّنْتَنِي مِنْ بَأْسِهِ بِقُدْرَتِكَ.</p><p class=\"fa\">پس معبودا، تو را صدا زدم، در حالی که از تو فریاد می‌خواستم، و به زودی پاسخت اطمینان داشتم، و می‌دانستم کسی که به سایهٔ پناه تو درآید ستم‌دیده نمی‌ماند، و کسی که به دژ یاری تو پناه برد هراسان نمی‌شود؛ پس با قدرتت مرا از آزارش در امان داشتی.</p></section><section class=\"pa\"><span class=\"n\">۱۳</span><p class=\"ar\">وَكَمْ مِنْ سَحَائِبِ مَكْرُوهٍ جَلَّيْتَهَا عَنِّي، وَسَحَائِبِ نِعَمٍ أَمْطَرْتَهَا عَلَيَّ، وَجَدَاوِلِ رَحْمَةٍ نَشَرْتَهَا، وَعَافِيَةٍ أَلْبَسْتَهَا، وَأَعْيُنِ أَحْدَاثٍ طَمَسْتَهَا، وَغَوَاشِي كُرُبَاتٍ كَشَفْتَهَا،</p><p class=\"fa\">و چه بسا ابرهای ناخوشایندی که از من کنار زدی، و ابرهای نعمتی که بر من باراندی، و جوی‌های رحمتی که روان کردی، و عافیتی که بر من پوشاندی، و چشمِ پیشامدهای بدی که کور کردی، و پرده‌های اندوهی که کنار زدی.</p></section><section class=\"pa\"><span class=\"n\">۱۴</span><p class=\"ar\">وَكَمْ مِنْ ظَنٍّ حَسَنٍ حَقَّقْتَ، وَعَدَمٍ جَبَرْتَ، وَصَرْعَةٍ أَنْعَشْتَ، وَمَسْكَنَةٍ حَوَّلْتَ،</p><p class=\"fa\">و چه بسا گمان نیکی که تحقق بخشیدی، و تنگدستی‌ای که جبران کردی، و زمین‌خوردگی‌ای که [مرا از آن] برخیزاندی، و بیچارگی‌ای که دگرگون کردی.</p></section><section class=\"pa\"><span class=\"n\">۱۵</span><p class=\"ar\">كُلُّ ذَلِكَ إِنْعَاماً وَتَطَوُّلاً مِنْكَ، وَفِي جَمِيعِهِ انْهِمَاكاً مِنِّي عَلَى مَعَاصِيكَ، لَمْ تَمْنَعْكَ إِسَاءَتِي عَنْ إِتْمَامِ إِحْسَانِكَ، وَلَا حَجَزَنِي ذَلِكَ عَنِ ارْتِكَابِ مَسَاخِطِكَ،</p><p class=\"fa\">همهٔ اینها از سرِ نعمت‌بخشی و بزرگواری تو بود، و در همهٔ آن، من غرق در نافرمانی‌ات بودم؛ نه بدی من تو را از کامل کردن نیکی‌ات بازداشت، و نه این [نیکی تو] مرا از انجام آنچه تو را خشمگین می‌کند بازداشت.</p></section><section class=\"pa\"><span class=\"n\">۱۶</span><p class=\"ar\">لَا تُسْأَلُ عَمَّا تَفْعَلُ، وَلَقَدْ سُئِلْتَ فَأَعْطَيْتَ، وَلَمْ تُسْأَلْ فَابْتَدَأْتَ، وَاسْتُمِيحَ فَضْلُكَ فَمَا أَكْدَيْتَ،</p><p class=\"fa\">از آنچه می‌کنی بازخواست نمی‌شوی؛ و به راستی از تو خواسته شد و عطا کردی، و خواسته نشد و خود آغاز کردی، و بخشش تو طلب شد و دریغ نکردی.</p></section><section class=\"pa\"><span class=\"n\">۱۷</span><p class=\"ar\">أَبَيْتَ يَا مَوْلَايَ إِلَّا إِحْسَاناً وَامْتِنَاناً وَتَطَوُّلاً وَإِنْعَاماً، وَأَبَيْتُ إِلَّا تَقَحُّماً لِحُرُمَاتِكَ، وَتَعَدِّياً لِحُدُودِكَ، وَغَفْلَةً عَنْ وَعِيدِكَ،</p><p class=\"fa\">ای مولای من، تو جز نیکی و منت و بزرگواری و نعمت‌بخشی نخواستی، و من جز درافتادن به حریم‌هایت، و تجاوز از مرزهایت، و غفلت از هشدارهایت نخواستم.</p></section><section class=\"pa\"><span class=\"n\">۱۸</span><p class=\"ar\">فَلَكَ الْحَمْدُ إِلَهِي مِنْ مُقْتَدِرٍ لَا يُغْلَبُ، وَذِي أَنَاةٍ لَا يَعْجَلُ، هَذَا مَقَامُ مَنِ اعْتَرَفَ بِسُبُوغِ النِّعَمِ، وَقَابَلَهَا بِالتَّقْصِيرِ، وَشَهِدَ عَلَى نَفْسِهِ بِالتَّضْيِيعِ.</p><p class=\"fa\">پس معبودا، ستایش از آنِ توست؛ توانایی که شکست نمی‌خورد، و بردباری که شتاب نمی‌کند. این جایگاه کسی است که به فراوانی نعمت‌ها اعتراف کرده، و با کوتاهی با آنها روبه‌رو شده، و بر ضد خود به تباه کردن [آنها] گواهی داده است.</p></section><section class=\"pa\"><span class=\"n\">۱۹</span><p class=\"ar\">اللّٰهُمَّ فَإِنِّي أَتَقَرَّبُ إِلَيْكَ بِالْمُحَمَّدِيَّةِ الرَّفِيعَةِ، وَالْعَلَوِيَّةِ الْبَيْضَاءِ، وَأَتَوَجَّهُ إِلَيْكَ بِهِمَا أَنْ تُعِيذَنِي مِنْ شَرِّ كَذَا وَكَذَا،</p><p class=\"fa\">خدایا، پس من با [مقام] بلندِ محمدی و [مقام] روشنِ علوی به تو نزدیکی می‌جویم، و با آن دو به تو روی می‌آورم که مرا از شرّ فلان و فلان پناه دهی [در اینجا خواستهٔ خود را نام ببرید].</p></section><section class=\"pa\"><span class=\"n\">۲۰</span><p class=\"ar\">فَإِنَّ ذَلِكَ لَا يَضِيقُ عَلَيْكَ فِي وُجْدِكَ، وَلَا يَتَكَأَّدُكَ فِي قُدْرَتِكَ، وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ،</p><p class=\"fa\">زیرا این کار با توانگری‌ات بر تو تنگ نمی‌آید، و با قدرتت برایت دشوار نیست، و تو بر هر چیز توانایی.</p></section><section class=\"pa\"><span class=\"n\">۲۱</span><p class=\"ar\">فَهَبْ لِي يَا إِلَهِي مِنْ رَحْمَتِكَ وَدَوَامِ تَوْفِيقِكَ مَا أَتَّخِذُهُ سُلَّماً أَعْرُجُ بِهِ إِلَى رِضْوَانِكَ، وَآمَنُ بِهِ مِنْ عِقَابِكَ، يَا أَرْحَمَ الرَّاحِمِينَ.</p><p class=\"fa\">پس معبودا، از رحمتت و توفیق همیشگی‌ات چیزی به من ببخش که آن را نردبانی کنم که با آن به خشنودی‌ات بالا روم، و با آن از کیفرت ایمن شوم؛ ای مهربان‌ترین مهربانان.</p></section>"}, {"id": "s54", "color": "lapis", "eyebrow": "صحیفهٔ سجادیه · دعای ۵۴", "title": "دعا برای برطرف شدن اندوه‌ها", "sub": "گشایش غم و اندوه، با آیت‌الکرسی و سه قل", "body": "<p class=\"intro-ar\">وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي اسْتِكْشَافِ الْهُمُومِ</p><p class=\"intro-fa\">از دعاهای امام سجاد (ع) در درخواستِ برطرف شدن اندوه‌ها</p><div class=\"player\"><span>🔊 قرائت دعای ۵۴ (عربی)</span><audio controls preload=\"none\" src=\"audio/dua54.mp3\"></audio></div><section class=\"pa\"><span class=\"n\">۱</span><p class=\"ar\">يَا فَارِجَ الْهَمِّ، وَكَاشِفَ الْغَمِّ، يَا رَحْمٰنَ الدُّنْيَا وَالْآخِرَةِ وَرَحِيمَهُمَا، صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَافْرُجْ هَمِّي، وَاكْشِفْ غَمِّي،</p><p class=\"fa\">ای گشایندهٔ اندوه، و ای برطرف‌کنندهٔ غم، ای بخشایندهٔ دنیا و آخرت و مهربانِ هر دو، بر محمد و خاندان محمد درود فرست، و اندوهم را بگشا، و غمم را برطرف کن.</p></section><section class=\"pa\"><span class=\"n\">۲</span><p class=\"ar\">يَا وَاحِدُ يَا أَحَدُ يَا صَمَدُ، يَا مَنْ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُواً أَحَدٌ، اعْصِمْنِي وَطَهِّرْنِي، وَاذْهَبْ بِبَلِيَّتِي.</p><p class=\"fa\">ای یکتا، ای یگانه، ای بی‌نیاز، ای کسی که نزاده و زاده نشده و هیچ کس همتای او نیست، مرا نگاه دار و پاکم کن، و گرفتاری‌ام را ببر.</p></section><section class=\"pa\"><span class=\"n\">۳</span><p class=\"ar\">(وَاقْرَأْ آيَةَ الْكُرْسِيِّ وَالْمُعَوِّذَتَيْنِ وَقُلْ هُوَ اللّٰهُ أَحَدٌ، وَقُلْ:)</p><p class=\"fa\">(در اینجا آیت‌الکرسی، سورهٔ فلق، سورهٔ ناس و سورهٔ اخلاص را بخوان؛ سپس بگو:)</p></section><section class=\"pa\"><span class=\"n\">۴</span><p class=\"ar\">اللّٰهُمَّ إِنِّي أَسْأَلُكَ سُؤَالَ مَنِ اشْتَدَّتْ فَاقَتُهُ، وَضَعُفَتْ قُوَّتُهُ، وَكَثُرَتْ ذُنُوبُهُ، سُؤَالَ مَنْ لَا يَجِدُ لِفَاقَتِهِ مُغِيثاً، وَلَا لِضَعْفِهِ مُقَوِّياً، وَلَا لِذَنْبِهِ غَافِراً غَيْرَكَ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ،</p><p class=\"fa\">خدایا، از تو درخواست می‌کنم، درخواستِ کسی که نیازش سخت شده، و نیرویش سست گشته، و گناهانش بسیار شده؛ درخواستِ کسی که برای نیازش فریادرسی، و برای ناتوانی‌اش نیروبخشی، و برای گناهش آمرزنده‌ای جز تو نمی‌یابد؛ ای صاحب شکوه و بزرگواری.</p></section><section class=\"pa\"><span class=\"n\">۵</span><p class=\"ar\">أَسْأَلُكَ عَمَلاً تُحِبُّ بِهِ مَنْ عَمِلَ بِهِ، وَيَقِيناً تَنْفَعُ بِهِ مَنِ اسْتَيْقَنَ بِهِ حَقَّ الْيَقِينِ فِي نَفَاذِ أَمْرِكَ.</p><p class=\"fa\">از تو کاری می‌خواهم که هر کس آن را انجام دهد، به سبب آن دوستش بداری؛ و یقینی که هر کس با یقینِ راستین به روان بودن فرمانت به آن یقین کند، با آن سودش رسانی.</p></section><section class=\"pa\"><span class=\"n\">۶</span><p class=\"ar\">اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَاقْبِضْ عَلَى الصِّدْقِ نَفْسِي، وَاقْطَعْ مِنَ الدُّنْيَا حَاجَتِي، وَاجْعَلْ فِيمَا عِنْدَكَ رَغْبَتِي شَوْقاً إِلَى لِقَائِكَ، وَهَبْ لِي صِدْقَ التَّوَكُّلِ عَلَيْكَ.</p><p class=\"fa\">خدایا، بر محمد و خاندان محمد درود فرست، و جانم را در حالِ راستی بگیر، و نیازم را از دنیا ببُر، و از سرِ شوق به دیدارت، اشتیاقم را به آنچه نزد توست قرار ده، و توکلِ راستین بر خودت را به من ببخش.</p></section><section class=\"pa\"><span class=\"n\">۷</span><p class=\"ar\">أَسْأَلُكَ مِنْ خَيْرِ كِتَابٍ قَدْ خَلَا، وَأَعُوذُ بِكَ مِنْ شَرِّ كِتَابٍ قَدْ خَلَا، أَسْأَلُكَ خَوْفَ الْعَابِدِينَ لَكَ، وَعِبَادَةَ الْخَاشِعِينَ لَكَ، وَيَقِينَ الْمُتَوَكِّلِينَ عَلَيْكَ، وَتَوَكُّلَ الْمُؤْمِنِينَ عَلَيْكَ.</p><p class=\"fa\">از تو خیرِ سرنوشتی را که پیش‌تر نوشته شده می‌خواهم، و از شرّ سرنوشتی که پیش‌تر نوشته شده به تو پناه می‌برم. از تو ترسِ عبادت‌کنندگانت، و عبادتِ فروتنانت، و یقینِ توکل‌کنندگان بر تو، و توکلِ مؤمنان بر تو را می‌خواهم.</p></section><section class=\"pa\"><span class=\"n\">۸</span><p class=\"ar\">اللّٰهُمَّ اجْعَلْ رَغْبَتِي فِي مَسْأَلَتِي مِثْلَ رَغْبَةِ أَوْلِيَائِكَ فِي مَسَائِلِهِمْ، وَرَهْبَتِي مِثْلَ رَهْبَةِ أَوْلِيَائِكَ، وَاسْتَعْمِلْنِي فِي مَرْضَاتِكَ عَمَلاً لَا أَتْرُكُ مَعَهُ شَيْئاً مِنْ دِينِكَ مَخَافَةَ أَحَدٍ مِنْ خَلْقِكَ.</p><p class=\"fa\">خدایا، اشتیاقم را در درخواستم مانند اشتیاق دوستانت در درخواست‌هایشان، و بیمم را مانند بیم دوستانت قرار ده، و مرا در راه خشنودی‌ات به کاری بگمار که با آن، از ترس هیچ یک از آفریدگانت، چیزی از دینت را رها نکنم.</p></section><section class=\"pa\"><span class=\"n\">۹</span><p class=\"ar\">اللّٰهُمَّ هَذِهِ حَاجَتِي، فَأَعْظِمْ فِيهَا رَغْبَتِي، وَأَظْهِرْ فِيهَا عُذْرِي، وَلَقِّنِّي فِيهَا حُجَّتِي، وَعَافِ فِيهَا جَسَدِي.</p><p class=\"fa\">خدایا، این نیاز من است؛ پس اشتیاقم را در آن بزرگ گردان، و عذرم را در آن آشکار کن، و دلیلم را در آن به من بیاموز، و تنم را در آن سلامت دار.</p></section><section class=\"pa\"><span class=\"n\">۱۰</span><p class=\"ar\">اللّٰهُمَّ مَنْ أَصْبَحَ لَهُ ثِقَةٌ أَوْ رَجَاءٌ غَيْرُكَ، فَقَدْ أَصْبَحْتُ وَأَنْتَ ثِقَتِي وَرَجَائِي فِي الْأُمُورِ كُلِّهَا، فَاقْضِ لِي بِخَيْرِهَا عَاقِبَةً، وَنَجِّنِي مِنْ مُضِلَّاتِ الْفِتَنِ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ،</p><p class=\"fa\">خدایا، اگر کسی صبح کرده و تکیه‌گاه یا امیدی جز تو دارد، من صبح کرده‌ام در حالی که تو در همهٔ کارها تکیه‌گاه و امید منی؛ پس برایم به آنچه سرانجامش بهتر است حکم کن، و مرا از فتنه‌های گمراه‌کننده نجات ده؛ به رحمتت، ای مهربان‌ترین مهربانان.</p></section><section class=\"pa\"><span class=\"n\">۱۱</span><p class=\"ar\">وَصَلَّى اللّٰهُ عَلَى سَيِّدِنَا مُحَمَّدٍ رَسُولِ اللّٰهِ الْمُصْطَفَى، وَعَلَى آلِهِ الطَّاهِرِينَ.</p><p class=\"fa\">و درود خدا بر سرور ما محمد، فرستادهٔ برگزیدهٔ خدا، و بر خاندان پاکش.</p></section>"}, {"id": "sources", "color": "slate", "eyebrow": "پیوست", "title": "منابع و یادداشت‌ها", "sub": "", "body": "<ul class=\"tips\">\n<li><b>متن قرآن:</b> روایت حفص از عاصم، نسخهٔ مجمع ملک فهد (KFGQPC)، با خط عثمانی همان مجمع.</li>\n<li><b>صحیفهٔ سجادیه (دعای ۳ و ۳۹):</b> اعراب‌گذاری شده و واژه‌به‌واژه با متن «الصحیفة السجادیة الکاملة» در پیکرهٔ علمی OpenITI مقابله شده است. جز تفاوت‌های املایی، اختلافی پیدا نشد.</li>\n<li><b>استغفار امیرالمؤمنین (ع):</b> «دستور معالم الحکم»، قاضی قضاعی (درگذشتهٔ ۴۵۴ ق)، باب ۵، بند ۱۰. متن ۷۰بندیِ رایج در منبعی که بتوان با آن مقابله کرد پیدا نشد و در این کتاب نیامده است.</li>\n<li><b>ترجمه‌ها:</b> ترجمهٔ تازه، جمله‌به‌جمله و وفادار به متن. واژه‌های داخل [ ] در متن عربی نیست و فقط برای روشن شدن معنا آمده است.</li>\n<li><b>صوت:</b> قرائت قرآن با پیوند به Quran.com شنیده می‌شود (قاریان مشهور). برای دعای ۳ و ۳۹ صحیفه، پیوند به صفحهٔ همان دعا در duas.org گذاشته شده که فایل صوتی و ویدئوی قرائت دارد. برای استغفار امیرالمؤمنین قرائت ضبط‌شده‌ای پیدا نشد. ترجمهٔ فارسی خوانده‌شده با صدای انسان هم در منبعی که بتوان بررسی کرد پیدا نشد.</li>\n<li><b>یازده دعای دیگر صحیفه (۶، ۷، ۸، ۱۷، ۲۰، ۲۱، ۲۳، ۲۹، ۳۰، ۴۹، ۵۴):</b> متنِ بی‌اعراب از پیکرهٔ علمی OpenITI (الصحیفة السجادیة، نسخهٔ Shia001112) گرفته شد. اعراب را Claude گذاشته و متن اعراب‌دار را حرف‌به‌حرف با OpenITI مقابله کرده است؛ جز تفاوت‌های املایی (مانند «أسئلک/أسألک») و چند خطای آشکار تایپی در OpenITI، اختلافی نماند. چون اعراب از نسخهٔ چاپی کپی نشده، برای قرائت دقیق، متن را با صوت همان دعا هم بشنوید. ترجمه‌ها تازه و جمله‌به‌جمله است.</li><li><b>صوت این یازده دعا:</b> فایل‌هایی که خودتان از duas.org فرستادید.</li></ul>"}];